// WHICH COPY OF THIS FILE IS RUNNING, read from the ?v= the page loaded it
// with. Compared with what the server would send now, so a browser holding an
// old copy can notice and fix itself -- see keepCurrent() at the end.
const CLIENT_JS_V = (() => {
  try {
    const src = (document.currentScript && document.currentScript.src) || '';
    const m = src.match(/[?&]v=([0-9a-f]+)/);
    return m ? m[1] : '';
  } catch (e) { return ''; }
})();

const $ = s => document.querySelector(s);
// localStorage rather than sessionStorage so several tabs share one session --
// people work with the queue in one tab and QuickBooks or a report in another,
// and being asked to sign in per tab is friction with no security benefit.
// The idle deadline below is what actually ends the session.
const TOK_KEY = 'ys_tok';
const IDLE_KEY = 'ys_last_activity';
let TOKEN = localStorage.getItem(TOK_KEY) || '';
// hal_connected starts null, not false: false is a claim ("STH is not synced")
// and until a queue has actually loaded we have not asked. Rendering the header
// before then -- which the Card Accounts tab does -- raised the warning banner
// on a perfectly healthy sync.
let QUEUE = {items: [], hal_connected: null, bills_loaded: 0};
// Shown once a minute at most: a message that repeats on every page of
// results is noise rather than information.
let HALFILL_NOTED = false;
let RESCORE_NOTED = false;
let COUNTS = {for_review: 0, categorized: 0, excluded: 0, sources: []};
// WHERE you are (which tab, which screen) is per browser tab; WHO you are (the
// token, the device) is shared. Both used to live in localStorage, which is
// shared across every tab of the same origin -- so two tabs open on different
// screens fought over one value, and refreshing either one jumped it to
// whatever the other had touched last.
//
// sessionStorage is per browser tab and survives a refresh, which is exactly
// the scope view state wants. On a tab's FIRST load it inherits the
// localStorage value, so opening a new tab still lands where you left off; from
// then on the two are independent.
const VIEW_KEYS = ['ys_tab', 'ys_screen', 'ys_table_tab',
                   'ys_algotab', 'ys_tabletab', 'ys_setuptab'];
function viewGet(key) {
  try {
    const own = sessionStorage.getItem(key);
    if (own !== null) return own;
    return localStorage.getItem(key);      // first load in this browser tab
  } catch (e) { return null; }
}
function viewSet(key, value) {
  try {
    sessionStorage.setItem(key, value);
    // Still mirrored, so a brand-new tab opens where the last one was.
    localStorage.setItem(key, value);
  } catch (e) {}
}

// Restored from the last visit: a refresh should put you back where you were,
// not at the top of the queue.
// OPEN BILLS and ALL BILLS are the same grid: All Bills lists every bill in
// QuickBooks, open or paid.
function isBills() { return status_ === 'bills' || status_ === 'allbills'; }
const billScope = () => (status_ === 'allbills' ? 'all' : 'open');
let status_ = (() => {
  try {
    const t = viewGet('ys_tab');
    return ['for_review', 'categorized', 'excluded', 'bills', 'allbills'].includes(t)
      ? t : 'for_review';
  } catch (e) { return 'for_review'; }
})();
let SEL = new Set();   // reassigned by select-all
// Bills are selected separately from charges: they're a different list, and a
// selection carried across tabs would act on rows nobody meant.
let BILL_SEL = new Set();
let SORT = {by: 'date', dir: 'desc'};
let PAGE_OFFSET = 0;
// Separate fields rather than one box, same reasoning as the charge filters.
let BILL_FILTERS = {vendor: '', memo: '', date_from: '', date_to: '',
                    amt_min: '', amt_max: '', bal_min: '', bal_max: '', aging: '',
                    qbo_id: ''};
let LAST_CLICKED = null;      // for shift-click ranges
let FILTERS = {date_from: '', date_to: '', amt_min: '', amt_max: '',
               samt_min: '', samt_max: '', rules_applied: '',
               vendor: '', profile: '', last4: '', memo: '', cvendor: '',
               category: '', user: '', ts_from: '', ts_to: '', currency: '',
               qbo_id: '', order_no: ''};
let ME = {};
let CAN = {owner: false, invite: false, write: false};
let COMPANIES = [];    // owner-registered companies
let CATEGORIES = [];   // QBO expense/asset accounts
let VENDORS = [];      // QBO vendors

const esc = s => String(s ?? '').replace(/[&<>"]/g, c =>
  ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

// ALL COMPANIES: A ROW'S ACTION SENDS ITS OWN COMPANY. Screens listing every
// company key their rows "Company|id" (card and QuickBooks ids repeat between
// companies). When an action sends such a key with company "All Companies",
// it is split here: the company becomes the row's company and the value its
// own id -- so every existing action works, within that row's company.
function _splitAllCompanies(path, opts) {
  if (typeof COMPANIES === 'undefined' || !COMPANIES.length) return [path, opts];
  const names = new Set(COMPANIES.map(c => c.name));
  let found = '';
  const split = v => {
    const m = /^([^|]+)\|(.*)$/.exec(String(v));
    if (m && names.has(m[1])) { found = found || m[1]; return m[2]; }
    return v;
  };
  const body = opts && opts.body;
  if (body instanceof FormData && body.get('company') === ALL_COMPANIES) {
    const nb = new FormData();
    for (const [k, v] of body.entries()) nb.append(k, k === 'company' ? v : (typeof v === 'string' ? split(v) : v));
    if (found) { nb.set('company', found); opts = {...opts, body: nb}; }
  }
  const q = path.indexOf('?');
  if (q >= 0) {
    const u = new URLSearchParams(path.slice(q + 1));
    if (u.get('company') === ALL_COMPANIES) {
      let hit = '';
      for (const [k, v] of [...u.entries()]) {
        if (k === 'company') continue;
        const before = found; found = '';
        const nv = split(v);
        if (found) { u.set(k, nv); hit = hit || found; }
        found = before || found;
      }
      if (hit) { u.set('company', hit); path = path.slice(0, q + 1) + u.toString(); }
    }
  }
  return [path, opts];
}

let DL_TOKEN = '';
let LAST_API_AT = Date.now();
// A SCREEN OR TAB OVERTAKEN BY ANOTHER NEVER DRAWS. While a view loads, its
// reading requests carry the view's number; when a different view starts
// loading, the number moves on, and a reply to the old one is never handed
// back -- so the old view stops where it is instead of finishing late and
// drawing over the tab now showing. Writes (anything but GET) are never held
// back, and requests made after a view has loaded are not tagged at all.
let VIEW_GEN = 0;
let VIEW_LOADING = false;
let FEED_LOADING = 0;
// "UPDATING..." WHEREVER SOMETHING YOU DID IS STILL WORKING. Adding a card
// account or pressing Pull Now left the screen blank until it finished, as if
// nothing had happened. Every request goes through api(), so it is watched
// here: one started within a few seconds of a click or key press, and still
// running after a third of a second, shows a small spinner until every such
// request is done. The page's own background checks are not counted, and it
// stands aside while a full-screen loading spinner is already showing.
let _LAST_INPUT = 0, _USER_BUSY = 0, _USER_BUSY_T = null;
['pointerdown', 'keydown'].forEach(ev => document.addEventListener(ev, () => { _LAST_INPUT = Date.now(); }, true));
function _userBusy(on) {
  // THE SAME CIRCLE IN THE MIDDLE OF THE SCREEN as every other wait (withWait),
  // reading "Updating...". Not a pill at the top: that one showed on every
  // navigation change. Only ACTIONS count (see api()); opening screens has its
  // own spinner already.
  _USER_BUSY = Math.max(0, _USER_BUSY + (on ? 1 : -1));
  clearTimeout(_USER_BUSY_T);
  let el = document.getElementById('userBusy');
  if (_USER_BUSY > 0) {
    _USER_BUSY_T = setTimeout(() => {
      if (_USER_BUSY <= 0 || document.querySelector('.bigspin:not(#userBusy)')) return;
      if (!el) {
        el = document.createElement('div');
        el.id = 'userBusy';
        el.className = 'bigspin navwait';
        el.innerHTML = '<div class="cosub">Updating\u2026</div>';
        document.body.appendChild(el);
      }
      el.style.display = '';
    }, 330);
  } else if (el) el.remove();
}
async function api(path, opts = {}) {
  // An ACTION -- a save, a pull, adding something -- started by the person.
  const _action = opts.method && opts.method !== 'GET';
  // `inline`: the window shows its own progress, so no screen-wide circle.
  const _byUser = _action && !opts.inline && Date.now() - _LAST_INPUT < 4000;
  if (!_byUser) return _apiRun(path, opts);
  _userBusy(true);
  try { return await _apiRun(path, opts); } finally { _userBusy(false); }
}
async function _apiRun(path, opts = {}) {
  // The Bank Feed's own loads are exempt: it has its own guard (LOAD_SEQ) and
  // its own spinner, which an unanswered request would leave on screen.
  const _myView = (VIEW_LOADING && !FEED_LOADING && (!opts.method || opts.method === 'GET')) ? VIEW_GEN : null;
  if (typeof isAllCompanies === 'function' && isAllCompanies()) [path, opts] = _splitAllCompanies(path, opts);
  // THE FRESHEST SESSION any tab holds. Each tab kept its own copy; a tab left
  // in the background held one that expired, and its next request signed out
  // every tab -- the one being worked in too.
  try { const _t = localStorage.getItem(TOK_KEY); if (_t && TOKEN) TOKEN = _t; } catch (e) {}
  LAST_API_AT = Date.now();
  const r = await fetch(path, {
    ...opts,
    headers: {...(opts.headers || {}), ...(TOKEN ? {Authorization: 'Bearer ' + TOKEN} : {})}
  });
  // Any successful call extends the session, so someone working steadily is
  // never signed out mid-task.
  const fresh = r.headers.get('X-Refresh-Token');
  if (fresh) { TOKEN = fresh; localStorage.setItem(TOK_KEY, TOKEN); }
  // Overtaken by another view: never answered, so it draws nothing.
  if (_myView !== null && _myView !== VIEW_GEN) return new Promise(() => {});
  // The short download pass for export links (kept in memory only).
  const _dl = r.headers.get('X-Download-Token');
  if (_dl) DL_TOKEN = _dl;
  if (r.status === 401) { logout('Signed out — the session expired.'); throw new Error('session expired'); }
  if (!r.ok) {
    // Read the body as text first: a 500 from a proxy or an unhandled error
    // may not be JSON at all, and swallowing it leaves only "Internal Server
    // Error" with the real cause invisible in the browser.
    const raw = await r.text().catch(() => '');
    let msg = raw;
    // A BARE "Not Found" almost always means an empty path segment: a URL like
    // "/queue//counts", built when the company is blank. FastAPI matches no
    // route and answers 404, and the screen shows the word with no hint of
    // what to do about it. Say what actually happened.
    if (r.status === 404 && /\/\//.test(path)) {
      msg = 'No company is selected — pick one from the list at the top left.';
    }
    // The parsed body, kept on the error for callers that need more than a
    // sentence -- the rename that has to ask before merging reads a flag out
    // of it. Without this every caller would have to re-parse the text it was
    // handed, or the endpoint would have to encode its meaning into prose.
    let parsed = null;
    try {
      parsed = JSON.parse(raw);
      const d = parsed.detail;
      // A 422 detail is a list of field errors, and String(list) gives
      // "[object Object]" -- which is what was showing instead of the reason.
      msg = Array.isArray(d)
        ? d.map(x => `${(x.loc || []).slice(-1)[0] || ''}: ${x.msg || ''}`.trim()).join('; ')
        : (d || raw);
    } catch (e) {}
    console.error('API', r.status, path, raw);
    const _err = new Error(msg || `${r.status} ${r.statusText}`);
    _err.payload = parsed;
    _err.status = r.status;
    // The status code is for the log, not the reader. A 400 always carries a
    // sentence explaining itself; only fall back to the code when it doesn't.
    throw _err;
  }
  return r.json();
}

// --- auth ---
let PENDING_USER = '';
let UPLOAD_OVERRIDE = false;
const DEVICE_KEY = 'ys_device';

function showStep(n) {
  $('#step1').style.display = n === 1 ? 'block' : 'none';
  $('#step2').style.display = n === 2 ? 'block' : 'none';
  $('#step3').style.display = n === 3 ? 'block' : 'none';
  // Step 1 needs no caption -- the two fields say what to do. The others do.
  const sub = $('#lsub');
  if (sub) {
    sub.style.display = n === 1 ? 'none' : '';
    sub.textContent = n === 2 ? 'Two-factor verification' : 'Reset your password';
  }
}

async function login() {
  $('#lerr').textContent = '';
  const body = new URLSearchParams({
    username: $('#u').value.trim().toLowerCase(),
    password: $('#p').value,
    device: localStorage.getItem(DEVICE_KEY) || ''
  });
  try {
    const r = await fetch('/auth/login', {method: 'POST', body});
    if (!r.ok) throw new Error((await r.json().catch(() => ({}))).detail
                               || 'incorrect username or password');
    // ACCEPTED: the password is not kept in the page -- not while working, and
    // not waiting in the box after a sign-out.
    $('#p').value = '';
    const j = await r.json();
    if (j.twofa_required) {
      PENDING_USER = j.username;
      showStep(2);
      $('#lerr').textContent = j.email_sent ? '' : j.note;
      $('#code').focus();
      return;
    }
    TOKEN = j.access_token;
    localStorage.setItem(TOK_KEY, TOKEN);
    startIdleWatch(j.idle_minutes);
    JUST_SIGNED_IN = true;
    await start();
  } catch (e) { $('#lerr').textContent = e.message; }
}

async function verify2fa() {
  $('#lerr').textContent = '';
  const body = new URLSearchParams({
    username: PENDING_USER, code: $('#code').value.trim(),
    trust_device: $('#trust').checked ? 'true' : 'false'
  });
  try {
    const r = await fetch('/auth/verify-2fa', {method: 'POST', body});
    if (!r.ok) throw new Error((await r.json().catch(() => ({}))).detail || 'bad code');
    const j = await r.json();
    if (j.device) localStorage.setItem(DEVICE_KEY, j.device);
    TOKEN = j.access_token;
    localStorage.setItem(TOK_KEY, TOKEN);
    startIdleWatch(j.idle_minutes);
    showStep(1);
    JUST_SIGNED_IN = true;
    await start();
  } catch (e) { $('#lerr').textContent = e.message; }
}

// A failure while loading the app is NOT a failure to authenticate.
//
// This used to be `start().catch(logout)`, so any error at all -- a dropped
// request, a slow endpoint, a bug in one render step -- deleted the token from
// localStorage. Because localStorage is shared, that also fired the storage
// event in every other tab, which signed those out too with "Signed out in
// another tab." Duplicating a tab was just the easiest way to trip it.
//
// The token is now cleared only by a real 401 or an explicit sign-out.
// "Signed out — the session expired" belongs to the session it ended, not to
// the next sign-in hours later. It's shown once, then cleared, so coming back
// tomorrow gets a clean login screen.
function noteSignOut(msg) {
  SIGNOUT_NOTE = msg || '';
  const box = $('#lerr');
  if (box) box.textContent = SIGNOUT_NOTE;
}

function startupFailed(err) {
  if (err && err.message === 'session expired') return;   // api() handled it
  console.error('startup failed', err);
  const box = $('#lerr');
  $('#app').style.display = '';
  if (typeof showWarn === 'function') {
    showWarn('Could not finish loading',
             `<div>${esc(String(err && err.message || err))}</div>`
             + `<div style="margin-top:8px;color:var(--tx2)">`
             + `You are still signed in — reload to try again.</div>`);
  } else if (box) {
    box.textContent = String(err && err.message || err);
  }
}

// A stored token means a session that is probably still good, so the app frame
// shows immediately and the login screen stays hidden. Rendering login first
// and hiding it once /auth/me returned is what made it flash on every refresh;
// if the token turns out to be stale, logout() puts login back.
// The sign-in card and its backdrop are shown and hidden together. Five places
// toggled the card; adding a second element to each of them by hand is exactly
// how one gets missed and the dark ground is left behind the app.
function showLogin(on) {
  const l = document.getElementById('login');
  const b = document.getElementById('loginbg');
  if (l) l.style.display = on ? 'block' : 'none';
  if (b) b.style.display = on ? 'block' : 'none';
}

if (TOKEN) {
  // Run now if the document is already parsed. This script sits at the end of
  // the body, so DOMContentLoaded has usually fired by the time it runs and the
  // listener never called -- which is why login kept flashing.
  const hideLogin = () => showLogin(false);
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', hideLogin);
  } else {
    hideLogin();
  }
  // If the session turns out to be dead and nothing has taken over, put the
  // login screen back rather than leaving a blank page.
  setTimeout(() => {
    const a = document.getElementById('app');
    if (a && a.style.display !== 'block') showLogin(true);
  }, 6000);
} else {
  // No token at all: this IS the login screen, so show it straight away. The
  // stylesheet now starts it hidden, which is what stops it flashing on a
  // refresh that turns out to be signed in.
  const show = () => showLogin(true);
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', show);
  } else {
    show();
  }
}

function logout(msg) {
  // SIGNED OUT, for whatever reason: the sign-in boxes start empty (the
  // username stays, as a convenience; the password and code never do).
  ['#p', '#code', '#np', '#np2'].forEach(id => { const el = document.querySelector(id); if (el) el.value = ''; });
  // A NEW SESSION STARTS CLEAN.
  //
  // Filters and searches lived in memory and in the view store, so signing out
  // and back in restored the last session's narrowing -- on a shared machine,
  // somebody else's. A grid showing 300 of 29,000 rows for a reason nobody set
  // is indistinguishable from a broken grid.
  try {
    FILTERS = {date_from: '', date_to: '', amt_min: '', amt_max: '',
               samt_min: '', samt_max: '', rules_applied: '', currency: '', vendor: '',
               category: '', bank_detail: '', profile: '', last4: '',
               memo: '', user: '', ts_from: '', ts_to: '', q: '',
               qbo_id: '', order_no: ''};
    BILL_FILTERS = {vendor: '', memo: '', date_from: '', date_to: '',
                    amt_min: '', amt_max: '', bal_min: '', bal_max: '',
                    aging: ''};
    clearGridSearches();
    CARD_FIND = '';
    QREF_FIND = {account: '', vendor: ''};
    // THE INPUTS THEMSELVES, not just the state behind them.
    //
    // Signing out does not reload the page, so every filter box kept the text
    // it was holding. The state object was cleared, so the grid came back
    // unfiltered while the dialog still showed last session's values -- and
    // the Filters button lit up for a moment before settling. Two views of one
    // thing, disagreeing.
    for (const id of ['fdfrom', 'fdto', 'famin', 'famax', 'fsamin', 'fsamax',
                      'fcur', 'fven', 'fprof', 'fl4', 'fmemo', 'ftsfrom',
                      'ftsto', 'gridFind', 'cardFind', 'bven', 'bmemo',
                      'bdfrom', 'bdto', 'bamin', 'bamax', 'bbmin', 'bbmax',
                      'frules']) {
      const el = $('#' + id);
      if (el) el.value = '';
    }
    // THE VISIBLE GRID TOO, not only the state behind it.
    //
    // Signing out does not reload the page: the previous session's rows,
    // header, chips and highlighted Filters button stay in the DOM, hidden
    // behind the login screen. Signing back in reveals all of it for the
    // second or two before the first fetch returns -- so a new session opens
    // showing someone else's filtered grid, then blinks and corrects itself.
    //
    // Emptied here rather than on sign-IN, because at that point the stale
    // markup has already been shown.
    for (const id of ['list', 'colhead', 'pagerbar', 'gridicons', 'shown',
                      'pagenums', 'pageinfo', 'bulkn']) {
      const el = $('#' + id);
      if (el) { el.innerHTML = ''; delete el.dataset.tab; }
    }
    const _mf = $('#moreFilters');
    if (_mf) _mf.classList.remove('on');
    // The card-account and other multi-select buttons carry their own "on"
    // marker, which outlives the selection it described.
    for (const id of ['fcardBtn', 'ftypeBtn', 'fkindBtn', 'ftierBtn',
                      'fmatchBtn', 'fingestBtn', 'fuserBtn']) {
      const el = $('#' + id);
      if (el) el.classList.remove('on');
    }
    // And the two cell pickers, which show a label rather than an input value.
    for (const id of ['fcvenWrap', 'fcatWrap']) {
      const w = $('#' + id);
      const btn = w && w.querySelector('.cellsel');
      // The LABEL span, not the button's text: the button holds two spans
      // (value and chevron), and setting textContent would replace both --
      // leaving a picker with no arrow that never reopened.
      const lab = btn && btn.querySelector('.cs-v');
      if (lab) {
        lab.innerHTML = `<i style="color:var(--tx2)">Any ${
          id === 'fcvenWrap' ? 'vendor' : 'category'}</i>`;
      }
    }
    for (const k of Object.keys(MULTI || {})) {
      try { resetMulti(k); }
      catch (e) {}
    }
  } catch (e) {}

  TOKEN = ''; localStorage.removeItem(TOK_KEY);
  try { resetPrefsState(); } catch (e) {}
  clearInterval(window._idle);
  clearInterval(window._qwatch);
  $('#app').style.display = 'none';
  showLogin(true);
  showStep(1);
  // Guard against being used as a promise rejection handler: an Error here
  // would render as "[object Error]" and hide the real reason.
  noteSignOut(typeof msg === 'string' ? msg : '');
}

// Sliding session: /auth/me returns a fresh token, so an active person is
// never interrupted while an idle browser expires on its own.
// Poll for other people's changes. Only the counts are fetched; the rows are
// refetched only when something actually moved, so this stays cheap at 5s.
function startQueueWatch() {
  clearInterval(window._qwatch);
  window._qwatch = setInterval(async () => {
    if (!TOKEN || $('#app').style.display === 'none') return;
    if (document.hidden) return;                    // don't poll a hidden tab
    if (document.querySelector('dialog[open]')) return;   // not mid-edit
    // No company means "/queue//version", which matches no route and 404s --
    // silently, twelve times a minute, for as long as the dashboard is open.
    if (!company()) return;
    try {
      const v = await api(`/queue/${encodeURIComponent(company())}/version`);
      const sig = `${v.for_review}|${v.categorized}|${v.excluded}|${v.latest_change}`;
      if (window._qsig && window._qsig !== sig) {
        window._qsig = sig;
        // keep the person's selection, drop anything that's gone
        await load();
      } else {
        window._qsig = sig;
      }
    } catch (e) {}
  }, 5000);
}

function startIdleWatch(minutes) {
  clearInterval(window._idle);
  const idleMs = (minutes || 60) * 60000;

  // Activity is shared between tabs: working in any one keeps them all alive,
  // and stepping away from all of them signs out everywhere.
  // THROTTLED. localStorage.setItem is SYNCHRONOUS -- it blocks the main
  // thread -- and this was bound to `scroll`, which fires continuously while
  // you drag a grid. Scrolling a long list meant hundreds of blocking writes a
  // second, on the same thread that has to answer the scroll.
  //
  // The value only decides whether you have been idle for sixty minutes, so
  // recording it more than once every few seconds buys nothing.
  let _lastTouch = 0;
  const touch = () => {
    const now = Date.now();
    if (now - _lastTouch < 5000) return;
    _lastTouch = now;
    try { localStorage.setItem(IDLE_KEY, String(now)); } catch (e) {}
  };
  touch();
  // ACTIVITY is any of these -- and scrolling INSIDE a grid counts: grids
  // scroll in their own boxes, whose scroll never reached a page listener, so
  // reading down a long feed with the wheel counted as idle.
  ['click', 'keydown', 'wheel', 'pointerdown', 'pointermove', 'touchstart'].forEach(ev =>
    document.addEventListener(ev, touch, {passive: true}));
  document.addEventListener('scroll', touch, {passive: true, capture: true});

  window._idle = setInterval(async () => {
    const last = parseInt(localStorage.getItem(IDLE_KEY) || '0', 10);
    // ACTIVE BUT QUIET: someone working with nothing being asked of the
    // server (a long window open, the Dashboard) still has their session
    // renewed, at least every ten minutes.
    if (last && Date.now() - last < idleMs && Date.now() - LAST_API_AT > 10 * 60000 && !document.hidden) {
      try { await api('/auth/me'); } catch (e) {}
    }
    if (last && Date.now() - last > idleMs) {
      logout('Signed out after ' + (minutes || 60) + ' minutes of inactivity.');
      return;
    }
    if (!localStorage.getItem(TOK_KEY)) {      // signed out in another tab
      logout('Signed out in another tab.');
      return;
    }
    try {
      const me = await api('/auth/me');
      if (me.access_token) {
        TOKEN = me.access_token;
        localStorage.setItem(TOK_KEY, TOKEN);
      }
    } catch (e) {}
  }, 60000);
}

// Reflect sign-out from another tab immediately rather than up to a minute later.
window.addEventListener('storage', e => {
  if (e.key === TOK_KEY && !e.newValue && TOKEN) {
    logout('Signed out in another tab.');
  }
});

$('#go').onclick = login;
$('#p').addEventListener('keydown', e => { if (e.key === 'Enter') login(); });
$('#verify').onclick = verify2fa;
$('#code').addEventListener('keydown', e => { if (e.key === 'Enter') verify2fa(); });
$('#backToLogin').onclick = e => { e.preventDefault(); showStep(1); };
$('#out').onclick = () => logout();

$('#forgot').onclick = async e => {
  e.preventDefault();
  const u = $('#u').value.trim().toLowerCase();
  if (!u) { $('#lerr').textContent = 'enter your username first'; return; }
  try {
    const r = await fetch('/auth/forgot',
      {method: 'POST', body: new URLSearchParams({username: u})});
    const j = await r.json();
    $('#lerr').style.color = 'var(--tx2)';
    $('#lerr').textContent = j.note;
  } catch (e2) { $('#lerr').textContent = e2.message; }
};

// arriving from a reset/invite email link
(function () {
  const p = new URLSearchParams(location.search);
  if (p.get('reset') && p.get('u')) {
    showStep(3);
    $('#doreset').onclick = async () => {
      if ($('#np').value !== $('#np2').value) {
        $('#lerr').textContent = "passwords don't match"; return;
      }
      try {
        const r = await fetch('/auth/reset', {method: 'POST', body: new URLSearchParams({
          username: p.get('u'), token: p.get('reset'), new_password: $('#np').value})});
        if (!r.ok) throw new Error((await r.json()).detail);
        $('#lerr').style.color = 'var(--ok)';
        $('#lerr').textContent = 'Password set — you can sign in now.';
        history.replaceState({}, '', '/');
        setTimeout(() => { showStep(1); $('#lerr').textContent = ''; }, 2200);
      } catch (e3) { $('#lerr').textContent = e3.message; }
    };
  }
})();

// --- boot ---
// The company picker.
//
// Kept as its own function because the Companies tab changes this list --
// adding, renaming or retiring a company has to be reflected in the picker
// without a reload, and a rename in particular would otherwise leave the
// selector pointing at a name that no longer exists.
//
// The selection is preserved across a refresh where it still exists, so
// editing a company does not silently move you to a different one.
// THE STRENGTH BANDS, as edited in Algorithms > Strengths: names, starts and
// colors. Their pill colors are written as a stylesheet, so every pill drawn
// with class "t-<band>" -- in the grid, the % pills, filters, the Strengths
// grid -- takes the band's color.
let BANDS = [];
let BAND_LEVELS = [];
async function loadBands() {
  try {
    const j = await api('/match/bands');
    BANDS = j.bands || [];
    BAND_LEVELS = j.auto_levels || [];
  } catch (e) { return; }
  let st = document.getElementById('bandStyles');
  if (!st) { st = document.createElement('style'); st.id = 'bandStyles'; document.head.appendChild(st); }
  st.textContent = BANDS.map(b => `.t-${b.key}{background:${b.color};color:${b.text};box-shadow:none}`).join('\n');
  // The Strengths filter offers the bands that exist, highest first.
  if (typeof MULTI !== 'undefined' && MULTI.ftier) {
    const rest = MULTI.ftier.options.filter(([k]) => k === 'none' || k === '--' || String(k).startsWith('rec:'));
    MULTI.ftier.options = [...BANDS.map(b => [b.key, b.name]), ...rest];
  }
}

async function loadCompanies(role) {
  loadBands();
  // THE STORED COMPANY, falling back to whatever is already selected.
  //
  // This read only the <select>, which is empty on a fresh page -- so a
  // refresh rebuilt the list and selected Dashboard, no matter which company
  // you were in. The value that survives a reload is the stored one; the
  // live select only matters when this runs again later in the session, after
  // someone has changed it.
  let was = company();
  if (!was) {
    try { was = viewGet('ys_company') || ''; } catch (e) {}
  }
  let reg = {companies: []};
  try { reg = await api('/companies/registry'); } catch (e) {}
  COMPANIES = reg.companies || [];
  const sel = $('#company');
  if (!COMPANIES.length) {
    sel.innerHTML = '<option value="">— no companies set up —</option>';
    const list = $('#list');
    if (list) {
      list.innerHTML = '<div class="empty">No companies have been set up yet.'
        + (role === 'admin' ? ' Open <b>Configuration</b> to add one.'
                            : ' Ask an admin to add one.') + '</div>';
    }
    return;
  }
  // ENGINE DASHBOARD sits on top, and selecting it leaves whatever company you
  // are in. The picker is how you move between companies, so it is also the
  // natural way out of one -- a separate button somewhere else was a second
  // idea for the same job.
  sel.innerHTML = '<option value="">Dashboard</option>'
    // MULTI-COMPANY MODE, between two lines: a view across the companies --
    // neither the Dashboard nor one of them -- when there is more than one.
    // A thin divider line, with no gap above or below -- a disabled option of
    // dashes took a whole line of height. Browsers without dividers in a
    // picker simply leave it out.
    + (COMPANIES.length > 1
       ? '<hr>' + `<option value="${ALL_COMPANIES}">Multi-Company</option>` : '')
    + '<hr>'
    + COMPANIES.map(c => `<option>${esc(c.name)}</option>`).join('');
  sel.value = (was && (was === ALL_COMPANIES ? COMPANIES.length > 1
                       : COMPANIES.some(c => c.name === was))) ? was : '';
}

// The vendor and category pickers, for the company currently selected.
async function loadRefLists() {
  const co = encodeURIComponent(company());
  try {
    CATEGORIES = (await api(`/qbo/categories?company=${co}`)).categories || [];
  } catch (e) { CATEGORIES = []; }
  try {
    VENDORS = (await api(`/qbo/vendors?company=${co}`)).vendors || [];
  } catch (e) { VENDORS = []; }
}

// Coming back from the QuickBooks connect flow.
//
// The callback redirects here with the outcome in the address rather than
// printing it; this reads it, says so, and drops the parameters so a refresh
// does not repeat the message.
function noteConnectResult() {
  const p = new URLSearchParams(location.search);
  if (!p.get('connected')) return false;
  const note = p.get('note') || 'QuickBooks file connected';
  history.replaceState({}, '', location.pathname);
  setTimeout(() => flash(note), 400);
  return true;
}

async function start() {
  showLogin(false);
  // Decided before anything renders, and applied as a class straight away.
  // Setting it after the awaits meant the feed painted first and was then
  // replaced, which is the flash of For Review.
  let last = 'feed', lastTab = '';
  try {
    last = viewGet('ys_screen') || 'feed';
    lastTab = viewGet('ys_tab') || '';
  } catch (e) {}
  // EVERY screen, not a list of two. Algorithms, Configuration and the rest
  // were added later and never added here, so a refresh on any of them dropped
  // you back at the feed.
  // A COMPANY SCREEN NEEDS A COMPANY.
  //
  // Restoring the Bank Feed with no company selected builds "/queue//counts"
  // -- the empty segment collapses the path, FastAPI matches nothing, and the
  // screen shows the raw "Not Found" from the 404. That is exactly what
  // happens after closing the tab while on the dashboard and reopening: the
  // company is blank and the remembered screen is not.
  //
  // Home is in both scopes, so it is the safe landing.
  // Not 'audit': it works in both scopes, reading every company from the
  // dashboard.
  const COMPANY_SCREENS = new Set(['feed', 'cards', 'setup']);
  // THE STORED COMPANY, not the picker.
  //
  // company() reads the <select>, and loadCompanies() does not run until
  // further down this function -- so at this point the picker is always empty
  // and this guard fired on every refresh, wiping the remembered screen and
  // landing everyone on the Dashboard. The stored value is the one that
  // survives a reload, which is exactly what is being asked about here.
  let _savedCo = '';
  try { _savedCo = viewGet('ys_company') || ''; } catch (e) {}
  if (!_savedCo && (COMPANY_SCREENS.has(last) || lastTab === 'cards')) {
    last = 'home';
    lastTab = '';
    try { viewSet('ys_screen', 'home'); viewSet('ys_tab', ''); } catch (e) {}
  }

  if (last && last !== 'feed') {
    document.body.classList.add('screen-open');
  } else if (lastTab === 'cards') {
    document.body.classList.add('cards-open');
    // The markup marks For Review as current. Move the highlight now, or it
    // shows on For Review until the first render replaces it.
    litNav('#cardsBtn');
  }
  $('#app').style.display = 'block';
  // The markup marks For Review as current; move the highlight to whichever
  // tab was restored, or the nav disagrees with the grid.
  //
  // Card Accounts is a tab too, but it has no data-s and status_ falls back to
  // for_review for it -- so this line re-lit For Review a moment after the
  // early highlight had cleared it, which is the flash.
  if (lastTab !== 'cards') {
    document.querySelectorAll('nav button').forEach(b =>
      b.classList.toggle('on', b.dataset.s === status_));
  }
  const me = await api('/auth/me');
  ME = me;
  // Just the name. The role governs what's on screen -- the buttons a person
  // can't use aren't rendered -- so labeling it was telling them something
  // they could already see.
  setWho(me);
  // Capability flags rather than role checks scattered through the UI.
  CAN = {
    owner: me.role === 'owner',                       // QBO + companies
    invite: ['owner', 'admin'].includes(me.role),     // user management
    write: ['owner', 'admin', 'user'].includes(me.role),
  };
  $('#setupBtn').style.display = CAN.write ? '' : 'none';
  $('#brokerBtn').style.display = CAN.write ? '' : 'none';
  $('#cardsBtn').style.display = CAN.write ? '' : 'none';
  // The upload button lives in the grid toolbar, which is rebuilt on every
  // render -- it may not exist yet at boot, and is shown/hidden there instead.
  if (!CAN.write) {
    // The one role worth naming: without it, a missing Add button looks like a
    // bug rather than a permission.
    $('#who').innerHTML = esc(me.username) + '<br><b>view only</b>';
  }

  // company list comes from QuickBooks itself, so the names match what the
  // team sees in QBO rather than something typed here
  // Companies come from the admin-managed registry, so the selector, the
  // upload dialog and the stored data can never disagree about a name.
  await loadCompanies(me.role);
  // Coding options come from QuickBooks itself, so what a reviewer picks is
  // always a real account/vendor in the ledger.
  // The pickers are one company's chart of accounts and vendor list, so they
  // are refetched when the company changes -- see the company picker's
  // onchange. Fetching them once at boot was correct while there was only ever
  // one QuickBooks file behind them.
  await loadRefLists();

  await loadPrefs();     // column order, visibility and widths for this user
  // Every sign-in starts newest-first on date, whatever last session did.
  SORT = {by: 'date', dir: 'desc'};
  PAGE_OFFSET = 0;

  // SIGNING IN LANDS ON HOME. `last` is the screen this browser was on when it
  // was last used, which is the right answer for a reload and the wrong one
  // for a sign-in: arriving at whatever screen you happened to close on is
  // arriving somewhere arbitrary. Home is the front door and it is where the
  // front door leads.
  // Returning from the connect flow lands on Companies, which is where it
  // started and where the new file now has to be mapped.
  if (noteConnectResult()) {
    setScope('global');
    await showScreen('companies');
    startQueueWatch();
    return;
  }

  if (JUST_SIGNED_IN) {
    JUST_SIGNED_IN = false;
    // AND FORGET THE LAST COMPANY. The scope below is global, but the picker
    // is filled from the stored company -- so signing in showed the dashboard
    // navigation above a company's name, which is the same mismatch a refresh
    // used to produce. Signing in is starting; starting is the dashboard.
    try {
      viewSet('ys_company', '');
      viewSet('ys_screen', 'home');
      viewSet('ys_tab', '');
    } catch (e) {}
    const _sel = $('#company');
    if (_sel) _sel.value = '';
    // Global scope, not inside a company. Arriving straight in whichever
    // company happened to be first in the list is a choice made for you, and
    // on an engine serving several it is the wrong one about half the time.
    setScope('global');
    await showScreen('home');
    startQueueWatch();
    return;
  }

  // A RELOAD restores the scope as well as the screen. Without this a refresh
  // in the middle of coding threw you back to the landing page, which is the
  // right answer for a sign-in and the wrong one for pressing F5.
  //
  // BUT THE COMPANY DECIDES IT, not the saved value on its own. `ys_scope` and
  // `ys_company` are written separately, so they can disagree -- close the tab
  // on the dashboard with a stale 'company' scope and you come back to a
  // company's navigation above an empty picker, which is what kept happening.
  // There is only one honest answer to "am I inside a company": whether one is
  // selected.
  setScope(_savedCo ? 'company' : 'global');

  // Same list as the class above: every screen, not two of them.
  if (last && last !== 'feed') {
    await showScreen(last);
  } else if (lastTab === 'cards') {
    const fb = $('#feedBtn');
    if (fb) fb.classList.add('on');
    // The counts in the tab headers come from load(), which this path skips --
    // so fetch them directly, or the tabs come back with empty parentheses.
    try {
      // With no status the endpoint answers for For Review, so the card
      // picker showed For Review counts on every tab.
      COUNTS = await api(`/queue/${encodeURIComponent(company())}/counts`
                         + `?status=${encodeURIComponent(status_)}`
                         + (compFilter() ? `&companies=${encodeURIComponent(compFilter())}` : ''));
      renderHeader();
      renderCardPicker();
    } catch (e) {}
    await $('#cardsBtn').onclick();
  } else {
    const fb = $('#feedBtn');
    if (fb) fb.classList.add('on');
    await load();
  }
  checkCards();
  startQueueWatch();
}

// NO FALLBACK. This used to return 'Y&S Tickets' whenever the picker was
// empty, which was harmless while that was the only company and actively wrong
// afterwards: selecting Engine Dashboard sets the picker to "", so company()
// went on naming a real company, the "are we leaving?" branch never fired, and
// the dashboard came up with the last company's data and its navigation.
//
// Empty now means empty. Every caller that needs one is inside company scope,
// where the picker always holds a name.
// EVERY POP-UP WINDOW CLOSES WITH A RED X, top right. A window's own Cancel or
// Close button is hidden and the X presses it -- so whatever that button did
// (closing, answering "no", refreshing the grid behind) still happens, from
// one place, for every window, including ones redrawn while open.
(function closeWithX() {
  if (typeof HTMLDialogElement === 'undefined') return;
  const isClose = b => /^(cancel|close)$/i.test((b.textContent || '').trim());
  function decorate(d) {
    const own = [...d.querySelectorAll('button')].filter(b => !b.classList.contains('dlgX') && isClose(b));
    let x = d.querySelector(':scope > .dlgX');
    if (!own.length && !x) return;
    own.forEach(b => { b.style.display = 'none'; b.dataset.xhidden = '1'; });
    if (!x) {
      x = document.createElement('button');
      x.type = 'button';
      x.className = 'dlgX';
      x.setAttribute('aria-label', 'Close');
      x.title = 'Close';
      x.innerHTML = '&times;';
      d.prepend(x);
    }
    x.onclick = e => {
      e.preventDefault();
      const b = d.querySelector('button[data-xhidden]');
      if (b) b.click(); else d.close();
      // THE X ALWAYS CLOSES ITS WINDOW. Its Cancel could be wired to a stale
      // copy of the window (see below), leaving the X doing nothing. Closed
      // regardless -- unless Cancel opened a question of its own on top.
      setTimeout(() => {
        if (d.open && document.querySelectorAll('dialog[open]').length === 1) d.close();
      }, 250);
    };
  }
  function watch(d) {
    if (d.__xWatch) return;
    d.__xWatch = true;
    // A ONE-OFF WINDOW IS REMOVED WHEN IT CLOSES. Closed with Escape, a window
    // stayed in the page; the next one of its kind then had a twin, and code
    // finding its buttons by id (#atCancel, #atSave ...) wired the old, closed
    // one -- so the new window's X and Cancel did nothing. Windows with an id
    // are the page's own and reused, and stay.
    d.addEventListener('close', () => {
      if (!d.id) setTimeout(() => { if (!d.open && d.isConnected) d.remove(); }, 0);
    });
    new MutationObserver(() => decorate(d)).observe(d, {childList: true, subtree: true});
  }
  for (const m of ['showModal', 'show']) {
    const orig = HTMLDialogElement.prototype[m];
    HTMLDialogElement.prototype[m] = function (...a) {
      try { decorate(this); watch(this); } catch (e) { /* never block a window opening */ }
      try { if (typeof markFilterFields === 'function') setTimeout(markFilterFields, 0); } catch (e) {}
      return orig.apply(this, a);
    };
  }
})();

const company = () => $('#company').value || '';
// MULTI-COMPANY MODE: "All Companies" in the picker. The Bank Feed then shows
// every company this person can reach, each row acting within its own.
const ALL_COMPANIES = '__all__';
const isAllCompanies = () => company() === ALL_COMPANIES;
// The company a row belongs to: its own in Multi-Company, else the one
// selected.
const rowCompany = it => (it && it.company) || company();

// Which filters this tab can actually show.
//
// The values are KEPT when you leave a tab -- clearing them meant a careful
// filter was lost just by glancing at Categorized and coming back. They simply
// aren't applied where their control isn't visible, which is what stops an
// invisible filter narrowing a grid you can't see it on.
function filterAppliesHere(key) {
  if (key === 'cvendor' || key === 'category') return editableHere();
  if (key === 'user' || key === 'ts_from' || key === 'ts_to') return resolutionCols();
  if (key === 'cvendor') return resolutionCols();
  return true;
}

function activeFilters() {
  return Object.fromEntries(
    Object.entries(FILTERS).filter(([k, v]) => v && filterAppliesHere(k)));
}

let LOAD_SEQ = 0;
let BILL_KEEP_ORDER = null;   // bill ids in on-screen order, kept across the reload after an edit

// Coding a charge reloads the grid, and replacing the rows used to drop you at
// the top of the page -- so working down a long queue meant scrolling back to
// where you were after every single action. Position is now preserved by
// default; the callers that genuinely change what you're looking at (a tab, a
// page, a filter) opt out.
function _scrollState() {
  const g = $('#gridscroll');
  return {y: window.scrollY, x: g ? g.scrollLeft : 0};
}

function _restoreScroll(st, keep) {
  const g = $('#gridscroll');
  if (!keep) {
    // Top of the page AND top of the grid's own scroller. Resetting only the
    // window left a paged grid showing whatever row happened to be under the
    // old scroll position, so page 2 opened halfway down.
    //
    // Twice: once now, and once after the rows have painted. The new page can
    // be taller than the old one, and a scroll set before layout is undone by
    // it.
    const top = () => {
      window.scrollTo(0, 0);
      if (g) { g.scrollLeft = 0; g.scrollTop = 0; }
    };
    top();
    requestAnimationFrame(top);
    return;
  }
  // After the layout settles, so the target position still exists. The browser
  // clamps if the list is now shorter, which is the behavior you want when the
  // row you just resolved has left the queue.
  requestAnimationFrame(() => {
    window.scrollTo(0, st.y);
    if (g) g.scrollLeft = st.x;
  });
}

// "UPDATING GRID": the blue ring with its label above, over any grid that is
// being re-fetched after a filter changes.
//
// Started and stopped AROUND the load itself (see load and renderAuditRows),
// never inferred from when the rows happen to change. The first version
// watched for the result to arrive, and a watcher has ways to miss what it is
// waiting for; a try/finally does not -- it ends however the load ends.
//
// A counter, because a second filter change can start before the first
// finishes, and the ring must stay up until the LAST one lands. And a short
// delay before showing, so a fast answer does not flash it.
let _gridBusyN = 0;
let _gridBusyT = null;
function gridBusyStart(label = 'Updating Grid') {
  _gridBusyN++;
  if (!document.getElementById('gridBusy')) {        // put back if anything removed it
    const g = document.createElement('div');
    g.id = 'gridBusy'; g.className = 'bigspin navwait'; g.style.display = 'none';
    g.innerHTML = '<div class="cosub">Updating Grid</div>';
    document.body.appendChild(g);
  }
  const _lab = document.querySelector('#gridBusy .cosub');
  if (_lab) _lab.textContent = label;
  if (_gridBusyN === 1) {
    clearTimeout(_gridBusyT);
    _gridBusyT = setTimeout(() => {
      const el = $('#gridBusy');
      // A Bank Feed load whose screen has been left (Home opened meanwhile,
      // say) shows nothing.
      if (el && _gridBusyN > 0 && !(document.body.classList.contains('screen-open')
          && /Bank Feed|For Review|Categorized|Excluded|Open Bills|All Bills/.test(el.textContent))) el.style.display = 'flex';
    }, 250);
  }
}
function gridBusyEnd() {
  _gridBusyN = Math.max(0, _gridBusyN - 1);
  if (_gridBusyN === 0) {
    clearTimeout(_gridBusyT);
    const el = $('#gridBusy');
    if (el) el.style.display = 'none';
  }
}

// WHAT THE GRID IS FILTERED BY, as one comparable string. Sets are sorted so
// the same selection always reads the same.
function _sig(obj) {
  try {
    return JSON.stringify(obj, (k, v) => v instanceof Set ? [...v].sort() : v);
  } catch (e) { return ''; }
}
function feedFilterSig() {
  // "EVERYTHING" AND "NOT CHOSEN YET" ARE THE SAME FILTER. A company's card
  // selection starts empty and is filled with every card when its card list
  // arrives, a moment after the first load -- so the ring read that as a
  // filter change and appeared on nearly every company switch. Any picker with
  // all of its options ticked, or none chosen yet, is written as 'all'.
  const allCards = (COUNTS && COUNTS.sources) || [];
  const cards = (CARD_SEL.size === 0 || CARD_SEL.size >= allCards.length)
    ? 'all' : CARD_SEL;
  const multi = {};
  Object.entries(MULTI).forEach(([k, m]) => {
    try {
      const sel = m.get();
      const n = (m.options || []).length;
      multi[k] = (!sel || sel.size === 0 || (n && sel.size >= n)) ? 'all' : sel;
    } catch (e) { multi[k] = null; }
  });
  return _sig({f: FILTERS, b: BILL_FILTERS, c: cards, m: multi});
}
// ONLY A FILTER CHANGE GETS THE RING. Opening a screen or switching tabs is
// navigation, and it already has its own treatment; showing "Updating Grid"
// there too said the same thing twice, in a different style. So: same tab,
// same company, different filters -> the ring. Anything else -> not.
// Paging is neither, and does not show it either.
let _lastFeedAt = null;
async function load(opts = {}) {
  const place = `${company()}|${status_}`;
  const filt = feedFilterSig();
  const filtering = !!_lastFeedAt && _lastFeedAt.place === place
    && _lastFeedAt.filt !== filt;
  // SWITCHING TABS in the same company -- For Review to Categorized, say --
  // shows the ring too, named for the tab being loaded. It had no indicator at
  // all, so a slow tab looked like one that had failed to change.
  const sameCo = !!_lastFeedAt && _lastFeedAt.place.split('|')[0] === company();
  const tabSwitch = sameCo && _lastFeedAt.place !== place;
  _lastFeedAt = {place, filt};
  if ((!filtering && !tabSwitch) || document.body.classList.contains('screen-open')) return _loadFeed(opts);
  gridBusyStart(filtering ? 'Updating Grid'
    : `Loading ${(typeof TAB_LABEL !== 'undefined' && TAB_LABEL[status_]) || 'Grid'}`);
  try { return await _loadFeed(opts); } finally { gridBusyEnd(); }
}

// ONE LOAD AT A TIME FOR THE SAME THING. A company switch starts the Bank
// Feed loading behind Home; pressing Bank Feed while it was still running
// started a second, identical load that cancelled the first -- and in
// Multi-Company, where a load takes a while, every further press cancelled
// and restarted it again, so the grid seemed to need several clicks. A load
// for exactly what is already loading now waits for that one instead.
let _FEED_INFLIGHT = null;
function _feedKey() {
  return [company(), status_, feedFilterSig(), PAGE_OFFSET, ($('#fpage') || {}).value || ''].join('|');
}
async function _loadFeed(opts = {}) {
  const key = _feedKey();
  if (_FEED_INFLIGHT && _FEED_INFLIGHT.key === key) {
    // THE RING ONLY WHILE THE BANK FEED IS ON SCREEN: a load started in the
    // background (changing company, opening Home) put "Loading Bank Feed"
    // over Home or another screen.
    const empty = !(QUEUE.items || []).length && !document.body.classList.contains('screen-open');
    if (empty) gridBusyStart('Loading Bank Feed');
    try { return await _FEED_INFLIGHT.p; } finally { if (empty) gridBusyEnd(); }
  }
  const p = _loadFeedRun(opts);
  _FEED_INFLIGHT = {key, p};
  try { return await p; }
  finally { if (_FEED_INFLIGHT && _FEED_INFLIGHT.p === p) _FEED_INFLIGHT = null; }
}

async function _loadFeedRun(o = {}) {
  FEED_LOADING += 1;
  try { return await _loadFeedRun2(o); } finally { FEED_LOADING -= 1; }
}
async function _loadFeedRun2({keepScroll = true} = {}) {
  const _scroll = _scrollState();
  // Every load takes a ticket, and a response is only allowed to paint if its
  // ticket is still the current one.
  //
  // Without this, loads race. The 5-second queue watcher fires a load, you
  // click Categorized which fires another, and whichever the network returns
  // LAST wins -- so the Categorized tab paints with For Review rows. It only
  // showed up right after resolving a charge because that is exactly when the
  // watcher notices a change and starts a competing load.
  const seq = ++LOAD_SEQ;
  const stale = () => seq !== LOAD_SEQ;
  // The selection survives a refresh, minus anything that is no longer in the
  // result -- resolved by someone else, or filtered out. Clearing it outright
  // meant that with two people working the queue, every action by one wiped the
  // other's checkboxes within five seconds. Pruning gives the same protection
  // (you can never act on a row you cannot see) without the interruption.
  LAST_CLICKED = null;
  // Only blank the grid when there is nothing to look at yet. Wiping it on
  // every refresh made the whole page flash empty each time a charge was
  // coded; leaving the old rows up until the new ones arrive is both calmer
  // and more honest, since they were accurate a moment ago.
  if (!(QUEUE.items || []).length) {
    $('#list').innerHTML = '';   // the centerd spinner says this now
  } else {
    $('#list').style.opacity = '.55';
  }
  const per = $('#fpage').value;
  try {
    // Deliberately unfiltered. These are the totals in the tab headers and the
    // card picker, and they're the fixed reference you filter AGAINST -- a
    // count that moves with the filters can't tell you what you're not seeing.
    // Unfiltered except for the tab: the per-tab totals in the header come
    // back grouped regardless, but the per-card counts are answered for
    // whichever status is asked for.
    const cp = new URLSearchParams({status: status_});
    const counts_ = await api(`/queue/${encodeURIComponent(company())}/counts`
                       + (cp.toString() ? '?' + cp : ''));
    if (stale()) return;
    COUNTS = counts_;

    // Seed the card selection the moment we know what the sources are. This
    // used to happen inside renderCardPicker, which runs AFTER the "nothing
    // ticked" check below -- so the very first load bailed out with an empty
    // grid while the button already read "All Cards (381)".
    // No seeding: an empty card selection means every card (see
    // renderCardPicker), so there is nothing to fill in before the first load.
    CARD_INIT = true;

    if (isBills()) {
      const bp = new URLSearchParams({limit: per, offset: PAGE_OFFSET,
        sort: SORT.by === 'vendor' ? 'vendor' : SORT.by, direction: SORT.dir, scope: billScope()});
      Object.entries(BILL_FILTERS).forEach(([k, v]) => { if (v) bp.set(k, v); });
      // THE QUICK SEARCH searches Open Bills too -- it was kept but never sent.
      if (FILTERS.q) bp.set('q', FILTERS.q);
      if (compFilter()) bp.set('companies', compFilter());
      const b = await api(`/bills/${encodeURIComponent(company())}?` + bp);
      if (stale()) return;
      // AN EDITED BILL STAYS WHERE IT WAS. After an edit, the bills already on
      // screen keep their order (BILL_KEEP_ORDER, set by the edit); the
      // reload used to resort them, and the bill just edited jumped.
      let _bills = b.bills || [];
      if (BILL_KEEP_ORDER) {
        const pos = new Map(BILL_KEEP_ORDER.map((id, i) => [id, i]));
        _bills = _bills.slice().sort((x, y) => (pos.has(x.bill_id) ? pos.get(x.bill_id) : 1e9)
                                               - (pos.has(y.bill_id) ? pos.get(y.bill_id) : 1e9));
        BILL_KEEP_ORDER = null;
      }
      QUEUE = {items: _bills, total: b.total,
               bills_loaded: billScope() === 'all' ? (QUEUE && QUEUE.bills_loaded) : b.total,
               hal_connected: true, mode: 'bills'};
      // THE CLASS FILTER'S CHOICES: the Classes on this company's bills.
      try {
        MULTI.bclass.options = [['__none', 'No Class'], ...((b.classes || []).map(c => [c, c]))];
        renderMulti('bclass');
      } catch (e) {}
      // Bills aren't charges -- nothing here can be excluded or deleted.
      $('#purgeBtn').style.display = 'none';
      renderHeader(); renderCardPicker(); renderTypePicker(); renderActiveFilters();
      renderPage(); renderBills();
      _restoreScroll(_scroll, keepScroll);
      return;
    }

    // Nothing ticked is every card, so no card filter is sent at all; ticked
    // cards narrow to those.
    const _allN = (COUNTS.sources || []).length;
    const card = (CARD_SEL.size && CARD_SEL.size < _allN)
      ? [...CARD_SEL].join(',') : '';
    const p = new URLSearchParams({status: status_, limit: per,
      offset: PAGE_OFFSET, sort: SORT.by, direction: SORT.dir});
    if (card) p.set('card', card);
    if (compFilter()) p.set('companies', compFilter());
    Object.entries(activeFilters()).forEach(([k, v]) => p.set(k, v));
    Object.entries(MULTI_PARAM).forEach(([key, param]) => {
      if (!MULTI[key].tabs.includes(status_)) return;
      let v = multiValue(key);
      if (key === 'ftier' && v) {
        // The Records half of this picker is a different question, so it goes
        // out as its own parameter rather than as a strength the server has
        // never heard of.
        const parts = v.split(',');
        const recs = parts.filter(x => x.startsWith('rec:'))
                          .map(x => x.slice(4));
        v = parts.filter(x => !x.startsWith('rec:')).join(',');
        // Both ticked is the same as asking nothing, so it is not sent.
        if (recs.length === 1) p.set('record', recs[0]);
      }
      if (v) p.set(param, v);
    });
    await loadStatusWords();
    const q_ = await api(`/queue/${encodeURIComponent(company())}?` + p.toString());
    if (stale()) return;
    QUEUE = q_;
    // A background rescore is running because the Rules Applied filter asked
    // for one. Said out loud: without it the first result can be a few rows
    // short and there is nothing on screen to explain why.
    // STH RECORDS NOT YET LOOKED UP are being looked up in the background for
    // the Records filter: said once, so a short list has a reason.
    if (q_ && q_.checking_records && !HALFILL_NOTED) {
      HALFILL_NOTED = true;
      flash(`Looking up STH records for ${Number(q_.checking_records).toLocaleString()} charge(s) not yet checked \u2014 reload in a minute for the full list`);
      setTimeout(() => { HALFILL_NOTED = false; }, 60000);
    }
    if (q_ && q_.rescoring && !RESCORE_NOTED) {
      RESCORE_NOTED = true;
      flash('Checking which charges rules apply to — reload in a moment for '
            + 'the complete list');
      setTimeout(() => { RESCORE_NOTED = false; }, 60000);
    }
  } catch (e) {
    if (stale()) return;   // a superseded request's error isn't worth showing
    $('#list').innerHTML = `<div class="empty" style="text-align:left;
      white-space:pre-wrap;user-select:text;font-family:monospace;font-size:12px;
      color:var(--bad);padding:16px">${esc(e.message)}</div>`;
    return;
  }
  $('#purgeBtn').style.display = 'none';   // shown by updateBulk once rows are picked
  // a charge someone else resolved is no longer in this view -- drop it from
  // the selection rather than acting on it later
  // Drop anything that didn't come back before rendering.
  const present = new Set((QUEUE.items || []).map(r => r.id));
  [...SEL].forEach(id => { if (!present.has(id)) SEL.delete(id); });
  setBandsHidden(BANDS_HIDDEN);   // also measures
  renderHeader();
  renderCardPicker();
  renderTypePicker();
  renderActiveFilters();
  renderPage();
  $('#vendorlist').innerHTML = VENDORS.map(v => `<option value="${esc(v.name)}">`).join('');
  $('#catlist').innerHTML = CATEGORIES.map(c =>
    `<option value="${esc(c.fully_qualified || c.name)}">`).join('');
  render();
  _restoreScroll(_scroll, keepScroll);
}

// --- bill editing --------------------------------------------------------

function renderBillBulk() {
  const bar = $('#billbulk');
  if (!bar) return;
  bar.style.display = BILL_SEL.size ? 'inline-flex' : 'none';
  const _txt = BILL_SEL.size
    // QUEUE.total, not QUEUE.bills. There is no `bills` key -- on this tab the
    // bills ARE QUEUE.items and the count is QUEUE.total -- so this read an
    // undefined property, took its length as 0, and rendered "5 of 0".
    ? `${BILL_SEL.size} of ${QUEUE.total || (QUEUE.items || []).length} selected`
    : '';
  setSelectionCount(_txt);

  // Batch Actions is a dialog about doing one thing to several bills, so it
  // has nothing to say about one. Deleting a single bill needs no dialog.
  // KEPT HIDDEN. Split and Delete are in the Action column on every row, so
  // these duplicated them a few centimeters away and only once something was
  // ticked. Setting .style.display here is also what defeated the
  // `display:none !important` in the markup -- assigning the property drops
  // the priority flag, so the "fix" in the markup was undone on every render.
  $('#billSplitOne').style.display = 'none';
  $('#billDeleteOne').style.display = 'none';
  // Never shown here: the toolbar button is the one on screen, and this stays
  // only because its handler is where the dialog is wired.
  $('#billBatch').style.display = 'none';
  // Keep the toolbar button in step with the bills selection.
  try { updateBulk(); } catch (e) {}
}

// --- 8: the bills bar belongs to the Bills tab and nothing else -------------
//
// It used to be shown by renderBills and hidden by nobody, so it survived a
// move to For Review and offered bill actions over a grid of charges.
function hideBillBulk() {
  const bar = $('#billbulk');
  if (bar) bar.style.display = 'none';
}

// The same floating picker the charge grids use, not a modal -- a bill's
// vendor is the same kind of edit as a charge's, and it should feel like one.
function openBillVendorPicker(btn) {
  openPicker(btn, {
    list: () => VENDORS.map(v => v.name || v),
    onPick: name => applyBillEdit([btn.dataset.id], {vendor: name}),
    canCreate: 'vendor',
  });
}

// "What should the amount become" has three answers, and they are not the same
// question -- a flat correction, a fixed adjustment, and a proportional one.
function billAmountDialog(ids) {
  const box = $('#billamt');
  const _b = ids.length === 1 ? (QUEUE.items || []).find(x => String(x.bill_id) === String(ids[0])) : null;
  // THE BILL'S DETAILS ON ONE LINE, its QBO memo on the next.
  const _kv = ([k, v]) => `<span style="margin-right:14px;white-space:nowrap;display:inline-block"><b>${k}</b>
           <span>${esc(v || '\u2014')}</span></span>`;
  $('#billamtWho').innerHTML = _b
    ? `<div style="white-space:nowrap">${[['Bill No.', _b.bill], ['Vendor', _b.vendor], ['Date', fmtDate(_b.date || '')],
        ['Amount', fmtAmt(_b.amt)]].map(_kv).join('')}</div>
       <div style="margin-top:2px">${_kv(['Memo', _b.memo]).replace('white-space:nowrap;', '')}</div>`
    : `<b>${ids.length} selected bills</b>`;
  $('#billamtValue').value = '';
  $('#billamtMode').value = 'set';
  // CASE BY CASE: no company setting -- the window starts on changing the
  // amount, and an Other Fees line is chosen here when a bill calls for it.
  document.querySelectorAll('input[name="billamtHow"]').forEach(r => { r.checked = r.value === 'amount'; });
  const hint = () => {
    const m = $('#billamtMode').value;
    // CAD TO USD and VENDORS OPEN need no figure: the rate on each bill's own
    // date, and each bill's open balance.
    const noValue = m === 'cad' || m === 'vendors_open';
    $('#billamtValueLbl').style.display = noValue ? 'none' : '';
    $('#billamtValueRow').style.display = noValue ? 'none' : 'flex';
    // CAD TO USD only ever changes the amount: no Other Fees choice.
    $('#billamtHowBox').style.display = (m === 'vendors_open' || m === 'cad') ? 'none' : '';
    $('#billamtHint').textContent = m === 'set' ? 'The new total for each bill.'
      : m === 'cad' ? 'Each bill\u2019s amount times the CAD to USD rate on the bill\u2019s date (e.g. $100 becomes $73.51).'
      : m === 'vendors_open' ? 'Adds a negative \u201cDue from Vendors - Open\u201d line for each bill\u2019s open balance, so its balance comes to zero. The new line carries the first line\u2019s memo.'
      : 'Positive for increase. Negative for decrease.';
    // The unit belongs next to the number, not only in the sentence below it.
    $('#billamtUnit').textContent = m === 'percent' ? '%' : '$';
  };
  $('#billamtMode').onchange = hint;
  hint();
  $('#billamtGo').onclick = async () => {
    const _m = $('#billamtMode').value;
    const v = (_m === 'cad' || _m === 'vendors_open') ? '0' : $('#billamtValue').value.trim();
    if (!v) return;
    box.close();
    const how = _m === 'cad' ? 'amount'
      : (document.querySelector('input[name="billamtHow"]:checked') || {}).value || 'amount';
    await applyBillEdit(ids, {amount_mode: $('#billamtMode').value,
                              amount_value: v, amount_how: how});
  };
  $('#billamtCancel').onclick = () => box.close();
  box.showModal();
  setTimeout(() => $('#billamtValue').focus(), 0);
}

async function applyBillEdit(ids, fields) {
  const fd = new FormData();
  fd.append('bill_ids', ids.join(','));
  Object.entries(fields).forEach(([k, v]) => fd.append(k, v));
  try {
    const r = await api('/bills/edit', {method: 'POST', body: fd});
    BILL_SEL.clear();
    BILL_KEEP_ORDER = (QUEUE.items || []).map(x => x.bill_id);
    await load();
    if (r.failed.length) {
      // Named individually: "3 failed" tells nobody which bill to go and look at.
      notify(`${r.updated} updated. ${r.failed.length} could not be:<br><br>`
             + r.failed.slice(0, 6)
                 .map(f => `<b>${esc(f.bill)}</b> — ${esc(f.error)}`).join('<br>'), 'Partly done', {html: true});
    } else {
      flash(r.updated === 1 ? 'Bill updated' : `${r.updated} bills updated`);
    }
  } catch (e) {
    notify(e.message, 'Could not update');
  }
}

$('#billSetVendor').onclick = async () => {
  const chosen = await pickFromList('Update Vendor', VENDORS.map(v => v.name || v),
                                    {confirmLabel: 'Update'});
  if (chosen === null) return;
  await applyBillEdit([...BILL_SEL], {vendor: chosen});
};
$('#billSetAmount').onclick = () => billAmountDialog([...BILL_SEL]);
// The one action in the app that cannot be reversed, so the confirm says so
// plainly rather than asking "are you sure".
async function billDelete(ids) {
  if (!ids.length) return;
  const go = await askConfirm('Delete bills',
    `Delete <b>${ids.length}</b> bill(s) from QuickBooks? `
    + `<b>This can not be undone.</b>`
    + `<br><br>Any bill with a payment against it will be refused rather than `
    + `deleted.`,
    'Delete', 'Cancel');
  if (!go) return;
  const fd = new FormData();
  fd.append('company', company());
  fd.append('bill_ids', ids.join(','));
  try {
    const r = await api('/bills/delete', {method: 'POST', body: fd});
    BILL_SEL.clear();
    await load();
    if ((r.refused || []).length) {
      notify(`${(r.deleted || []).length} deleted. `
             + `${r.refused.length} refused:<br><br>`
             + r.refused.slice(0, 6).map(esc).join('<br>'), 'Partly done', {html: true});
    } else {
      flash(`${(r.deleted || []).length} bill(s) deleted`);
    }
  } catch (e) { notify(e.message, 'Could not delete'); }
}

// Checked here as well as on the server: one vendor is the rule that decides
// whether the merge is possible at all, and finding out after a round trip is
// worse than not offering it.
// The vendor check runs here as well as on the server: one vendor is what
// decides whether the merge is possible at all, and finding out after a round
// trip is worse than not offering it.
let MERGE_KEEP = null;

async function billMerge(ids) {
  const rows = (QUEUE.items || []).filter(b => ids.includes(b.bill_id));
  if (rows.length < 2) {
    notify('Select at least two bills to merge.', 'Nothing to merge');
    return;
  }
  const vendors = [...new Set(rows.map(b => (b.vendor || '').trim()))];
  if (vendors.length > 1) {
    notify('Update the bills to be the same vendor before merging.',
           'Different vendors');
    return;
  }
  // Defaults to the largest, which is usually the one that is actually right,
  // but nothing depends on that guess -- it is a radio button, not a rule.
  MERGE_KEEP = rows.reduce((a, b) =>
    (Number(b.amt) || 0) > (Number(a.amt) || 0) ? b : a).bill_id;

  const draw = () => {
    $('#mergeList').innerHTML = rows.map(b => `
      <label style="display:flex;gap:8px;align-items:baseline;padding:5px 6px;
             border-radius:6px;font-size:13px;cursor:pointer;
             ${b.bill_id === MERGE_KEEP
               ? 'background:#e8eefc;border:1px solid var(--accent)'
               : 'border:1px solid transparent'}">
        <input type="radio" name="mergeKeep" value="${esc(b.bill_id)}"
               ${b.bill_id === MERGE_KEEP ? 'checked' : ''} style="width:auto">
        <span style="flex:1;min-width:0">
          <b>${esc(b.bill || b.bill_id)}</b> · ${fmtAmt(b.amt)} · ${fmtDate(b.date)}
          ${b.memo ? '<br><span style="color:var(--tx2);font-size:12px">'
                     + esc(b.memo) + '</span>' : ''}
        </span>
        <span style="font-size:11px;font-weight:600;color:${
          b.bill_id === MERGE_KEEP ? 'var(--accent)' : 'var(--bad)'}">
          ${b.bill_id === MERGE_KEEP ? 'KEEP' : 'DELETE'}</span>
      </label>`).join('');
    $('#mergeList').querySelectorAll('input[name="mergeKeep"]')
      .forEach(r => r.onchange = () => { MERGE_KEEP = r.value; draw(); });
  };
  draw();
  $('#billmerge').showModal();

  $('#mergeCancel').onclick = () => $('#billmerge').close();
  $('#mergeGo').onclick = async () => {
    $('#billmerge').close();
    const fd = new FormData();
    fd.append('company', company());
    fd.append('keep_id', MERGE_KEEP);
    fd.append('drop_ids', ids.filter(i => i !== MERGE_KEEP).join(','));
    try {
      const r = await api('/bills/merge', {method: 'POST', body: fd});
      BILL_SEL.clear();
      await load();
      if ((r.stuck || []).length) {
        notify(`Bill ${esc(r.doc_number)} is now ${fmtAmt(r.amount)}, but `
               + `${r.stuck.length} of the originals could not be deleted and `
               + `are still in QuickBooks:<br><br>`
               + r.stuck.slice(0, 5).map(esc).join('<br>')
               + `<br><br>The amount is on both — remove them there.`,
               'Merged, with leftovers');
      } else {
        flash(`${r.merged} bill(s) merged into ${r.doc_number}`);
      }
    } catch (e) { notify(e.message, 'Could not merge'); }
  };
}

// Same arithmetic as the transaction split, and the same rule: the LAST part
// takes the remainder, so the parts always total the bill exactly.
let BS = null;
const bsRound = v => Math.round((Number(v) || 0) * 100) / 100;

function bsApplyPercents() {
  // Nothing typed, nothing computed. The last part used to absorb "the rest",
  // which on an empty form meant the whole bill appeared against part 2 the
  // moment the mode was toggled -- figures nobody had entered.
  if (!BS.parts.some(p => p.percent !== null && p.percent !== '' )) {
    BS.parts.forEach(p => { p.amount = null; });
    return;
  }
  let running = 0;
  BS.parts.forEach((p, i) => {
    if (i === BS.parts.length - 1) {
      p.amount = bsRound(BS.amount - running);
    } else {
      p.amount = bsRound(BS.amount * (Number(p.percent) || 0) / 100);
      running = bsRound(running + p.amount);
    }
  });
}

function bsTotals() {
  if (BS.mode === 'percent') {
    $('#bsLines').querySelectorAll('.bsDollars').forEach(el => {
      const p = BS.parts[+el.dataset.i];
      el.textContent = p ? fmtAmt(p.amount || 0) : '';
    });
  }
  const total = BS.parts.reduce((a, p) => a + (Number(p.amount) || 0), 0);
  const diff = bsRound(BS.amount - total);
  const el = $('#bsSum');
  el.textContent = diff === 0
    ? `${fmtAmt(total)} of ${fmtAmt(BS.amount)} — balanced`
    : `${fmtAmt(total)} of ${fmtAmt(BS.amount)} — `
      + (diff > 0 ? `${fmtAmt(diff)} unallocated` : `${fmtAmt(-diff)} over`);
  el.style.color = diff === 0 ? 'var(--ok)' : 'var(--bad)';
  $('#bsGo').disabled = diff !== 0 || BS.many;
  if (BS.many) $('#bsGo').disabled = BS.parts.some(p => !Number(p.percent));
}

function bsDraw() {
  const pct = BS.mode === 'percent';
  $('#bsLines').innerHTML = BS.parts.map((p, i) => `
    <div style="display:flex;gap:6px;align-items:center">
      <span style="width:16px;color:var(--tx2);font-size:12px">${i + 1}</span>
      <input class="bsVal" data-i="${i}" type="number" step="0.01"
             value="${pct ? (p.percent ?? '') : (p.amount ?? '')}"
             style="width:110px" placeholder="${pct ? '%' : '0.00'}">
      <span class="bsDollars" data-i="${i}"
            style="flex:1;font-size:12px;color:var(--tx2)"
        >${pct && !BS.many ? fmtAmt(p.amount || 0) : ''}</span>
      <button class="ghost bsDel" data-i="${i}"
              style="padding:1px 9px;font-size:16px;line-height:1;color:var(--bad);border-color:var(--line)"${BS.parts.length <= 2 ? ' disabled' : ''}
        >×</button>
    </div>`).join('');
  $('#bsLines').querySelectorAll('.bsVal').forEach(inp => inp.oninput = () => {
    const i = +inp.dataset.i;
    if (BS.mode === 'percent') {
      BS.parts[i].percent = inp.value === '' ? null : Number(inp.value);
      if (!BS.many) bsApplyPercents();
    } else {
      BS.parts[i].amount = inp.value === '' ? null : bsRound(inp.value);
      BS.parts[i].percent = null;
    }
    bsTotals();          // never a redraw: it would take the caret with it
  });
  $('#bsLines').querySelectorAll('.bsDel').forEach(b => b.onclick = () => {
    BS.parts.splice(+b.dataset.i, 1);
    if (BS.mode === 'percent' && !BS.many) bsApplyPercents();
    bsDraw();
  });
  bsTotals();
}

async function billSplit(ids) {
  const rows = (QUEUE.items || []).filter(b => ids.includes(b.bill_id));
  if (!rows.length) return;
  const many = rows.length > 1;
  BS = {ids, many, amount: many ? 0 : Math.abs(Number(rows[0].amt) || 0),
        mode: many ? 'percent' : 'amount',
        parts: [{amount: null, percent: null}, {amount: null, percent: null}]};
  $('#bsHead').innerHTML = many
    ? `<b>${rows.length}</b> bills — the same percentages applied to each.`
    : `Bill <b>${esc(rows[0].bill || rows[0].bill_id)}</b> · `
      + `${fmtAmt(BS.amount)} · ${esc(rows[0].vendor || '')}`;
  document.querySelectorAll('.bsMode').forEach(b => {
    b.style.display = (many && b.dataset.m === 'amount') ? 'none' : '';
    b.classList.toggle('on', b.dataset.m === BS.mode);
  });
  bsDraw();
  $('#billsplit').showModal();
}

document.querySelectorAll('.bsMode').forEach(b => b.onclick = () => {
  BS.mode = b.dataset.m;
  document.querySelectorAll('.bsMode').forEach(x => x.classList.toggle('on', x === b));
  if (BS.mode === 'percent' && !BS.many) bsApplyPercents();
  bsDraw();
});
$('#bsAdd').onclick = () => {
  BS.parts.push({amount: null, percent: null});
  if (BS.mode === 'percent' && !BS.many) bsApplyPercents();
  bsDraw();
};
$('#bsEven').onclick = () => {
  const n = BS.parts.length;
  const share = Math.floor((100 / n) * 10000) / 10000;
  BS.parts.forEach((p, i) => {
    p.percent = i === n - 1 ? bsRound(100 - share * (n - 1)) : share;
  });
  BS.mode = 'percent';
  document.querySelectorAll('.bsMode')
    .forEach(x => x.classList.toggle('on', x.dataset.m === 'percent'));
  if (!BS.many) bsApplyPercents();
  bsDraw();
};
$('#bsCancel').onclick = () => { $('#billsplit').close(); BS = null; };

$('#bsGo').onclick = async () => {
  const st = BS;
  const rows = (QUEUE.items || []).filter(b => st.ids.includes(b.bill_id));
  $('#billsplit').close();
  BS = null;
  const done = [], failed = [];
  for (const b of rows) {
    // Resolved per bill, because the percentages land on different totals and
    // the remainder has to fall on that bill's own last part.
    const amt = Math.abs(Number(b.amt) || 0);
    let running = 0;
    const parts = st.parts.map((p, i) => {
      const v = st.mode === 'percent'
        ? (i === st.parts.length - 1 ? bsRound(amt - running)
           : bsRound(amt * (Number(p.percent) || 0) / 100))
        : p.amount;
      if (i < st.parts.length - 1) running = bsRound(running + v);
      return v;
    });
    const fd = new FormData();
    fd.append('company', company());
    fd.append('bill_id', b.bill_id);
    fd.append('parts', parts.join(','));
    try {
      const r = await api('/bills/split', {method: 'POST', body: fd});
      done.push(r.doc_number);
      (r.failed || []).forEach(f => failed.push(`${r.doc_number}: ${f}`));
    } catch (e) {
      failed.push(`${b.bill || b.bill_id}: ${e.message}`);
    }
  }
  BILL_SEL.clear();
  await load();
  if (failed.length) {
    notify(`${done.length} split. ${failed.length} problem(s):<br><br>`
           + failed.slice(0, 6).map(esc).join('<br>'), 'Partly done',
           {html: true});
  } else {
    flash(done.length === 1 ? `Bill ${done[0]} split` : `${done.length} bills split`);
  }
};

$('#billSplitOne').onclick = () => billSplit([...BILL_SEL]);
// Per-row equivalents, through the same functions as the buttons above.
document.addEventListener('click', e => {
  const sp = e.target.closest && e.target.closest('.rowBillSplit');
  if (sp) { e.stopPropagation(); billSplit([sp.dataset.id]); return; }
  const dl = e.target.closest && e.target.closest('.rowBillDelete');
  if (dl) { e.stopPropagation(); billDelete([dl.dataset.id]); }
});
$('#billDeleteOne').onclick = () => billDelete([...BILL_SEL]);
$('#billBatch').onclick = () => {
  $('#billBatchN').textContent = `${BILL_SEL.size} bill(s)`;
  $('#billbatch').showModal();
};
$('#billBatchCancel').onclick = () => $('#billbatch').close();
document.querySelectorAll('.billBatchOpt').forEach(b => b.onclick = () => {
  $('#billbatch').close();
  // Straight to the existing handlers -- the dialog is a door, not a second
  // implementation of what is behind it.
  if (b.dataset.a === 'split') return billSplit([...BILL_SEL]);
  if (b.dataset.a === 'merge') return billMerge([...BILL_SEL]);
  if (b.dataset.a === 'delete') return billDelete([...BILL_SEL]);
  if (b.dataset.a === 'fields') return billUpdateFields([...BILL_SEL]);
  $(b.dataset.a === 'vendor' ? '#billSetVendor' : '#billSetAmount').click();
});

// THE OPEN BILLS LINE above the quick search: "Open Bills 4389 mirrored --
// last synced 10/8/2026, 10:01 AM  [Sync From QBO]", as on Vendors. Read once
// per company and minute; Sync From QBO reads that company's bills now.
let BILLS_STATUS = {co: '', at: 0, j: null};
// The Bank Feed's quick search while it is being typed (see #gridFind).
const QS_TYPING = {value: '', at: 0, focused: false};
async function renderBillsStatus(force) {
  const el = $('#billsStatus');
  if (!el) return;
  const co = company();
  // ALL BILLS has its own line: every bill mirrored, open or paid.
  const sc = billScope(), tabS = status_;
  const nm = sc === 'all' ? 'All Bills' : 'Open Bills';
  const draw = j => {
    // ONLY ON THE OPEN BILLS TAB: the line sits above every screen, so it
    // showed on Home (and others) after leaving Open Bills.
    // SHOWN ONLY WHILE THE OPEN BILLS TAB ITSELF IS ON SCREEN: its button lit
    // and visible. A load finishing in the background on another screen
    // (Home included) used to bring the line up there.
    const _tab = document.querySelector(`nav button[data-s="${tabS}"]`);
    if (!isBills() || status_ !== tabS || company() !== co || !_tab || !_tab.classList.contains('on') || !_tab.offsetParent
        || document.body.classList.contains('screen-open') || document.body.classList.contains('coding-open')) {
      el.style.display = 'none'; return; }
    el.innerHTML = `<b style="font-size:13px;color:var(--tx)">${nm}</b>
      <span>${(j.count || 0).toLocaleString()} mirrored${j.synced_at ? ' \u2014 last synced ' + esc(localStamp(j.synced_at)) : ''}</span>
      ${isAllCompanies() ? '' : `<button id="billsSync" style="background:#15803d;color:#fff;border:1px solid #15803d;border-radius:6px;
        padding:3px 11px;font-size:11px;font-weight:600">Sync From QBO</button>`}`;
    el.style.display = 'flex';
    const b = $('#billsSync');
    if (b) b.onclick = async () => {
      b.disabled = true; b.textContent = 'Syncing\u2026';
      try {
        const r = await api(`/bills/sync/${encodeURIComponent(co)}?scope=${sc}`, {method: 'POST'});
        BILLS_STATUS = {co, sc, at: Date.now(), j: r};
        flash(sc === 'all' ? 'All bills synced from QuickBooks' : 'Open bills synced from QuickBooks');
        await load();
      } catch (e) { notify(e.message, 'Sync failed'); b.disabled = false; b.textContent = 'Sync From QBO'; }
    };
  };
  if (!force && BILLS_STATUS.co === co && BILLS_STATUS.sc === sc && BILLS_STATUS.j && Date.now() - BILLS_STATUS.at < 60000) return draw(BILLS_STATUS.j);
  try {
    const j = await api(`/bills/status/${encodeURIComponent(co)}?scope=${sc}`);
    BILLS_STATUS = {co, sc, at: Date.now(), j};
    draw(j);
  } catch (e) {}
}

// EACH BILLS TAB KEEPS ITS OWN FILTERS. All Bills starts on Current bills.
const BILL_TAB_STATE = {};
function swapBillFilters(from, to) {
  const tabs = ['bills', 'allbills'];
  if (tabs.includes(from)) {
    BILL_TAB_STATE[from] = {f: {...BILL_FILTERS}, age: new Set(AGE_SEL), cls: new Set(CLASS_SEL)};
  }
  if (!tabs.includes(to) || from === to) return;
  const blank = {vendor: '', memo: '', date_from: '', date_to: '', amt_min: '', amt_max: '',
                 bal_min: '', bal_max: '', aging: '', qbo_id: '', klass: ''};
  const st = BILL_TAB_STATE[to] || (to === 'allbills'
    ? {f: {...blank, aging: 'Current'}, age: new Set(['Current']), cls: new Set()}
    : {f: {...blank}, age: new Set(), cls: new Set()});
  BILL_FILTERS = {...st.f}; AGE_SEL = new Set(st.age); CLASS_SEL = new Set(st.cls);
  Object.entries(FIELD_ID_BILLS).forEach(([k, id]) => {
    const el = document.getElementById(id);
    if (el && 'value' in el && el.tagName !== 'BUTTON') el.value = BILL_FILTERS[k] || '';
  });
  try { renderMulti('bage'); renderMulti('bclass'); } catch (e) {}
}

function renderBills() {
  const rows = QUEUE.items || [];
  $('#colhead').classList.remove('on');
  $('#bulkinline').style.display = 'none';
  // Anything selected that is no longer on screen is dropped -- a filter or a
  // page change shouldn't leave invisible rows queued up for a batch edit.
  const onScreen = new Set(rows.map(b => b.bill_id));
  [...BILL_SEL].forEach(id => { if (!onScreen.has(id)) BILL_SEL.delete(id); });
  // The charge renderer calls this; the bills one never did, which is why the
  // Filters button stayed white here however many filters were set.
  markActiveFilters();
  refreshUndo();
  // Same sortable, resizable header treatment as the charge grid.
  const cols = visibleColumns();
  // The toolbar stays while a search is running, even with no results. It
  // holds the search box, so hiding it left no way to clear the term -- you had
  // to press Reset Filters to get the grid back.
  renderGridIcons(true);
  renderBillsStatus();
  $('#list').style.opacity = '';
  $('#list').innerHTML = rows.length ? `
    <div class="bhead" style="display:flex;gap:10px;padding:7px 14px;font-size:13px;
                font-weight:600;text-transform:uppercase;letter-spacing:.04em;color:var(--tx);
                border-bottom:1px solid var(--line);margin-bottom:6px">
      <!-- A select-all box, matching the one on every row. Without it the
           header started where the rows' checkbox does and every bills column
           sat a checkbox-width left of its own data. -->
      ${CAN.write ? `<input type="checkbox" id="bpickAll"
             title="Select every bill on this page"
             style="width:auto;flex:none;margin:0 6px 0 1px">` : ''}
      ${cols.map(c => {
        const arrow = c.sort && SORT.by === c.sort ? (SORT.dir === 'asc' ? ' ▲' : ' ▼') : '';
        const cls = c.cls + (c.sort ? ' sortcol' : '');
        const attr = c.sort ? ` data-bsort="${c.sort}"` : '';
        return `<span class="${cls}"${attr}>${esc(c.label)}${arrow}`
             + `<i class="rz" data-col="${c.key}"></i></span>`;
      }).join('')}
    </div>
    ${rows.map(b => `<div class="row"><div class="hd" style="cursor:default">
      ${CAN.write ? `<input type="checkbox" class="bpick" data-id="${esc(b.bill_id)}"
             ${BILL_SEL.has(b.bill_id) ? 'checked' : ''}
             style="width:auto;flex:none;margin:0 6px 0 1px">` : ''}
      ${cols.map(c => c.cell(b)).join('')}
    </div></div>`).join('')}`
    : (Object.values(BILL_FILTERS).some(v => v) || FILTERS.q
       ? '<div class="empty">No bills match the filters.</div>'
       : `<div class="empty">No ${billScope() === 'all' ? '' : 'open '}bills loaded. Use Sync From QBO above.</div>`);

  const bpicks = [...document.querySelectorAll('.bpick')];
  bpicks.forEach(cb => cb.onclick = e => {
    e.stopPropagation();
    cb.checked ? BILL_SEL.add(cb.dataset.id) : BILL_SEL.delete(cb.dataset.id);
    renderBillBulk();
  });
  rangeSelect(bpicks, BILL_SEL, cb => cb.dataset.id, renderBillBulk);
  document.querySelectorAll('.billven').forEach(b => b.onclick = e => {
    e.stopPropagation();
    openBillVendorPicker(b);
  });
  document.querySelectorAll('.billamt').forEach(b => b.onclick = e => {
    e.stopPropagation();
    billAmountDialog([b.dataset.id]);
  });
  const bAll = $('#bpickAll');
  if (bAll) {
    bAll.checked = rows.length > 0 && rows.every(b => BILL_SEL.has(b.bill_id));
    bAll.onchange = () => {
      rows.forEach(b => bAll.checked ? BILL_SEL.add(b.bill_id)
                                     : BILL_SEL.delete(b.bill_id));
      renderBills();
    };
  }
  renderBillBulk();

  // No per-element sort handler here. There used to be one, and the
  // document-level handler below ran straight after it and overwrote SORT.by
  // with undefined -- so the bills grid set the sort correctly and then unset
  // it, twice per click. One handler covers both grids.
}

function renderPage() {
  const per = parseInt($('#fpage').value, 10) || 200;
  const total = QUEUE.total || 0;
  const from = total ? PAGE_OFFSET + 1 : 0;
  const to = Math.min(PAGE_OFFSET + per, total);
  // innerHTML, not textContent: the total is the number people scan for, so it
  // is bold and labeled rather than trailing off after "of".
  $('#pageinfo').innerHTML = total
    ? `${from}–${to} of <b style="font-size:14px">${total.toLocaleString()}`
      + `</b> <b style="font-size:14px">Results</b>` : '';
  renderPageNums(total);
  $('#prevPage').disabled = PAGE_OFFSET === 0;
  $('#nextPage').disabled = PAGE_OFFSET + per >= total;
  // Keep the controls visible and just disable them at the ends -- hiding them
  // made it look like paging didn't exist.
  const showPager = total > per;
  $('#prevPage').style.display = showPager ? '' : 'none';
  $('#nextPage').style.display = showPager ? '' : 'none';
  $('#pageinfo').style.display = total ? '' : 'none';
}

function renderHeader() {
  // ON THE BANK FEED, FOR THE COMPANY SHOWING, only: the banner sits above
  // every screen, so it stayed up on the Dashboard and other screens -- and
  // after changing company -- until the next Bank Feed load said otherwise.
  $('#halWarn').style.display = (QUEUE.hal_connected === false && QUEUE.company === company()
    && !isAllCompanies() && !document.body.classList.contains('screen-open')) ? 'block' : 'none';
  // Only append a count once one is known -- "(0)" while loading reads as a
  // fact rather than an absence.
  const nBills = COUNTS.bills ?? QUEUE.bills_loaded;
  $('#billsavail').textContent = nBills === undefined || nBills === null
    ? 'Open Bills' : `Open Bills (${nBills})`;
  // Same reasoning: no parenthetical until there's a number to put in it,
  // rather than "(undefined)" for the moment before the counts land.
  const count = v => (v === undefined || v === null) ? '' : ' (' + v + ')';
  $('#c_review').textContent = count(COUNTS.for_review);
  $('#c_cat').textContent = count(COUNTS.categorized);
  $('#c_exc').textContent = count(COUNTS.excluded);
}

// Card ACCOUNTS, matching the Cards screen -- several can be picked at once,
// which the single-select version couldn't do.
// Amounts are stored absolute with the sign carried separately, so an amount
// range can't express "refunds only". This is the only way to ask for them.
// Selections for the checkbox filters. Empty means untouched, which reads as
// "everything" -- the same as ticking every box.
// Filled from MULTI once it is defined -- every box ticked, which is the state
// that shows everything.
let TXN_SEL = new Set();
let TIER_SEL = new Set();
let MATCH_SEL = new Set();
// Empty or full means "no filter" -- both are sent as nothing.
let KIND_SEL = new Set();
let CARD_SEL = new Set();
let CARD_Q = '';        // what's typed in the cards menu search box
let CARD_INIT = false;

// Which kinds of card the picker's list is narrowed to: API, Plaid, Virtual,
// None (a card with none of those). Narrows the LIST, like the search box --
// it chooses nothing by itself; Select All then takes what is shown.
let CARD_TYPES = new Set();
const CARD_TYPE_TEST = {
  api: s => !!s.api_fed,
  plaid: s => !!s.linked,
  virtual: s => !!s.virtual,
  none: s => !s.api_fed && !s.linked && !s.virtual,
};

// COMPANIES (Multi-Company): which companies the Bank Feed shows. Like the
// card picker -- nothing ticked is every company, ticks narrow, and the grid
// reloads once when the picker closes. Hidden for a single company.
let COMP_SEL = new Set();
let COMP_DIRTY = false;
const compFilter = () => (isAllCompanies() && COMP_SEL.size) ? [...COMP_SEL].join(',') : '';
function renderCompanyFilter() {
  const wrap = document.getElementById('fcompWrap');
  if (!wrap) return;
  syncMultiClass();
  wrap.style.display = isAllCompanies() ? '' : 'none';
  if (!isAllCompanies()) return;
  const btn = document.getElementById('fcompBtn'), menu = document.getElementById('fcompMenu');
  const names = COMPANIES.map(c => c.name);
  btn.textContent = !COMP_SEL.size || COMP_SEL.size === names.length ? 'All Companies'
    : COMP_SEL.size === 1 ? [...COMP_SEL][0] : `${COMP_SEL.size} Companies`;
  btn.classList.toggle('on', COMP_SEL.size > 0 && COMP_SEL.size < names.length);
  const g = 'padding:3px 10px;font-size:12px;font-weight:600;color:#fff;border-radius:6px';
  menu.innerHTML = names.map(n => `<label class="msopt" style="display:flex;gap:6px;
      align-items:center;padding:2px 4px;font-size:13px"><input type="checkbox"
      class="compPick" value="${esc(n)}" style="width:auto" ${COMP_SEL.has(n) ? 'checked' : ''}>${esc(n)}</label>`).join('')
    + `<div class="msact" style="display:flex;gap:6px">
        <button id="compAll" style="${g};background:#15803d;border:1px solid #15803d">Select All</button>
        <button id="compNone" style="${g};background:var(--bad);border:1px solid var(--bad)">Clear</button>
        <button id="compClose" style="${g};background:var(--accent);border:1px solid var(--accent)">Close</button></div>`;
  menu.onclick = e => e.stopPropagation();
  menu.querySelectorAll('.compPick').forEach(cb => cb.onchange = () => {
    cb.checked ? COMP_SEL.add(cb.value) : COMP_SEL.delete(cb.value);
    COMP_DIRTY = true; renderCompanyFilter(); menu.style.display = 'block';
  });
  menu.querySelector('#compAll').onclick = () => { COMP_SEL = new Set(names); COMP_DIRTY = true; renderCompanyFilter(); menu.style.display = 'block'; };
  menu.querySelector('#compNone').onclick = () => { COMP_SEL = new Set(); COMP_DIRTY = true; renderCompanyFilter(); menu.style.display = 'block'; };
  menu.querySelector('#compClose').onclick = () => closeCompanyFilter();
  btn.onclick = e => {
    e.stopPropagation();
    if (menu.style.display === 'block') closeCompanyFilter();
    else { menu.style.display = 'block'; if (typeof fitMenu === 'function') fitMenu(menu, btn); }
  };
}
function closeCompanyFilter() {
  const menu = document.getElementById('fcompMenu');
  if (!menu || menu.style.display !== 'block') return;
  menu.style.display = 'none';
  if (COMP_DIRTY) {
    COMP_DIRTY = false;
    // The cards on offer are the chosen companies' cards: start again.
    CARD_SEL = new Set();
    PAGE_OFFSET = 0;
    load({keepScroll: false});
  }
}
document.addEventListener('click', e => { if (!e.target.closest('#fcompWrap')) closeCompanyFilter(); });

// THE COMPANIES PICKER at the START of a screen's quick search row (QBO Sync
// screens). The same selection as the Bank Feed's: choosing companies on one
// screen carries to the others. Reloads the screen once, when it closes.
function mountCompanyPicker(bar, reload) {
  syncMultiClass();
  if (!bar || !isAllCompanies()) return;
  const old = bar.querySelector('.qcompWrap');
  if (old) old.remove();
  const names = COMPANIES.map(c => c.name);
  const wrap = document.createElement('span');
  wrap.className = 'qcompWrap';
  wrap.style.cssText = 'position:relative;display:inline-block;margin-right:6px;order:-1';
  const label = () => !COMP_SEL.size || COMP_SEL.size === names.length ? 'All Companies'
    : COMP_SEL.size === 1 ? [...COMP_SEL][0] : `${COMP_SEL.size} Companies`;
  const g = 'padding:3px 10px;font-size:12px;font-weight:600;color:#fff;border-radius:6px';
  wrap.innerHTML = `<button class="ghost qcompBtn" style="min-width:140px;text-align:left">${esc(label())}</button>
    <div class="msmenu qcompMenu" style="display:none;position:absolute;z-index:40;top:32px;left:0;min-width:260px"></div>`;
  bar.insertBefore(wrap, bar.firstChild);
  const btn = wrap.querySelector('.qcompBtn'), menu = wrap.querySelector('.qcompMenu');
  let dirty = false;
  const draw = () => {
    btn.textContent = label();
    menu.innerHTML = names.map(n => `<label class="msopt" style="display:flex;gap:6px;align-items:center;
        padding:2px 4px;font-size:13px"><input type="checkbox" class="qcompPick" value="${esc(n)}"
        style="width:auto" ${COMP_SEL.has(n) ? 'checked' : ''}>${esc(n)}</label>`).join('')
      + `<div class="msact" style="display:flex;gap:6px">
          <button class="qcompAll" style="${g};background:#15803d;border:1px solid #15803d">Select All</button>
          <button class="qcompNone" style="${g};background:var(--bad);border:1px solid var(--bad)">Clear</button>
          <button class="qcompClose" style="${g};background:var(--accent);border:1px solid var(--accent)">Close</button></div>`;
    menu.querySelectorAll('.qcompPick').forEach(cb => cb.onchange = () => {
      cb.checked ? COMP_SEL.add(cb.value) : COMP_SEL.delete(cb.value); dirty = true; draw(); });
    menu.querySelector('.qcompAll').onclick = () => { COMP_SEL = new Set(names); dirty = true; draw(); };
    menu.querySelector('.qcompNone').onclick = () => { COMP_SEL = new Set(); dirty = true; draw(); };
    menu.querySelector('.qcompClose').onclick = () => close();
  };
  const close = () => {
    if (menu.style.display !== 'block') return;
    menu.style.display = 'none';
    document.removeEventListener('click', outside);
    if (dirty) { dirty = false; reload(); }
  };
  const outside = e => { if (!wrap.contains(e.target)) close(); };
  menu.onclick = e => e.stopPropagation();
  btn.onclick = e => {
    e.stopPropagation();
    if (menu.style.display === 'block') return close();
    draw(); menu.style.display = 'block';
    setTimeout(() => document.addEventListener('click', outside), 0);
  };
}

function renderCardPicker() {
  renderCompanyFilter();
  // ORDER AS SENT. The server sorts by account type and then name, the same
  // order as the Bank / Card Accounts grid.
  const srcs = [...(COUNTS.sources || [])];
  // NOTHING TICKED MEANS EVERY CARD. Ticking narrows. It used to start with
  // every card ticked, so picking one meant deselecting everything first and
  // then finding it again.
  CARD_INIT = true;
  const anyVirt = srcs.some(x => x.virtual);
  const anyPhys = srcs.some(x => !x.virtual);
  const groupRow = (id, label, test) => {
    const members = srcs.filter(test);
    const all = members.length > 0 && members.every(m => CARD_SEL.has(m.source));
    return `<label class="cardrow cardgroup" data-name="${esc(label.toLowerCase())}"
             data-kind="group"
             style="display:flex;align-items:center;gap:7px;padding:3px 2px;
                    font-size:13px;font-weight:600">
      <input type="checkbox" class="cardgroupPick" data-group="${id}"
             ${all ? 'checked' : ''} style="width:auto">
      ${esc(label)}
      <span style="color:var(--tx2);font-weight:400">(${members.length})</span>
    </label>`;
  };
  const typeChip = (k, label) => `<button class="ghost cardTypeChip" data-type="${k}"
      style="padding:1px 8px;font-size:11px;border-radius:10px;
             ${CARD_TYPES.has(k) ? 'background:#e8f1fb;border-color:#bcd9ee;font-weight:600' : ''}"
      >${label}</button>`;

  $('#fcardMenu').onclick = e => e.stopPropagation();
  // THREE PARTS: a header, a list that scrolls by itself, and a footer that
  // stays put. The whole menu used to be one tall block, so with a long card
  // list the Select All buttons were below the bottom of the screen.
  $('#fcardMenu').style.display = $('#fcardMenu').style.display || '';
  $('#fcardMenu').innerHTML = `
    <div style="display:flex;flex-direction:column;max-height:min(70vh,640px)">
      <div style="flex:none">
        <div style="display:flex;gap:4px;flex-wrap:wrap;margin-bottom:6px">
          ${typeChip('api', 'API')}${typeChip('plaid', 'Plaid')}
          ${typeChip('virtual', 'Virtual')}${typeChip('none', 'None')}
        </div>
        <input id="cardSearch" placeholder="Type to narrow…" value="${esc(CARD_Q)}"
               style="width:100%;margin-bottom:6px;font-size:13px">
      </div>
      <div id="cardList" style="flex:1 1 auto;min-height:0;overflow-y:auto">`
    + (anyVirt ? groupRow('virtual', 'Virtuals', x => x.virtual) : '')
    + (anyPhys ? groupRow('physical', 'Non-Virtuals', x => !x.virtual) : '')
    + ((anyVirt || anyPhys)
        ? '<div style="border-top:1px solid var(--line);margin:5px 0"></div>' : '')
    + srcs.map(s => `
      <label class="cardrow" data-name="${esc((s.name || '').toLowerCase())}"
             data-src="${esc(s.source)}"
             style="display:flex;align-items:center;gap:7px;padding:3px 2px;font-size:13px">
        <input type="checkbox" class="cardpick" value="${esc(s.source)}"
               ${CARD_SEL.has(s.source) ? 'checked' : ''} style="width:auto">
        ${esc(s.name)}${s.qbo_retired ? `<span class="vtag"
          title="Retired in QuickBooks. It stays here because charges are filed
                 under it and have to remain findable."
          style="background:#f1f5f9;color:#64748b">RETIRED</span>` : ''}${
          s.linked ? linkBadge(s.link_status, 13) : ''}${
          s.api_fed ? apiBadge(s.api_stale_hours) : ''}${
          s.virtual ? '<span class="vtag">VIRTUAL</span>' : ''}
        ${s.active === false
          ? '<span class="vtag" style="background:var(--chip);color:var(--tx2)"'
            + ' title="No longer in use — history only">RETIRED</span>' : ''}
        <span style="color:var(--tx2)">(${s.count ?? s.for_review ?? 0})</span>
      </label>`).join('')
    + `</div>
      <div style="flex:none;display:flex;gap:6px;margin-top:7px;
                  border-top:1px solid var(--line);padding-top:7px">
        <button id="cardAll" style="padding:3px 10px;font-size:12px;font-weight:600;
          background:#15803d;color:#fff;border:1px solid #15803d;border-radius:6px"
          title="Tick every card shown">Select All</button>
        <button id="cardNone" style="padding:3px 10px;font-size:12px;font-weight:600;
          background:var(--bad);color:#fff;border:1px solid var(--bad);border-radius:6px"
          title="Untick everything -- every card is shown again">Clear</button>
        <button id="cardClose" style="padding:3px 10px;font-size:12px;font-weight:600;
          background:var(--accent);color:#fff;border:1px solid var(--accent);
          border-radius:6px" title="Close and show the chosen cards">Close</button>
      </div>
    </div>`;

  // What the list shows: the search text AND the type chips. The group rows
  // follow the search only.
  const bySrc = new Map(srcs.map(x => [x.source, x]));
  const visible = s => {
    const needle = CARD_Q.trim().toLowerCase();
    if (needle && !(s.name || '').toLowerCase().includes(needle)) return false;
    if (!CARD_TYPES.size) return true;
    return [...CARD_TYPES].some(t => CARD_TYPE_TEST[t](s));
  };
  const applyCardSearch = () => {
    const needle = CARD_Q.trim().toLowerCase();
    $('#fcardMenu').querySelectorAll('.cardrow').forEach(r => {
      const s = r.dataset.src ? bySrc.get(r.dataset.src) : null;
      const on = s ? visible(s) : (!needle || r.dataset.name.includes(needle));
      r.style.display = on ? 'flex' : 'none';
    });
  };
  const search = $('#cardSearch');
  search.oninput = () => { CARD_Q = search.value; applyCardSearch(); };
  search.onclick = e => e.stopPropagation();
  applyCardSearch();
  $('#fcardMenu').querySelectorAll('.cardTypeChip').forEach(b => b.onclick = e => {
    e.stopPropagation();
    CARD_TYPES.has(b.dataset.type) ? CARD_TYPES.delete(b.dataset.type)
                                   : CARD_TYPES.add(b.dataset.type);
    renderCardPicker();
  });

  const picked = srcs.filter(x => CARD_SEL.has(x.source));
  const label = (CARD_SEL.size === 0 || CARD_SEL.size >= srcs.length)
    ? `All Card Accounts (${srcs.length})`
    : picked.length === 1 ? picked[0].name
    : `${picked.length} Card Accounts`;
  $('#fcardBtn').textContent = label;
  // IN USE while it narrows the grid (some cards ticked, not every one).
  {
    const _all = ((COUNTS && COUNTS.sources) || []).length;
    $('#fcardBtn').classList.toggle('on', CARD_SEL.size > 0 && (!_all || CARD_SEL.size < _all));
  }

  $('#fcardMenu').querySelectorAll('.cardpick').forEach(cb => cb.onchange = () => {
    cb.checked ? CARD_SEL.add(cb.value) : CARD_SEL.delete(cb.value);
    CARD_DIRTY = true;
    renderCardPicker();
  });
  const shown = () => srcs.filter(visible);
  $('#fcardMenu').querySelectorAll('.cardgroupPick').forEach(cb => {
    cb.onclick = e => e.stopPropagation();
    cb.onchange = () => {
      const test = cb.dataset.group === 'virtual' ? (x => x.virtual) : (x => !x.virtual);
      const members = (COUNTS.sources || []).filter(test).map(x => x.source);
      const next = new Set(CARD_SEL);
      members.forEach(m => cb.checked ? next.add(m) : next.delete(m));
      CARD_SEL = next;
      CARD_DIRTY = true;
      renderCardPicker();
    };
  });

  const closeBtn = $('#cardClose');
  if (closeBtn) closeBtn.onclick = e => { e.stopPropagation(); closeCardPicker(); };
  const all = $('#cardAll'), none = $('#cardNone');
  if (all) all.onclick = () => {
    shown().forEach(s => CARD_SEL.add(s.source));
    CARD_DIRTY = true;
    renderCardPicker();
  };
  if (none) none.onclick = () => {
    CARD_SEL = new Set();
    CARD_DIRTY = true;
    renderCardPicker();
  };
}

// The control asks a different question depending on the tab. On For Review and
// Excluded nothing has been resolved yet, so the only distinction available is
// whether money went out or came back. On Categorized the useful question is
// what the charge was resolved AS, and several kinds are worth seeing together
// -- so that one is a multi-select.

// One engine for every checkbox filter. Each declares its options and where
// its selection lives; the rest -- button label, menu, select/clear all, and
// the "everything ticked means no filter" rule -- is shared.
// Everything ticked, immediately.
//
// This used to happen on the first render, but the first load() runs BEFORE
// any render -- so on a page refresh the sets were still empty, empty means
// "none selected", and the grid came back with nothing in it.
function seedMultiSelections() {
  Object.keys(MULTI).forEach(k =>
    resetMulti(k));
}

// Which query parameter each multi-select feeds.
const MULTI_PARAM = {ftype: 'txn_type', ftier: 'tier',
                     fmatch: 'matchable', fkind: 'kinds', fingest: 'ingest',
                     fuser: 'user'};

// Seeded by seedMultiSelections; the literal matches what it produces so a
// render before that call cannot blank the grid.
let INGEST_SEL = new Set();
let USER_SEL = new Set();
let USER_OPTS_LOADED = false;
let AGE_SEL = new Set();
let CLASS_SEL = new Set();
const MULTI = {
  ftype: {
    title: 'Transaction Types',
    // Like the card picker: nothing ticked is every type, ticks narrow, and
    // the grid reloads when the picker closes rather than on every tick.
    noneIsAll: true,
    tabs: ['for_review', 'excluded'],
    options: [['charges', 'Charges'], ['payments', 'Payments'],
              ['refunds', 'Refunds']],
    get: () => TXN_SEL, set: v => { TXN_SEL = v; },
  },
  bage: {
    // A bucket list is short and people ask for two of them at once -- "what
    // is 61 days or older" is two ticks, not two visits to a dropdown.
    title: 'Aging',
    tabs: ['bills', 'allbills'],
    options: [['Current', 'Current'], ['1 - 30', '1 - 30'],
              ['31 - 60', '31 - 60'], ['61 - 90', '61 - 90'],
              ['91 and over', '91 and over']],
    get: () => AGE_SEL, set: v => { AGE_SEL = v; },
  },
  // CLASS on Open Bills and All Bills: the Classes on this company's bills,
  // filled from the bills read, and bills with none.
  bclass: {
    title: 'Classes',
    tabs: ['bills', 'allbills'],
    options: [['__none', 'No Class']],
    get: () => CLASS_SEL, set: v => { CLASS_SEL = v; },
  },
  ftier: {
    // Two questions in one picker, separated by a rule: how good the bill
    // match is, and whether the cardholder has a season-ticket record at all.
    // They are asked together often enough that two controls would just mean
    // two things to open.
    title: 'Strengths / Records',
    tabs: ['for_review', 'categorized'],
    options: [['perfect', 'Perfect'], ['very_strong', 'Very Strong'],
              ['strong', 'Strong'], ['moderate', 'Moderate'],
              ['weak', 'Weak'], ['none', 'No Candidate'],
              ['--', '--'],
              ['rec:found', 'Record Found'],
              ['rec:none', 'Record Not Found']],
    get: () => TIER_SEL, set: v => { TIER_SEL = v; },
  },
  fuser: {
    title: 'Users',
    tabs: ['categorized'],
    // Filled from /users/list once the screen knows who exists; the literal
    // here is only what an unfilled render shows.
    options: [['system', 'system']],
    get: () => USER_SEL, set: v => { USER_SEL = v; },
  },
  fingest: {
    title: 'Ingestion Methods',
    tabs: ['for_review', 'categorized', 'excluded'],
    options: [['csv', 'CSV Upload'], ['api', 'Program API'], ['plaid', 'Plaid']],
    get: () => INGEST_SEL, set: v => { INGEST_SEL = v; },
  },
  fmatch: {
    title: 'Action Types',
    // Removed from For Review: it filtered on a distinction nobody was using,
    // and it sat in a row that is now four pickers wide. The definition stays
    // so the saved selection keeps its shape, but it is offered nowhere.
    tabs: [],
    options: [['match', 'Add/Match'], ['add', 'Add Only']],
    get: () => MATCH_SEL, set: v => { MATCH_SEL = v; },
  },
  fkind: {
    title: 'Transaction Types',
    tabs: ['categorized'],
    options: [['bill_payment', 'Bill Payments'], ['expense', 'Expenses'],
              ['payment', 'Payments'], ['refund', 'Refunds']],
    get: () => KIND_SEL, set: v => { KIND_SEL = v; },
  },
};

// EVERY PICKER STARTS WITH NOTHING TICKED, meaning all -- as the Card Accounts
// picker does -- so choosing two means ticking two, not unticking the rest
// first. Ticks narrow; Clear goes back to all.
Object.values(MULTI).forEach(m => { m.noneIsAll = true; });

seedMultiSelections();
// ALL BILLS opened from the last visit starts on Current bills, as a click does.
if (status_ === 'allbills') { AGE_SEL = new Set(['Current']); BILL_FILTERS.aging = 'Current'; }

// Empty used to mean "untouched, so show everything", which made Clear look
// broken -- you unticked every box and the grid was unchanged. Empty now means
// what it says: nothing selected, nothing shown. The Card Accounts picker has
// always worked this way, which is why that one Clear appeared to work.
// A picker back to its default: every option ticked -- or, for one where
// nothing ticked already means everything (Transaction Types), nothing ticked.
function resetMulti(k) {
  const m = MULTI[k];
  if (!m) return;
  m.set(m.noneIsAll ? new Set()
    : new Set(m.options.filter(o => o[0] !== '--').map(o => o[0])));
}

function multiValue(key) {
  const m = MULTI[key];
  const sel = m.get();
  if (sel.size === 0) return m.noneIsAll ? '' : '\u0000none';
  // Dividers are not choices: counting one made a fully-selected picker look
  // narrowed, and sent a filter value on every request.
  const n = m.options.filter(o => o[0] !== '--').length;
  return sel.size < n ? [...sel].join(',') : '';
}

let MULTI_T = null;

function renderMulti(key) {
  // A click inside a menu never reaches the document closer.
  //
  // Checking `closest('.msmenu')` there was not enough: Select All rebuilds the
  // menu's contents, which detaches the button that was clicked, so by the time
  // the event bubbled up it had no ancestors at all and read as an outside
  // click. The propagation path is fixed when the event is dispatched, so a
  // listener on the menu itself still fires and can stop it here.
  const m0 = $('#' + key + 'Menu');
  if (m0) m0.onclick = e => e.stopPropagation();

  const m = MULTI[key];
  const btn = $('#' + key + 'Btn');
  const menu = $('#' + key + 'Menu');
  if (!btn) return;
  const showing = m.tabs.includes(status_);
  btn.parentNode.style.display = showing ? '' : 'none';
  if (!showing) return;

  const sel = m.get();
  // A selection saved before the separator existed can still contain it.
  if (sel.has('--')) { sel.delete('--'); m.set(sel); }
  const real = m.options.filter(o => o[0] !== '--');
  const all = sel.size === real.length || (m.noneIsAll && sel.size === 0);
  btn.textContent = all ? `All ${m.title}`
    : sel.size === 0 ? `No ${m.title} Selected`
    : sel.size === 1 ? (real.find(o => sel.has(o[0])) || ['', ''])[1]
    : `${sel.size} ${m.title}`;
  btn.classList.toggle('on', !all);

  // "--" is a separator, not an option: it draws a rule and nothing else, so
  // two related questions can share one menu without reading as one list.
  menu.innerHTML = m.options.map(([v, label]) => v === '--'
    ? `<div style="border-top:1px solid var(--line);margin:5px 0"></div>`
    : `
    <label class="msopt">
      <input type="checkbox" class="mspick" value="${esc(v)}"
             ${sel.has(v) ? 'checked' : ''}>
      ${esc(label)}
    </label>`).join('')
    + (m.noneIsAll
      ? `<div class="msact">
         <button class="msall" style="padding:3px 10px;font-size:12px;font-weight:600;
           background:#15803d;color:#fff;border:1px solid #15803d;border-radius:6px"
           >Select All</button>
         <button class="msnone" style="padding:3px 10px;font-size:12px;font-weight:600;
           background:var(--bad);color:#fff;border:1px solid var(--bad);border-radius:6px"
           >Clear</button>
         <button class="msclose" style="padding:3px 10px;font-size:12px;font-weight:600;
           background:var(--accent);color:#fff;border:1px solid var(--accent);
           border-radius:6px">Close</button>
       </div>`
      : `<div class="msact">
         <button class="ghost msall" style="padding:3px 9px;font-size:12px">Select All</button>
         <button class="ghost msnone" style="padding:3px 9px;font-size:12px">Deselect All</button>
       </div>`);

  // Each tick changes the selection immediately, but the RELOAD waits until
  // you stop.
  //
  // Ticking three boxes quickly used to fire three loads, and each one rebuilt
  // the set from `sel` -- the snapshot taken when the menu was drawn -- so the
  // second and third clicks each undid the ones before them and only one
  // registered. The set is now read live at click time, and the load is
  // debounced so a burst of clicks is one request.
  // INSIDE THE FILTERS WINDOW, a tick waits for Apply: the label changes, the
  // grid does not -- and closing the window without Apply puts it back.
  const _inFilters = !!(document.getElementById(key + 'Btn') || menu).closest('#advfilters');
  const apply = next => {
    if (_inFilters && m.before === undefined) m.before = new Set(m.get());
    m.set(next);
    renderMulti(key);          // label reflects the tick right away
    if (_inFilters) return;
    PAGE_OFFSET = 0;
    if (m.noneIsAll) { m.dirty = true; return; }   // reloads when it closes
    clearTimeout(MULTI_T);
    MULTI_T = setTimeout(() => load({keepScroll: false}), 320);
  };
  menu.querySelectorAll('.mspick').forEach(cb => cb.onchange = () => {
    const base = new Set(m.get());     // live, not the snapshot
    cb.checked ? base.add(cb.value) : base.delete(cb.value);
    apply(base);
  });
  menu.querySelector('.msall').onclick = () =>
    apply(new Set(m.options.filter(o => o[0] !== '--').map(o => o[0])));
  menu.querySelector('.msnone').onclick = () => apply(new Set());
  const _close = menu.querySelector('.msclose');
  if (_close) _close.onclick = () => closeMulti(key);
}

// Close a picker; reload the grid once if its choice changed while open.
function closeMulti(key) {
  const m = MULTI[key], menu = $('#' + key + 'Menu');
  if (menu) menu.style.display = 'none';
  const _b = document.getElementById(key + 'Btn');
  if (_b && _b.closest('#advfilters')) return;          // waits for Apply
  if (m && m.dirty) {
    m.dirty = false;
    PAGE_OFFSET = 0;
    load({keepScroll: false});
  }
}

function renderTypePicker() {
  Object.keys(MULTI).forEach(renderMulti);
}

// FIT A PICKER INTO THE SPACE IT HAS. Inside the Filters window a picker hung
// below its button and, near the window's bottom edge, ran past it -- so the
// WINDOW scrolled instead of the picker. It now opens upward when there is
// more room above, and is sized to the room it has, so only the list scrolls.
function fitMenu(menu, btn) {
  const box = btn.closest('dialog, #advfilters, #billfilters, #auditfilters');
  const b = btn.getBoundingClientRect();
  const lim = box ? box.getBoundingClientRect()
                  : {top: 0, bottom: window.innerHeight};
  const below = lim.bottom - b.bottom - 12, above = b.top - lim.top - 12;
  menu.style.top = ''; menu.style.bottom = '';
  if (below < 220 && above > below) {
    menu.style.top = 'auto';
    menu.style.bottom = 'calc(100% + 4px)';
    menu.style.maxHeight = `${Math.max(120, Math.min(420, above))}px`;
  } else {
    menu.style.maxHeight = `${Math.max(120, Math.min(420, below))}px`;
  }
  menu.style.overflowY = 'auto';
}

// One handler for every multi-select button.
document.addEventListener('click', e => {
  const btn = e.target.closest('.msbtn');
  const keyOf = id => id.replace(/Menu$/, '');
  document.querySelectorAll('.msmenu').forEach(m => {
    if (!btn || m.id !== btn.dataset.menu) {
      if (!e.target.closest('.msmenu') && m.style.display === 'block') closeMulti(keyOf(m.id));
    }
  });
  if (!btn) return;
  e.stopPropagation();
  const menu = $('#' + btn.dataset.menu);
  if (menu.style.display === 'block') closeMulti(keyOf(menu.id));
  else { menu.style.display = 'block'; fitMenu(menu, btn); }
});

// THE GRID WAITS FOR THE PICKER TO CLOSE. Each tick used to reload the grid
// straight away, so choosing four cards meant four reloads. Ticks now only
// mark the choice as changed; closing the picker -- its button, a click
// elsewhere, or Close -- reloads once, and only if something did change.
let CARD_DIRTY = false;
// Set by "select all N matching": the filters its selection was made under.
let SEL_MATCHING = null;
// The totals the server gave for a "Select all N matching" selection.
let SEL_TOTALS = null;
// Whether API Card Connections' "Add Or Change Connections" is open.
let API_MANAGE_OPEN = false;
function closeCardPicker() {
  const m = $('#fcardMenu');
  if (!m || m.style.display === 'none') return;
  m.style.display = 'none';
  if (CARD_DIRTY) {
    CARD_DIRTY = false;
    PAGE_OFFSET = 0;
    load({keepScroll: false});
  }
}
$('#fcardBtn').onclick = e => {
  e.stopPropagation();
  const m = $('#fcardMenu');
  if (m.style.display === 'none' || !m.style.display) {
    m.style.display = 'block';
    setTimeout(() => { const b = $('#cardSearch'); if (b) b.focus(); }, 0);
  } else {
    closeCardPicker();
  }
};
document.addEventListener('click', e => {
  if (!e.target.closest('.ms')) {
    closeCardPicker();
    $('#ftypeMenu').style.display = 'none';
  }
});

// --- one row: can be matched to a bill OR coded ---
// Amounts arrive as decimal strings ("4486.98"). Grouping them makes the
// magnitude readable at a glance -- $1083.75 and $10837.50 look far too alike
// without it, which matters in a column you scan rather than read.
// EVERY amount on screen carries its dollar sign, and it comes from here.
// It used to be left to the call site -- `${fmtAmt(x)}` in thirteen places and
// a bare `fmtAmt(x)` in twenty-one others -- so whether a number read as money
// depended on which template happened to prefix it. A formatter that returns
// half a value is a formatter every new caller gets wrong.
//
// Negatives print in parentheses, matching the Excel exports, which use
// $#,##0.00;($#,##0.00). A minus sign and a bracket for the same thing across
// the two would be a difference with no meaning behind it.
function fmtAmt(v) {
  const n = Number(v);
  if (!isFinite(n)) return String(v ?? '');
  const body = Math.abs(n).toLocaleString('en-US', {minimumFractionDigits: 2,
                                                   maximumFractionDigits: 2});
  return n < 0 ? `($${body})` : `$${body}`;
}

// The bare number, for the few places that supply their own symbol: a source
// amount in Canadian dollars, where the point is that it is NOT USD.
function fmtNum(v) {
  const n = Number(v);
  if (!isFinite(n)) return String(v ?? '');
  return n.toLocaleString('en-US', {minimumFractionDigits: 2,
                                    maximumFractionDigits: 2});
}

function fmtDate(iso) {
  const p = String(iso || '').split('-');
  return p.length === 3 ? `${+p[1]}/${+p[2]}/${p[0]}` : (iso || '');
}

// One definition per column, used by the header, the rows, the column picker
// and the resizer. Adding a column means adding one entry here.
//
//   tabs  -- which tabs it can appear on at all (absent = all charge tabs)
//   fixed -- can't be hidden; without it a row is unidentifiable
const CHARGE_COLUMNS = [
  // First column: it is what the row is FOR. Everything else describes the
  // charge; this is where you act on it.
  // Categorized has no per-row actions left: Split moved into the category
  // picker and Delete to the toolbar, so an empty column would just take width.
  {key: 'act',     label: 'Action',                 cls: 'c-act',  fixed: true,
   tabs: ['for_review', 'excluded'],
   cell: it => actionCell(it)},

  // COMPANY, right after Action -- only in Multi-Company, where rows from
  // every company share the grid.
  {key: 'company', label: 'Company', cls: 'c-company', sort: 'company', fixed: true,
   multi: true,
   cell: it => `<span class="c-company" title="${esc(it.company || '')}">${esc(it.company || '')}</span>`},
  {key: 'card',    label: 'Card Account',           cls: 'c-card',    sort: 'account', fixed: true,
   // The QuickBooks warning rides here rather than in Categorization Details:
   // a wide CHECK QBO badge threw that column's widths out, and the first
   // column is where the eye lands anyway.
   cell: it => `<span class="c-card" title="${esc(it.account)}">${esc(it.account)}`
     + (it.post_error
        ? `<span class="tag tag-bang" title="${esc(it.post_error)}">!</span>` : '')
     + `</span>`},
  {key: 'date',    label: 'Date',                   cls: 'c-date',    sort: 'date',
   cell: it => `<span class="c-date">${fmtDate(it.date)}</span>`},
  {key: 'cven',    label: 'Vendor',                 cls: 'c-cven',    sort: 'cvendor',
   tabs: ['for_review', 'categorized'],
   // A bill payment's vendor comes from the bill it paid, so it isn't editable
   // here -- recategorize it first and it becomes an expense with its own.
   // The read-only form carries the same padding as the button in the editable
   // one, or a bill payment's vendor sits a few pixels left of every other row
   // in the column.
   cell: it => it.resolution === 'matched'
     ? `<span class="c-cven"><span class="cell-ro" title="${esc(vendorCell(it))}"
          >${esc(vendorCell(it))}</span></span>`
     : selectCell(it, 'vendor', vendorCell(it), 'c-cven', ruleBadge(it, 'vendor'))},
  {key: 'ccat',    label: 'Category',               cls: 'c-ccat',    sort: 'category',
   tabs: ['for_review', 'categorized'],
   // The badge goes INSIDE the cell. Concatenated in front of it, it became an
   // extra item in the ROW's flex layout and pushed every column after it out
   // of line -- which is what threw the whole grid out.
   cell: it => selectCell(it, 'category', categoryCell(it), 'c-ccat',
                          ruleBadge(it, 'category'), splitBadge(it))
     + (it.needs_qbo
        ? `<span class="tier" title="${esc(it.needs_qbo)} — create it in QuickBooks, or Add will be refused"
                 style="background:#fef3c7;color:#92400e;margin-left:6px"
           >NOT IN QBO</span>`
        : '')},
  {key: 'ven',     label: 'Bank Detail',            cls: 'c-ven',     sort: 'vendor',
   // The flag rides with the bank detail, since that is where the evidence for
   // it came from -- there is no currency field in any export.
   cell: it => editable(it, 'merchant', it.merchant, 'c-ven')},
  {key: 'prof',    label: 'Profile',                cls: 'c-prof',    sort: 'profile',
   // A Credit Card Profiles rule set it: the blue RULE badge after the name.
   cell: it => it.profile_rule && !editingCell(it.id, 'profile')
     ? editable(it, 'profile', it.holder, 'c-prof').replace(/<\/span>$/,
         ` <span class="tag tag-rule" title="${esc(it.profile_rule)}">RULE</span></span>`)
     : editable(it, 'profile', it.holder, 'c-prof')},
  {key: 'amt',     label: 'Amount',                 cls: 'c-amt',     sort: 'amount',
   // Two kinds of money coming back, and they mean different things: a refund
   // reverses a purchase, a payment settles the card. Color and badge say
   // which without reading the description.
   cell: it => {
     const tm = it.transfer_match;
     // A CHECKING WITHDRAWAL that pairs with a card payment IS a payment,
     // whatever its description says -- badged so, like the card side.
     const pay = (it.is_credit && it.is_card_payment) || (tm && !it.is_credit);
     const ref = it.is_credit && !it.is_card_payment;
     const color = pay ? 'var(--ok)' : ref ? 'var(--bad)' : '';
     const badge = (pay
       ? '<span class="tag tag-pay">PAYMENT</span>'
       : ref ? '<span class="tag tag-ref">REFUND</span>' : '')
       // THE OTHER SIDE OF A TRANSFER already in QuickBooks: Match links it to
       // that entry without recording it again. Beside the PAYMENT badge too:
       // a card-side payment can be the side still waiting.
       + (tm ? `<button class="tmMatch" data-id="${esc(it.id)}"
            title="${tm.pair === 'both'
              ? `Pairs with ${esc(tm.other_account)} on ${esc(fmtDate(tm.other_date))}, also waiting. Match posts the payment to QuickBooks once and clears both rows.`
              : `Already in QuickBooks: ${esc(tm.qbo_txn_type)} ${esc(tm.qbo_txn_id)}, recorded from ${esc(tm.other_account)} on ${esc(fmtDate(tm.other_date))}. Match links this row to it; nothing is written to QuickBooks.`}"
            style="margin-left:6px;padding:1px 8px;font-size:11px;font-weight:600;
                   background:#e8f1fb;color:#1f4f6b;border:1px solid #bcd9ee;border-radius:10px;
                   cursor:pointer">Match Transfer</button>` : '')
       // A NEAR MISS: something close on another account that can't be
       // paired -- the reason on hover, so a test isn't guesswork.
       + (!tm && it.transfer_why ? `<span class="tmWhy" title="${esc(it.transfer_why)}"
            style="margin-left:6px;display:inline-block;width:16px;height:16px;line-height:16px;
                   text-align:center;border-radius:50%;background:#fff4e5;color:#9a3412;
                   border:1px solid #fdba74;font-size:11px;font-weight:700;cursor:help">?</span>` : '');
     // The flag rides with the AMOUNT, not the bank detail: it is a fact about
     // the money, and here it behaves like the other badges instead of
     // disturbing the columns that follow.
     const flag = it.is_canadian
       ? `<span title="Charged in Canadian dollars"
            style="display:inline-flex;vertical-align:middle;margin-left:6px"
          ><svg viewBox="0 0 24 16" width="18" height="12" aria-hidden="true">
             <rect width="24" height="16" fill="#fff"/>
             <rect width="6" height="16" fill="#d52b1e"/>
             <rect x="18" width="6" height="16" fill="#d52b1e"/>
             <path fill="#d52b1e" d="M12 3.4l.9 1.9 2-.5-.7 1.9 1.6 1-1.6.6.4 1.8-1.8-.5-.3 1.9h-1l-.3-1.9-1.8.5.4-1.8L8.2 7.7l1.6-1-.7-1.9 2 .5z"/>
           </svg></span>`
       : '';
     return `<span class="c-amt"${color ? ` style="color:${color}"` : ''}
       title="${pay ? 'Payment onto the card' : ref ? 'Refund — money returned' : ''}"
       >${it.is_credit ? `${esc(fmtAmt(-Math.abs(it.amt)))}` : `${esc(fmtAmt(it.amt))}`}${badge}${flag}</span>`;
   }},
  {key: 'l4',      label: 'CC Last 4/5',              cls: 'c-l4',      sort: 'l4',
   // Editable, because everything downstream is inferred from it: the wrong
   // four resolves to the wrong cardholder, which drives the profile and the
   // STH lookup. Some feeds carry no card number at all.
   // `card`, not `card_last4`. The queue names this field `card` -- the row
   // column is card_last4, the item key is not -- and rewriting this cell to
   // add the pencil silently renamed the thing it displays, so the column went
   // blank while the data behind it was correct all along.
   cell: it => `<span class="c-l4">${esc(it.card || '')}${
     CAN.write && !it.qbo_txn_id
       ? `<span class="l4Edit" data-id="${esc(it.id || it.charge_id)}"
            data-v="${esc(it.card || '')}" title="Correct the last four"
            style="cursor:pointer;margin-left:5px;color:var(--tx2);
                   vertical-align:-2px" onclick="event.stopPropagation()"
          >${PENCIL_ICON}</span>` : ''}</span>`},
  {key: 'memo',    label: 'QBO Memo',               cls: 'c-memo',    sort: 'memo',
   // Editable in its own right, and still rewritten whenever Bank Detail or
   // Profile changes -- those two describe it, so a later edit to either wins.
   cell: it => editable(it, 'memo', it.memo, 'c-memo')},
  // CUSTOM NOTES: your own note on a charge -- editable in place, sorted,
  // found by the quick search and exported; kept in the engine, never sent
  // to QuickBooks.
  {key: 'note',    label: 'Custom Notes',           cls: 'c-note',    sort: 'note',
   cell: it => editable(it, 'custom_note', it.custom_note || '', 'c-note')},
  {key: 'ord',     label: 'Order #',                cls: 'c-ord',     sort: 'ord',
   tabs: ['for_review', 'categorized', 'excluded'],
   cell: it => `<span class="c-ord">${it.order_number
     ? esc(it.order_number)
     : '<span style="color:var(--tx2)">—</span>'}</span>`},
  // The identifier the portal gave the transaction, captured on upload. Sits
  // beside Order # because both are "what the source called it".
  {key: 'scur',    label: 'Source Currency',        cls: 'c-scur',    sort: 'scur',
   tabs: ['for_review', 'categorized', 'excluded'],
   cell: it => `<span class="c-scur">${it.source_currency
     ? esc(it.source_currency)
     : '<span style="color:var(--tx2)">—</span>'}</span>`},
  {key: 'samt',    label: 'Source Amount',          cls: 'c-samt',    sort: 'samt',
   tabs: ['for_review', 'categorized', 'excluded'],
   // Formatted as MONEY, with the currency it is actually in.
   //
   // A bare "1,442.35" beside a dollar Amount column reads as dollars, and it
   // is the one column on the grid that is deliberately NOT dollars. The code
   // comes from the charge, so a Canadian charge says CAD and a British one
   // says GBP rather than all of them implying USD.
   cell: it => `<span class="c-samt">${it.source_amount != null
     ? `${esc(CUR_SYM[it.source_currency] || '')}${esc(fmtNum(it.source_amount))}${
         it.source_currency && !CUR_SYM[it.source_currency]
           ? ' ' + esc(it.source_currency) : ''}`
     : '<span style="color:var(--tx2)">—</span>'}</span>`},

  // Same first-column treatment as the charge grids, and the same two things
  // you can do to one bill.
  // "Platform TXN ID", not "TXN ID": there are two transaction ids on this row
  // "TXN ID" beside "QBO Txn ID" did not say which system this one came from.
  {key: 'txnid',   label: 'Platform TXN ID',        cls: 'c-txnid',   sort: 'txnid',
   tabs: ['for_review', 'categorized', 'excluded'],
   cell: it => `<span class="c-txnid" title="${esc(it.txn_id || '')}">${it.txn_id
     ? esc(it.txn_id)
     : '<span style="color:var(--tx2)">—</span>'}</span>`},
  // When it arrived in the feed, as against when it was categorized.
  {key: 'upts',    label: 'Ingestion Time Stamp',    cls: 'c-upts',    sort: 'upts',
   tabs: ['for_review', 'categorized'],
   cell: it => `<span class="c-upts">${it.uploaded_at
     ? esc(localStamp(it.uploaded_at))
     : '<span style="color:var(--tx2)">—</span>'}</span>`},
  {key: 'status',  label: 'Match Strength',         cls: 'c-status',  sort: 'status',
   // Only a bill payment HAS a match strength. On an expense the column was
   // reporting "None", which reads as a failed match rather than a question
   // that was never asked.
   tabs: ['for_review', 'categorized'],
   cell: it => it.force_matched
     ? `<span class="c-status"><span class="tag" style="background:#e2e8f0;
          color:#475569;margin:0" title="Matched by hand, bypassing the gates"
          >Forced</span></span>`
     : (status_ === 'categorized' && it.resolution !== 'matched')
     ? `<span class="c-status" style="color:var(--tx2)">—</span>`
     : statusCell(it)},
  {key: 'kind',    label: 'Transaction Type',       cls: 'c-kind',    sort: 'kind',
   tabs: ['categorized'],
   cell: it => `<span class="c-kind">${esc(kindOf(it))}</span>`},
  {key: 'details', label: 'Additional Details',     cls: 'c-details', sort: 'details',
   tabs: ['categorized'],
   // Whatever there is to say about this row beyond its own columns. A bill
   // payment describes the bill it settled. A charge ADDED against a season
   // ticket account has no bill, but it does have the STH record behind it --
   // the same account shown on For Review, which used to disappear the moment
   // the row was coded. Anything else genuinely has nothing more to say.
   cell: it => {
     // A charge the hourly sweep has flagged looks identical to a healthy one
     // otherwise -- same status, same bill, same everything. The badge is the
     // only thing that distinguishes them.
     const warn = '';
     if (it.resolution === 'matched') {
       // A forced match can cover several bills; matched_bill_* names only the
       // first, so a two-bill payment reported one and looked wrong.
       const lines = it.bill_lines || [];
       if (lines.length > 1) {
         const txt = lines.map(l =>
           `Bill ${l.bill_no} · ${fmtAmt(l.amount)}`
           + (l.vendor ? ` · ${l.vendor}` : '')).join('   +   ');
         return `<span class="c-details" title="${esc(txt)}">`
           + `<span class="tag tag-split" style="margin:0 6px 0 0">${lines.length} BILLS</span>`
           + esc(txt) + `</span>${warn}`;
       }
       const d = detailsOf(it);
       // The strength that produced this match, kept beside it: on Categorized
       // the question is "how confident was this?", and the answer belongs with
       // the bill it chose.
       // The number here, the word in the Match Strength column: this cell is
       // read when you want the detail, that one when you want the band.
       const band = it.force_matched
         ? `<span title="Matched by hand, bypassing the date and amount gates"
              style="display:inline-flex;vertical-align:middle;margin-right:6px;
                     color:#475569">${ACT_ICONS.force}</span>`
         : (it.tier && it.score)
         ? `<span class="tier t-${it.tier}" style="margin-right:6px"
              title="${esc(it.tier)}">${it.score}%</span>`
         : '';
       return `<span class="c-details" title="${esc(d)}">${band}${esc(d)}</span>${warn}`;
     }
     // The SAME renderer For Review uses -- halPills -- not a text rewrite of
     // it. The pills carry the tick, the cross, the calendar and the variance
     // coloring, and a coded charge is read for exactly the reasons an
     // uncoded one is. Two renderers for one set of facts is how the two
     // drifted apart in the first place.
     const h2 = it.hal;
     if (h2) {
       const txt = halDetailsOf(it);      // plain text, for the hover
       // The pills go inside a single tm-b child, exactly as For Review nests
       // them. As direct children of the flex row they each picked up the
       // container's 10px gap on top of their own margins, which is why the
       // ticks and crosses sat further apart here than there.
       return `<span class="c-details tm-hal" title="${esc(txt)}">`
         + `<span class="tier" style="background:#e6eefb;color:var(--accent)`
         + `">STH</span>`
         + `<span class="tm-b"><b>${esc(h2.lookup_name || '—')}</b>`
         + `${halPills(h2)}</span></span>${warn}`;
     }
     const hal = halDetailsOf(it);
     if (hal) {
       // Badged, so the season account is not mistaken for a bill at a glance.
       return `<span class="c-details" title="${esc(hal)}"
         ><span class="tier" style="background:#e6eefb;color:var(--accent);
                margin-right:6px">STH</span>${esc(hal)}</span>${warn}`;
     }
     return `<span class="c-details" style="color:var(--tx2)">N/A</span>${warn}`;
   }},
  {key: 'user',    label: 'User',                   cls: 'c-user',    sort: 'user',
   tabs: ['categorized'],
   // For an automatic coding this says WHAT decided it, not just that
   // something did. "system-rule" told a reviewer nothing they could act on;
   // "system — Bank Feed Rule: Ticketmaster" points straight at the rule to
   // change. A person's username is shown unchanged.
   cell: it => {
     const who = it.resolved_by || '';
     if (!who.startsWith('system')) {
       return `<span class="c-user" title="${esc(who)}">${esc(who)}</span>`;
     }
     const why = ruleProvenance(it);
     const txt = why ? `system — ${why}` : who;
     return `<span class="c-user" title="${esc(txt)}">${esc(txt)}</span>`;
   }},
  {key: 'ts',      label: 'Categorized Time Stamp',             cls: 'c-ts',      sort: 'ts',
   tabs: ['categorized'],
   // The stamp is the FIRST decision. Anything done to the charge afterwards
   // gets a marker beside it -- see editedSince.
   cell: it => `<span class="c-ts">${esc(localStamp(it.resolved_at_utc))}${
     editedSince(it)}</span>`},
  // The id QuickBooks gave the transaction this charge became. Its use is
  // looking a row up over there, so it is shown verbatim -- an em dash where
  // there is none means the post never landed, which is worth seeing.
  {key: 'ingest',  label: 'Ingestion Method',       cls: 'c-ingest',  sort: 'ingest',
   // How this charge arrived. Per charge rather than per card account: one
   // account holds uploads from before an API was connected and pulls since,
   // and after a switchover the question is always which rows are which.
   // Plain text. A pill implies something to act on, and this column is a fact
   // about where the row came from -- read once when a total looks odd, not
   // scanned. The colored badges are on Card Accounts, where the question is
   // "is this feed live", which IS actionable.
   cell: it => `<span class="c-ingest">${esc(
     {csv: 'CSV', api: 'API', plaid: 'Plaid'}[it.ingest_method || 'csv']
     || it.ingest_method || '')}</span>`},
  {key: 'qbo',     label: 'QBO Txn ID',             cls: 'c-qbo',     sort: 'qbo',
   tabs: ['categorized'],
   // A CHANGED marker when QuickBooks holds something different.
   //
   // Somebody editing a vendor or category in QuickBooks used to leave no
   // trace here at all -- unlike a deletion, which brings the charge back to
   // the queue. The badge names both sides on hover, because "changed" without
   // saying to what is only half an answer.
   cell: it => it.qbo_txn_id
     ? `<span class="c-qbo" title="${esc(it.qbo_txn_type || '')} ${esc(it.qbo_txn_id)}"
         >${esc(it.qbo_txn_id)}${driftBadge(it)}</span>`
     : `<span class="c-qbo" style="color:var(--tx2)">—</span>`},
  // Empty until an upload carries them. A dash rather than a guess: a blank
  // source currency means the file did not say, which is not the same as USD.
];

const BILL_COLUMNS = [
  {key: 'bact',  label: 'Action',   cls: 'b-act',  fixed: true,
   cell: b => `<span class="b-act">`
     + actBtn('rowBillSplit ico-split', b.bill_id, 'split', 'Split bill')
     + actBtn('rowBillDelete ico-del', b.bill_id, 'trash', 'Delete bill')
     + `</span>`},

  // COMPANY, right after Action -- only in Multi-Company, where rows from
  // every company share the grid.
  {key: 'company', label: 'Company', cls: 'b-company', sort: 'company', fixed: true,
   multi: true,
   cell: b => `<span class="b-company" title="${esc(b.company || '')}">${esc(b.company || '')}</span>`},
  {key: 'bno',   label: 'Bill No.', cls: 'b-no',   sort: 'bill',    fixed: true,
   cell: b => `<span class="b-no">${esc(b.bill)}</span>`},
  {key: 'bven',  label: 'Vendor',   cls: 'b-ven',  sort: 'vendor',
   // A bill's vendor is editable in place; the amount has its own dialog,
   // because "what should it become" has three different answers.
   cell: b => CAN.write
     ? `<span class="b-ven"><button class="billven cellsel" data-id="${esc(b.bill_id)}"
          data-value="${esc(b.vendor)}" title="${esc(b.vendor)}">
          <span class="cs-v">${esc(b.vendor)}</span><span class="cs-c">▾</span>
        </button></span>`
     : `<span class="b-ven" title="${esc(b.vendor)}">${esc(b.vendor)}</span>`},
  {key: 'bdate', label: 'Date',     cls: 'b-date', sort: 'date',
   cell: b => `<span class="b-date">${fmtDate(b.date)}</span>`},
  {key: 'bamt',  label: 'Amount',   cls: 'b-amt',  sort: 'amount',
   cell: b => `<span class="b-amt">${esc(fmtAmt(b.amt))}${CAN.write
     ? `<button class="billamt ed-open" data-id="${esc(b.bill_id)}" title="Change amount"
                style="background:none;border:none;cursor:pointer;color:var(--tx2);
                       font-size:11px;padding:0 0 0 5px">✎</button>` : ''}</span>`},
  {key: 'bbal',  label: 'Balance',  cls: 'b-bal',  sort: 'balance',
   cell: b => `<span class="b-bal">${esc(fmtAmt(b.balance))}</span>`},
  // Ages from the due date (net 30 on the bill date), the way QuickBooks' A/P
  // Aging report does. Color rises with the bucket so an old bill stands out
  // without reading the label.
  {key: 'bmemo', label: 'Memo', cls: 'b-memo', sort: 'memo',
   cell: b => `<span class="b-memo" title="${esc(b.memo)}">${esc(b.memo)}</span>`},
  // THE CLASS on the bill's lines (several, comma separated, when they differ).
  {key: 'bclass', label: 'Class', cls: 'b-class', sort: 'class',
   cell: b => `<span class="b-class" title="${esc(b.class || '')}">${b.class ? esc(b.class) : '<span style="color:var(--tx2)">\u2014</span>'}</span>`},
  // A bill has no separate transaction id: the bill IS the QuickBooks
  // transaction, so its id is what you would search for over there.
  {key: 'bage',  label: 'Aging',    cls: 'b-age',
   cell: b => `<span class="b-age" title="${b.aging_days > 0
       ? b.aging_days + ' days past due' : 'not yet due'}">${b.aging
     ? esc(b.aging) : '<span style="color:var(--tx2)">—</span>'}</span>`},
  {key: 'bqbo',  label: 'QBO Txn ID', cls: 'b-qbo', sort: 'qbo',
   cell: b => `<span class="b-qbo">${esc(b.bill_id)}</span>`},
];

// Per-user layout, loaded from the server on sign-in.
//   PREFS.order[tab]   -> array of column keys
//   PREFS.hidden[tab]  -> array of column keys
//   PREFS.widths       -> {colKey: px}, shared across tabs so a column you
//                         widened stays that width wherever it appears
// gridw: per-grid column widths for the secondary grids (audit log, tables,
// card accounts). Separate from `widths`, which is the Bank Feed's own and is
// keyed by column key across all of its tabs.
let PREFS = {order: {}, hidden: {}, widths: {}, gridw: {}};
let PAGEINFO_STEM = '';
let SIGNOUT_NOTE = '';
// Per-browser rather than per-user: this is about the screen you're on, not a
// preference worth syncing.
const BANDS_KEY = 'ys_bands_hidden';
let BANDS_HIDDEN = false;
// Where the toggle sits while the row is expanded, so it can hold that spot
// once its neighbors are gone.
let BANDS_LEFT = 0;
// Which single cell is open for editing: "chargeId::field". One field at a
// time, edited where it lives -- a pencil at the end of the row made you look
// for what it applied to. Excluded rows are read-only: they were set aside
// deliberately and nothing about them reaches QuickBooks.
let EDIT_CELL = '';
const editableHere = () =>
  status_ === 'for_review' || status_ === 'categorized';
const editingCell = (id, field) => EDIT_CELL === `${id}::${field}`;

// Vendor and Category are chosen from QuickBooks' own lists, so the cell is a
// dropdown rather than a free-text box -- there is nothing to type that isn't
// already on the list, and a typo fails at post time.
//
// A native <select> can't be searched, and these lists run to hundreds of
// accounts, so this is the same shape as the Cards menu: one floating panel,
// reused by every cell, with a type-to-narrow box at the top.
function selectCell(it, field, value, cls, after = '', before = '') {
  // `after` is markup, not text: everything else here is escaped because the
  // value is echoed into data-value as well, and a badge smuggled through that
  // string came out as visible angle brackets.
  if (!editableHere()) {
    return `<span class="${cls}">${before}<span class="cell-ro" title="${esc(value)}"
      >${esc(value)}</span>${after}</span>`;
  }
  // No inline stopPropagation here: it kept the click from ever reaching the
  // handler that opens the picker. The row's expand toggle already ignores
  // clicks on a button, so nothing needs stopping.
  return `<span class="${cls}">${before}<button class="cellsel" data-id="${esc(it.id)}"
      data-field="${field}" data-value="${esc(value)}" title="${esc(value)}">
    <span class="cs-v">${esc(value) || '<i style="color:var(--tx2)">Choose…</i>'}</span>
    ${after}<span class="cs-c">▾</span></button></span>`;
}

// What to say after a single-field edit. One place, so the pencil and the
// dropdown can't drift apart -- and always a flash rather than a dialog: a
// successful save is not something to click OK about.
const FIELD_LABEL = {profile: 'Profile', memo: 'Memo', merchant: 'Bank Detail',
                     vendor: 'Vendor', category: 'Category'};

function flashEdit(field, qbo) {
  // On For Review nothing has been committed yet -- picking a vendor or a
  // category is setting up the decision, not making it. The cell already shows
  // the new value, so a flash for each one is noise between you and the Add.
  //
  // On Categorized the same edit rewrites a transaction that already exists in
  // QuickBooks, which is worth confirming.
  if (status_ === 'for_review') return;
  const label = FIELD_LABEL[field] || 'Change';
  flash(qbo === 'replaced with an expense' ? 'Changed to Expense'
        : `${label} updated`);
}

// Create a vendor or category in QuickBooks, then add it to the in-memory list
// so it is selectable straight away rather than after the next reference sync.
async function createRef(field, name) {
  const isVendor = field === 'vendor';
  const label = isVendor ? 'vendor' : 'category';
  // Category accounts need a type; QuickBooks has no sensible default for one.
  let acctType = 'Expense';
  let parentId = '';
  if (!isVendor) {
    const picked = await pickAccountType(name);
    if (!picked) return null;
    acctType = picked.kind || 'Expense';
    parentId = picked.parent || '';
  } else {
    const go = await askConfirm('Create vendor',
      `Create <b>${esc(name)}</b> as a new vendor in QuickBooks?`,
      'Create', 'Cancel', {goGreen: true});
    if (!go) return null;
  }
  const fd = new FormData();
  fd.append('name', name);
  if (!isVendor) {
    fd.append('account_type', acctType);
    if (parentId) fd.append('parent_id', parentId);
  }
  try {
    const r = await api(isVendor ? '/qbo/vendors/create' : '/qbo/categories/create',
                        {method: 'POST', body: fd});
    if (isVendor) VENDORS = [...VENDORS, {name: r.name}];
    else CATEGORIES = [...CATEGORIES, {name: r.name, fully_qualified: r.name}];
    flash(r.created ? `${isVendor ? 'Vendor' : 'Category'} created`
                    : `Already in QuickBooks`);
    return r.name;
  } catch (e) {
    notify(e.message, `Could not create the ${label}`);
    return null;
  }
}

// QuickBooks refuses an account without a type, and there is no safe default:
// an expense and a cost of goods account behave differently on the P&L.
// Three outcomes, not two, so this is its own dialog rather than a confirm:
// Bank, Credit Card, or neither.
function pickBankOrCard(name) {
  return new Promise(resolve => {
    const box = $('#bankOrCard');
    $('#bankOrCardName').textContent = name;
    $('#bocBank').onclick = () => { box.close(); resolve('Bank'); };
    $('#bocCard').onclick = () => { box.close(); resolve('Credit Card'); };
    $('#bocCancel').onclick = () => { box.close(); resolve(null); };
    box.showModal();
  });
}

// THE SAME dialog Chart of Accounts uses -- Account Type and Subaccount, in
// two labeled rows. There were two different windows for creating the same
// thing, one per screen, and only one of them could offer a parent.
//
// Returns {kind, parent} so the caller can send both.
async function pickAccountType(name) {
  const got = await askForText(`Create "${name}"`, '', '', name,
                               ACCT_TYPES, CATEGORY_PARENTS());
  if (!got) return null;
  return typeof got === 'object' ? got : {kind: got, parent: ''};
}

// The accounts a new category can hang under. Built from the loaded category
// list, which is what this screen already has -- the Chart of Accounts screen
// reads its own grid rows for the same purpose.
function CATEGORY_PARENTS() {
  // The /qbo/categories payload names these `id` and `type`; the Chart of
  // Accounts grid names the same things `qbo_id` and `account_type`. Reading
  // only one pair meant this list came back empty on the transactions tab and
  // the Subaccount row never appeared at all.
  return (CATEGORIES || [])
    .map(c => ({qbo_id: c.qbo_id || c.id || '',
                name: c.fully_qualified || c.name || '',
                account_type: c.account_type || c.type || ''}))
    .filter(c => c.qbo_id && c.name);
}

function closePicker() {
  const p = $('#cellpick');
  if (p) p.style.display = 'none';
}

// One label, used to build the option and to recognize it when picked.
const SPLIT_OPT = '\u29C9  Split across categories…';

// In Multi-Company the vendor and category lists are the ROW's company's.
// Kept per company so moving between rows does not reload them.
const REF_CACHE = {};
async function useRefsFor(co) {
  if (!co || co === ALL_COMPANIES) return;
  if (!REF_CACHE[co]) {
    const c = encodeURIComponent(co);
    const [cats, vens] = await Promise.all([
      api(`/qbo/categories?company=${c}`).catch(() => ({})),
      api(`/qbo/vendors?company=${c}`).catch(() => ({}))]);
    REF_CACHE[co] = {cats: cats.categories || [], vens: vens.vendors || []};
  }
  CATEGORIES = REF_CACHE[co].cats; VENDORS = REF_CACHE[co].vens;
}

function openPicker(btn, opts) {
  if (isAllCompanies() && btn && btn.dataset && btn.dataset.id && !btn.__refsReady) {
    const it = (QUEUE.items || []).find(x => String(x.id) === String(btn.dataset.id));
    useRefsFor(rowCompany(it)).then(() => { btn.__refsReady = true; openPicker(btn, opts); btn.__refsReady = false; });
    return;
  }
  const {id, field} = btn.dataset;
  const cur = btn.dataset.value || '';
  // `opts` lets another grid reuse this picker with its own list and its own
  // idea of what picking means.
  // Splitting IS a way of categorizing, so it heads the category list rather
  // than living as its own icon on every row.
  const canSplit = field === 'category' && CAN.write
    && (status_ === 'for_review' || status_ === 'categorized');
  // A CARD PAYMENT'S CATEGORY IS A BANK ACCOUNT: the one it was paid from.
  // Its picker offers bank accounts only, and no split -- expense and asset
  // accounts were never a right answer for money moving between two accounts
  // the company owns.
  const _row = (QUEUE.items || []).find(x => String(x.id) === String(id));
  const isPay = !!(_row && _row.is_card_payment);
  const list = opts ? opts.list()
    : field === 'category'
      ? (isPay
          ? CATEGORIES.filter(c => c.is_bank).map(c => c.fully_qualified || c.name)
          : (canSplit ? [SPLIT_OPT] : []).concat(
              CATEGORIES.map(c => c.fully_qualified || c.name)))
    : VENDORS.map(v => v.name || v);

  const box = $('#cellpick');
  // A modal <dialog> renders in the browser's TOP LAYER, which sits above every
  // z-index on the page -- so the picker opened behind the dialog no matter how
  // high its z-index went. Moving the node inside the open dialog puts it in
  // the same layer. It is position:fixed, so its coordinates do not change.
  const host = btn.closest('dialog[open]') || document.body;
  if (box.parentElement !== host) host.appendChild(box);
  const r = btn.getBoundingClientRect();
  box.style.display = 'block';
  box.style.left = Math.min(r.left, window.innerWidth - 330) + 'px';
  // Flip above the cell when there isn't room below.
  const below = window.innerHeight - r.bottom;
  box.style.top = (below > 280 ? r.bottom + 4 : Math.max(8, r.top - 284)) + 'px';

  const draw = needle => {
    const n = needle.trim().toLowerCase();
    const hits = list.filter(x => !n || x.toLowerCase().includes(n)).slice(0, 300);
    // Clearing is a real choice -- a suggestion you disagree with should be
    // removable without inventing a replacement.
    // Not on Categorized: those transactions are in QuickBooks, and a category
    // cleared to nothing is not a state a posted transaction can be in.
    const clearOpt = (cur && status_ === 'for_review')
      ? `<div class="cp-o cp-clear" style="color:var(--tx2);font-style:italic">Clear</div>`
      : '';
    // Offer to create what was typed when nothing matches it exactly. Coding a
    // charge against a vendor QuickBooks has never heard of used to mean
    // leaving the app, making it there, and coming back.
    const typed = needle.trim();
    const exact = list.some(x => x.toLowerCase() === typed.toLowerCase());
    const creatable = opts ? opts.canCreate : field;
    const addOpt = (typed && !exact && CAN.write && creatable)
      ? `<div class="cp-o cp-add" style="color:var(--accent);font-weight:600"
              data-name="${esc(typed)}">+ Create “${esc(typed)}”</div>`
      : '';
    // Create goes LAST. It's the fallback, and putting it above the list meant
    // Enter or a quick click reached for it before the vendor that was already
    // there one line below.
    $('#cellpickList').innerHTML = clearOpt + (hits.length
      ? hits.map(x => `<div class="cp-o${
          (opts && opts.multi
            ? (opts.chosen() || []).includes(x)
            : x === cur) ? ' on' : ''}"${
          opts && opts.multi
            ? ` data-tick="${(opts.chosen() || []).includes(x) ? '1' : '0'}"`
            : ''}`
          + ` data-v="${esc(x)}">${
            // A real tick box in multi mode, so "selected" is visible at a
            // glance rather than inferred from a highlight.
            opts && opts.multi
              ? `<span class="cp-tick">${
                  (opts.chosen() || []).includes(x) ? '\u2713' : ''}</span>`
              : ''}${esc(x)}`
          + `${opts && opts.badge ? opts.badge(x) : ''}</div>`).join('')
      : (typed ? '' : `<div class="cp-empty">Nothing matches “${esc(needle)}”</div>`))
      + addOpt;
    $('#cellpickList').querySelectorAll('.cp-o').forEach(o => o.onclick = async () => {
      // THE BANK FEED'S SPLIT. A grid with its own list (Bank Feed Rules)
      // offers the same words and handles them in its own onPick -- this used
      // to catch them first and open the charge split for a rule id, so the
      // rules' split did nothing.
      if (!opts && (o.dataset.v || '') === SPLIT_OPT) {
        closePicker();
        splitDialog([btn.dataset.id]);
        return;
      }
      // Creating happens first, then the new name is applied like any other.
      if (o.classList.contains('cp-add')) {
        const made = await createRef(creatable, o.dataset.name);
        if (!made) return;
        closePicker();
        if (opts) { await opts.onPick(made); return; }
        const fd = new FormData();
        fd.append('charge_id', id);
        fd.append(field, made);
        try {
          const res = await api('/queue/edit', {method: 'POST', body: fd});
          flashEdit(field, res.qbo);
          await load();
        } catch (e) { notify(e.message, 'Could not save'); }
        return;
      }
      const wantsClear = o.classList.contains('cp-clear');
      // data-v, not textContent: an option may render a badge beside its
      // label, and the badge is not part of the value.
      const val = o.dataset.v != null ? o.dataset.v : o.textContent;
      // MULTI MODE: tick, stay open, keep picking.
      //
      // The close moved BELOW this branch: it ran first, so the list shut and
      // the redraw painted ticks onto a closed picker -- one choice per open,
      // which is not a multi-select.
      //
      // A filter over hundreds of vendors needs the search box, so it reuses
      // this picker rather than the plain checkbox menus -- but a list you
      // must reopen for every choice is not a multi-select in any useful
      // sense.
      if (opts && opts.multi) {
        await opts.onPick(wantsClear ? '' : val);
        if (wantsClear) { closePicker(); return; }   // "Clear" means done
        draw($('#cellpickSearch').value);            // ticks, in place
        return;
      }
      closePicker();
      // A CALLER WITH ITS OWN onPick IS ASKED FIRST.
      //
      // "same value, nothing to do" is true when this picker edits a charge,
      // but not for the multi-select filter, where picking a selected value
      // REMOVES it. Returning early skipped the callback and fell through to
      // the charge-edit path below -- which is why choosing a vendor in the
      // filters tried to save a charge and reported "charge not found".
      if (opts) { await opts.onPick(wantsClear ? '' : val); return; }
      if (!wantsClear && val === cur) return;
      const fd = new FormData();
      fd.append('charge_id', id);
      fd.append(field, wantsClear ? '' : val);
      if (wantsClear) fd.append('clear', field);
      try {
        const res = await api('/queue/edit', {method: 'POST', body: fd});
        flashEdit(field, res.qbo);
        await load();
      } catch (e) { notify(e.message, 'Could not save'); }
    });
  };

  const search = $('#cellpickSearch');
  search.value = '';
  search.oninput = () => draw(search.value);
  // Enter takes the first option, which is the Create row when the typed name
  // is new -- so a vendor can be added without reaching for the mouse.
  search.onkeydown = e => {
    if (e.key !== 'Enter') return;
    e.preventDefault();
    // Enter takes the first real option, which is an existing name when one
    // matches and the Create row only when nothing does.
    const first = $('#cellpickList').querySelector('.cp-o:not(.cp-clear)');
    if (first) first.click();
  };
  draw('');
  setTimeout(() => search.focus(), 0);
}

// A click INSIDE the picker never reaches the document closer.
//
// Same trap as the multi-select menus (see renderMulti): redrawing the list to
// show a new tick DETACHES the option that was clicked, so by the time the
// event bubbles up it has no ancestors and `closest('#cellpick')` is null --
// an inside click read as an outside one, and the picker shut after every
// choice. The propagation path is fixed when the event is dispatched, so a
// listener on the container itself still fires and can stop it.
(function () {
  const cp = document.querySelector('#cellpick');
  if (cp) cp.addEventListener('click', e => e.stopPropagation());
})();

// Closing only. Opening is bound per button in wireRows, like every other
// in-row control, so it survives the row's own click handling.
document.addEventListener('click', e => {
  if (e.target.closest('#cellpick') || e.target.closest('.cellsel')
      || e.target.closest('.cellsel-static')) return;
  closePicker();
});

// A pencil, or the input plus its save/cancel once opened.// A pencil, or the input plus its save/cancel once opened.
function editable(it, field, value, cls, extraAttrs = '') {
  if (!editableHere()) {
    return `<span class="${cls}"><span class="cell-ro" title="${esc(value)}"
      >${esc(value)}</span></span>`;
  }
  if (!editingCell(it.id, field)) {
    return `<span class="${cls}" title="${esc(value)}">${esc(value)}`
      + `<button class="ed-open" data-id="${esc(it.id)}" data-field="${field}"
                 title="Edit" onclick="event.stopPropagation()"
                 style="background:none;border:none;cursor:pointer;color:var(--tx2);
                        font-size:11px;padding:0 0 0 5px;line-height:1">✎</button></span>`;
  }
  return `<span class="${cls}" style="display:flex;gap:4px;align-items:center">
    <input class="ed-input" data-id="${esc(it.id)}" data-field="${field}"
           value="${esc(value)}" ${extraAttrs}
           style="flex:1;min-width:0;font-size:12px;padding:2px 4px"
           onclick="event.stopPropagation()">
    <button class="ed-save" data-id="${esc(it.id)}" data-field="${field}" title="Save"
            onclick="event.stopPropagation()"
            style="background:#15803d;color:#fff;border:1px solid #15803d;
                   border-radius:4px;padding:1px 6px;font-size:11px">✓</button>
    <button class="ed-cancel" title="Cancel" onclick="event.stopPropagation()"
            style="background:none;border:none;color:var(--tx2);cursor:pointer;
                   font-size:12px">✕</button></span>`;
}

const gridKey = () => (isBills() ? 'bills' : status_);
const allColumns = () => (isBills() ? BILL_COLUMNS : CHARGE_COLUMNS);

function availableColumns() {
  const tab = gridKey();
  const base = allColumns().filter(c => (!c.tabs || c.tabs.includes(tab))
    && (!c.multi || isAllCompanies()));
  const order = PREFS.order[tab] || [];
  // A saved order lists only the columns that existed when it was saved. A
  // column added since is slotted in where it is DECLARED -- after whichever
  // saved column precedes it in the definition list -- rather than being sent
  // to the far right where nobody scrolls to find it.
  const declared = base.map(c => c.key);
  const rank = {};
  order.forEach((k, i) => { rank[k] = i; });
  let last = -1;
  declared.forEach(k => {
    if (rank[k] === undefined) rank[k] = last + 0.5;   // just after its neighbor
    else last = rank[k];
  });
  const ranked = [...base].sort((a, b) =>
    (rank[a.key] ?? 0) - (rank[b.key] ?? 0));
  // EVERY pinned column is hoisted to the front, in the order they are declared
  // -- Action, then Card Account. A saved order from before a pinned column
  // existed treats it as new and sends it to the end, and a drop in front of
  // one would otherwise move it. Doing it here means the grid is right whatever
  // the stored order says.
  const pinned = ranked.filter(c => c.fixed);
  if (pinned.length) {
    const rest = ranked.filter(c => !c.fixed);
    const declared = allColumns().filter(c => c.fixed).map(c => c.key);
    pinned.sort((a, b) => declared.indexOf(a.key) - declared.indexOf(b.key));
    return pinned.concat(rest);
  }
  return ranked;
}

function visibleColumns() {
  const hidden = new Set(PREFS.hidden[gridKey()] || []);
  // Every column can be hidden, Amount and Bank Detail included: which ones
  // matter depends on the work, and nobody hides a column by accident from a
  // dialog whose whole purpose is choosing them.
  return availableColumns().filter(c => !hidden.has(c.key));
}

async function savePrefs() {
  try {
    const fd = new FormData();
    fd.append('value', JSON.stringify(PREFS));
    await api('/prefs/columns', {method: 'POST', body: fd});
  } catch (e) { /* a failed save shouldn't interrupt the work */ }
}

// ONE PERSON'S LAYOUT AT A TIME. Signing out does not reload the page, so the
// last person's column widths and order stayed in memory (and on the page's
// width variables) -- and someone signing in after them with no saved layout
// of their own got theirs. Cleared on sign-out and before each load.
function resetPrefsState() {
  PREFS = {order: {}, hidden: {}, widths: {}, gridw: {}};
  try { Object.keys(GRID_W).forEach(k => delete GRID_W[k]); } catch (e) {}
  try { Object.values(COL_VAR || {}).forEach(v => document.documentElement.style.removeProperty(v)); } catch (e) {}
}

async function loadPrefs() {
  resetPrefsState();
  try {
    const r = await api('/prefs/columns');
    if (r.value) {
      const p = JSON.parse(r.value);
      PREFS = {order: p.order || {}, hidden: p.hidden || {},
               widths: p.widths || {}, gridw: p.gridw || {}};
    }
  } catch (e) { /* defaults are fine */ }
  applyWidths();
}

function applyWidths() {
  Object.entries(PREFS.widths || {}).forEach(([key, px]) => {
    if (COL_VAR[key]) {
      document.documentElement.style.setProperty(COL_VAR[key], px + 'px');
    }
  });
}

// Strength is stored per charge, so it stays meaningful after resolution --
// useful for spotting what got coded despite a strong bill match.
const statusCol = () => status_ === 'for_review' || status_ === 'categorized';
// What a charge was resolved TO -- only meaningful once it has been.
const resolutionCols = () => status_ === 'categorized';

// A bill payment has no coded vendor -- it has the BILL's vendor, captured in
// the snapshot at match time. Falling back to it is why this column isn't
// blank for half the tab.
function vendorOf(it) {
  return it.resolution === 'matched'
    ? (it.matched_bill_vendor || '') : (it.coded_vendor || '');
}

// Which of the three things a resolved charge turned into.
const KINDS = [['bill_payment', 'Bill Payments', 'Bill Payment'],
               ['expense', 'Expenses', 'Expense'],
               ['payment', 'Payments', 'Payment'],
               ['refund', 'Refunds', 'Refund']];

function kindKey(it) {
  if (it.resolution === 'matched') return 'bill_payment';
  if (!it.is_credit) return 'expense';
  // Two different things, and the Transaction Type column should say which.
  return it.is_card_payment ? 'payment' : 'refund';
}
function kindOf(it) {
  const k = KINDS.find(x => x[0] === kindKey(it));
  return k ? k[2] : '';
}

// The Strength cell: a score before a charge is resolved, what it became after.
// tabler "adjustments": three sliders, the conventional mark for this.
const ADJ_ICON = `<svg viewBox="0 0 24 24" width="17" height="17" fill="none"
  stroke="currentColor" stroke-width="1.8" stroke-linecap="round"
  stroke-linejoin="round" aria-hidden="true">
  <circle cx="6" cy="10" r="2"/><line x1="6" y1="4" x2="6" y2="8"/>
  <line x1="6" y1="12" x2="6" y2="20"/>
  <circle cx="12" cy="16" r="2"/><line x1="12" y1="4" x2="12" y2="14"/>
  <line x1="12" y1="18" x2="12" y2="20"/>
  <circle cx="18" cy="7" r="2"/><line x1="18" y1="4" x2="18" y2="5"/>
  <line x1="18" y1="9" x2="18" y2="20"/></svg>`;

// The bank-feed badge. A classical bank front -- the same visual language
// QuickBooks uses for a connected account, so nobody has to learn what it
// means. Color carries the health: green connected, amber needs the
// cardholder to log in again, red erroring.
//
// It is a FUNCTION rather than a constant because the same mark appears at two
// sizes, in the Card Accounts grid and in the queue's card picker, and a
// second hand-tuned copy would drift from the first.
const BANK_ICON = (size = 14, color = 'var(--ok)') => `<svg viewBox="0 0 24 24"
  width="${size}" height="${size}" fill="none" stroke="${color}"
  stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"
  aria-hidden="true" style="vertical-align:-2px"><path d="M3 10 12 4l9 6"/>
  <line x1="5" y1="10" x2="5" y2="18"/><line x1="10" y1="10" x2="10" y2="18"/>
  <line x1="14" y1="10" x2="14" y2="18"/><line x1="19" y1="10" x2="19" y2="18"/>
  <line x1="3" y1="20" x2="21" y2="20"/></svg>`;

// One place decides what a connection's state looks like, so the grid and the
// picker can never disagree about a card.
const LINK_LOOK = {
  ok:              {c: 'var(--ok)',  t: 'Connected to the bank feed'},
  login_required:  {c: '#b45309',    t: 'Connection needs the cardholder to sign in again — no new charges are arriving'},
  error:           {c: 'var(--bad)', t: 'Connection is erroring — no new charges are arriving'},
};
// A card account fed by a program API rather than by uploads. Distinct from
// the bank icon, which means a Plaid connection to somebody's own bank -- these
// are different things and were worth different marks: one is a credential a
// cardholder gave, the other is a key the company holds.
// Same shape and size as the VIRTUAL tag beside it -- two labels on one row
// that disagree about their own dimensions read as a mistake.
// Exactly the VIRTUAL tag with different colors -- same class, no size
// overrides. Two labels sitting on one row that disagree about their own
// dimensions read as a mistake.
// Green while the feed is current, amber once it has gone quiet. A program
// account whose token expired returns nothing, which is indistinguishable from
// a card nobody used -- the same failure the bank icon already colors for.
const apiBadge = (staleHours, cls = 'vtag') => {
  const stale = staleHours === null || staleHours === undefined
    ? true                          // configured, never pulled
    : staleHours > 24;
  const tip = staleHours === null || staleHours === undefined
    ? 'Fed by a program API — but it has never pulled anything'
    : stale ? `Fed by a program API — last pulled ${
        staleHours < 48 ? Math.round(staleHours) + 'h'
                        : Math.round(staleHours / 24) + 'd'} ago`
      : 'Fed by a program API — charges arrive on a schedule, not from uploads';
  // The badge stays green and a red ! is appended when the feed is in
  // trouble. An amber badge changed the meaning of the badge itself, so "API"
  // read as a different KIND of thing rather than the same thing with a
  // problem -- and amber-on-green is a distinction nobody reads at a glance.
  // The badge in the SAME class as the VIRTUAL tag beside it, so the two are
  // one size: small tags on the card picker, larger ones on the accounts grid.
  // The warning is its own icon, OUTSIDE the badge -- inside it, a "!" made
  // "API" read as a different label rather than the same one with a problem.
  return `<span class="${cls}" title="${esc(tip)}"
    style="background:#dcfce7;color:#166534;border-color:#86efac">API</span>${
      stale ? `<span class="apiWarn" title="${esc(tip)}"
        style="display:inline-flex;align-items:center;justify-content:center;
               width:${cls === 'tag' ? 16 : 13}px;height:${cls === 'tag' ? 16 : 13}px;
               border-radius:50%;margin-left:4px;background:var(--bad);color:#fff;
               font-size:${cls === 'tag' ? 11 : 9}px;font-weight:700;
               vertical-align:middle">!</span>` : ''}`;
};

// A pencil, matching the one the Card Accounts name field already shows.
// What drove an automatic coding, in words. One function, because the badge
// hover and the User column ask the same question and answering it twice is
// how two descriptions of one fact drift apart.
function ruleProvenance(it) {
  const kind = {bank_rule: 'Bank Feed Rule', teams_table: 'Teams Table',
                payment: 'Card Payment', hal: 'Season Account'}[it.rule_source];
  const name = (it.rule_detail || it.rule_name || '').trim();
  if (kind) return name ? `${kind}: ${name}` : kind;
  // FROM PAST CODING: said as such -- it fell through to "Bank Feed Rule:".
  if (it.from_history) return `Past Coding: coded this way ${it.from_history} times`;
  // Nothing stored: fall back to what this render worked out. Charges coded
  // before provenance was recorded have no stored value, and "we did not keep
  // this" is better said as the rule name alone than as a wrong label.
  if (!name) return '';
  return /^season account/i.test(name) ? `Teams Table: ${
    name.replace(/^season account:\s*/i, '')}` : `Bank Feed Rule: ${name}`;
}

// Symbols for the currencies these cards actually see. Anything else shows its
// three-letter code after the number, which is unambiguous and needs no table.
// The selection count, written to BOTH homes.
//
// #shown sits in the pager row that is always on screen -- "1-200 of 2,233
// Results" -- and #bulkn lives in #pagerbar, a separate row that only some
// screens render. Three attempts at choosing between them each failed on a
// grid the other one covered, so this writes to whichever exist and lets the
// invisible one be harmless.
function setSelectionCount(text) {
  // ONE place: the end of the pagination row.
  //
  // This wrote to every element that might be visible, because I could not
  // tell which one was -- so once they all worked, the count appeared three
  // times. #bulkn is the one #pagerbar creates and keys its own visibility on,
  // which makes it the right single home; the others are cleared here so a
  // stale value cannot linger in a hidden element and reappear.
  // #shown, which sits at the END of the pager row -- "1-200 of 1,815
  // Results  …  500 selected". #bulkn lives in #pagerbar, a band ABOVE the
  // grid, which is where the count kept appearing instead.
  const t = $('#shown');
  if (t) t.textContent = text;
  for (const id of ['#bulkn', '#bulkinlinen', '#billbulkn']) {
    const el = $(id);
    if (el) el.textContent = '';
  }
  // pagerbar carries nothing now, so it should take no height.
  const bar = $('#pagerbar');
  if (bar) bar.style.display = 'none';
}

const CUR_SYM = {USD: '$', CAD: 'CA$', GBP: '\u00a3', EUR: '\u20ac',
                 MXN: 'MX$', AUD: 'A$', JPY: '\u00a5', CHF: 'CHF '};

// "CHANGED IN QBO", with both readings on hover.
// The gold DEP marker. Shown beside the CATEGORY only.
function depBadge(it, forVendor) {
  if (forVendor) return '';
  const cat = it.coded_category || it.suggested_category || '';
  if (!/\(DEP\)\s*$/.test(cat)) return '';
  return `<span class="tag" title="Coded to the deposit account: this charge's
      amount matches a deposit record for the holder"
    style="background:#fef3c7;color:#92400e;border:1px solid #fcd34d;
           margin-right:4px;font-weight:700">DEP</span>`;
}

// A DRAWN notepad, not a glyph.
//
// This has been \u270E, then a red !, then \u{1F5D2} -- and the emoji was the
// worst of the three: the character renders differently on every platform,
// falls back to a monochrome outline on Windows that reads as a rectangle, and
// at any size that fits a table row it is an indistinct smudge. An inline SVG
// looks the same everywhere and can be drawn to be recognizable at 16px: a
// page with a spiral binding down the side and three ruled lines.
const NOTE_ICON = `<svg viewBox="0 0 20 20" width="17" height="17"
    fill="none" stroke="currentColor" stroke-width="1.6"
    stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
  <path d="M5 3.2h9.2a1.6 1.6 0 0 1 1.6 1.6v11.4a1.6 1.6 0 0 1-1.6 1.6H5z"
        fill="currentColor" fill-opacity=".12"/>
  <path d="M8.2 7.6h5M8.2 10.4h5M8.2 13.2h3.2"/>
  <path d="M4.6 5.1h2M4.6 8.2h2M4.6 11.3h2M4.6 14.4h2" stroke-width="1.8"/>
</svg>`;

// SOMETHING WAS DONE TO THIS CHARGE AFTER IT WAS CATEGORIZED.
//
// The User and Categorized Time Stamp columns report the first decision and
// stop. A charge coded on Monday and recoded by somebody else on Friday read
// as though Monday were the whole story, and the only way to find out
// otherwise was to open the audit log and search for the row.
//
// A pencil rather than a word, because it sits inside a timestamp cell and the
// common case is no marker at all -- a column that is blank on 95% of rows
// should cost 95% of rows nothing. The hover names every edit: who, when and
// what, because "edited" without saying by whom is the same half-answer the
// timestamp was already giving.
function editedSince(it) {
  const ev = it.later_edits || [];
  if (!ev.length) return '';
  const n = it.later_edit_count || ev.length;
  // Newest first on hover: the current state of the charge is the last thing
  // that happened to it, and that is what somebody checking is asking about.
  const lines = ev.slice().reverse().map(e =>
    `${localStamp(e.at)} — ${e.actor || 'system'} — ${e.what}`
    + (e.detail ? `: ${e.detail}` : '')).join('\n');
  const more = n > ev.length ? `\n…and ${n - ev.length} earlier` : '';
  // A NOTEPAD. It went pencil, then red exclamation, now this: the
  // exclamation was noticeable and said the wrong thing -- a red ! reads as a
  // fault, and an edit after coding is a note about the row's history, not an
  // error in it. The notepad says "there is more written down here", which is
  // exactly what the hover then gives you.
  return ` <span class="editmark" title="${esc(
    `Edited ${n === 1 ? 'once' : n + ' times'} after it was categorized\n\n`
    + lines + more)}">${NOTE_ICON}</span>`;
}

function driftBadge(it) {
  let diffs;
  try { diffs = JSON.parse(it.qbo_drift || '[]'); } catch (e) { return ''; }
  if (!diffs || !diffs.length) return '';
  const tip = diffs.map(d =>
    `${d.field}: this says ${d.engine}, QuickBooks says ${d.quickbooks}`)
    .join('\n');
  return `<span class="vtag" title="${esc(tip)}"
    style="background:#fef3c7;color:#92400e;border-color:#fcd34d;margin-left:5px"
    >CHANGED IN QBO</span>`;
}

const PENCIL_ICON = `<svg viewBox="0 0 24 24" width="15" height="15" fill="none"
  stroke="currentColor" stroke-width="1.8" stroke-linecap="round"
  stroke-linejoin="round" aria-hidden="true"><path d="M12 20h9"/>
  <path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z"/></svg>`;

const linkBadge = (status, size, extra = '') => {
  const look = LINK_LOOK[status] || LINK_LOOK.ok;
  return `<span title="${esc(look.t)}${extra ? ' — ' + esc(extra) : ''}"
    style="margin-left:5px;cursor:help">${BANK_ICON(size, look.c)}</span>`;
};

const XLSX_ICON = `<svg viewBox="0 0 24 24" width="17" height="17" aria-hidden="true">
  <path fill="#15803d" d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6z"/>
  <path fill="#bbf7d0" d="M14 2v6h6z"/>
  <path fill="#fff" d="M8.4 11h1.7l1.1 2 1.1-2h1.7l-1.9 3.2 2 3.3h-1.7l-1.2-2.1-1.2 2.1H8.3l2-3.3z"/>
</svg>`;

// The sticky offsets depend on how tall the bands actually are, which changes
// when the header wraps or the filter row runs to two lines.
// Collapsing the frozen bands buys back roughly 90px of grid on a laptop.
// Which tab you're on stays visible either way -- it moves into the button, so
// hiding the tabs never means losing track of where you are.
let FILTERS_WERE_OPEN = [];

function setBandsHidden(hidden) {
  // An open filter panel goes with them. Leaving it on screen while the tabs
  // and filter bar disappear stranded a panel with nothing above it.
  if (hidden) {
    // Remembered, so expanding again restores what was on screen rather than
    // making you re-open it.
    FILTERS_WERE_OPEN = ['#advfilters', '#billfilters'].filter(sel => {
      const el = document.querySelector(sel);
      return el && el.style.display === 'block';
    });
    FILTERS_WERE_OPEN.forEach(sel => {
      document.querySelector(sel).style.display = 'none';
    });
  } else {
    (FILTERS_WERE_OPEN || []).forEach(sel => {
      const el = document.querySelector(sel);
      if (el) el.style.display = 'block';
    });
    FILTERS_WERE_OPEN = [];
  }
  BANDS_HIDDEN = !!hidden;
  document.body.classList.toggle('bands-hidden', BANDS_HIDDEN);
  const b = $('#hideBands');
  if (b) {
    // Rotated rather than swapped for a second glyph, so it turns in place.
    b.style.transform = BANDS_HIDDEN ? 'rotate(180deg)' : '';
    b.title = BANDS_HIDDEN ? 'Show the tabs and filters' : 'Hide the tabs and filters';
    b.classList.toggle('on', BANDS_HIDDEN);
  }
  try { localStorage.setItem(BANDS_KEY, BANDS_HIDDEN ? '1' : ''); } catch (e) {}
  measureBands();
}

// KEEP EVERYTHING ABOVE A GRID IN VIEW. In a screen that scrolls inside its
// own box -- QBO Sync's sub-tabs, sync line and toolbar, then the grid -- only
// the column headers were pinned, so the sub-tabs and toolbar scrolled away.
// Each element on the way down to the grid that comes BEFORE it is pinned, in
// order, each below the last, and the column headers are placed beneath them.
function pinAboveGrid(box) {
  if (!box) return;
  const table = box.querySelector('table.gridtable, table.rulegrid');
  let cover = box.querySelector(':scope > .pinCover');
  if (!table) { if (cover) cover.remove(); return; }
  // Start from the natural layout: undo the last pass before measuring.
  box.querySelectorAll('[data-pinned]').forEach(el => {
    el.style.position = el.style.top = el.style.zIndex = ''; delete el.dataset.pinned;
  });
  const path = [];
  for (let el = table; el && el !== box; el = el.parentElement) path.unshift(el);
  const bt = box.getBoundingClientRect().top - box.scrollTop + (box.clientTop || 0);
  const at = el => el.getBoundingClientRect().top - bt;   // offset from the box's content top
  let parent = box;
  const pins = [];
  for (const branch of path) {
    for (const sib of parent.children) {
      if (sib === branch) break;
      if (sib.classList.contains('pinCover') || getComputedStyle(sib).display === 'none') continue;
      pins.push([sib, at(sib)]);
    }
    parent = branch;
    if (branch.tagName === 'TABLE') break;
  }
  const headTop = at(table);
  // Each piece stays exactly where it sits: its sticky offset is its own place.
  pins.forEach(([el, y]) => {
    el.dataset.pinned = '1';
    el.style.position = 'sticky';
    el.style.top = `${Math.max(0, Math.round(y))}px`;
    el.style.zIndex = '9';
    if (!el.style.background) el.style.background = 'var(--bg)';
  });
  // A SOLID BACKDROP over everything above the header: the gaps between the
  // pinned pieces were see-through, so rows showed through them on the way up.
  if (!cover) {
    cover = document.createElement('div');
    cover.className = 'pinCover';
    cover.setAttribute('aria-hidden', 'true');
    box.prepend(cover);
  }
  const h = Math.max(0, Math.round(headTop));
  cover.style.cssText = `position:sticky;top:0;height:${h}px;margin-bottom:-${h}px;`
    + 'background:var(--bg);z-index:8;pointer-events:none';
  box.style.setProperty('--pin-top', `${h}px`);
}

// Re-pinned whenever QBO Sync or the Rules grid redraws -- each sub-tab draws
// itself, so watching the box covers them all -- and when the window resizes.
(function watchPinnedBoxes() {
  if (typeof MutationObserver === 'undefined') return;
  const boxes = ['cardsGrid', 'tablesGrid'];
  const pending = new Set();
  const run = () => { pending.forEach(id => pinAboveGrid(document.getElementById(id))); pending.clear(); };
  let t = null;
  const queue = id => { pending.add(id); clearTimeout(t); t = setTimeout(run, 60); };
  const start = () => boxes.forEach(id => {
    const el = document.getElementById(id);
    if (el && !el.__pinWatch) {
      el.__pinWatch = true;
      new MutationObserver(muts => {
        // Our own pinning changes style attributes only; content changes are
        // what call for a fresh measurement.
        if (muts.some(m => m.type === 'childList')) queue(id);
      }).observe(el, {childList: true, subtree: true});
    }
  });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
  window.addEventListener('resize', () => boxes.forEach(queue));
})();

// GRID HEADERS ON PAGE-SCROLLED SCREENS. A grid that scrolls with the page
// (Algorithms, Tags, Configuration...) pinned its header at the very top of the
// window -- behind the engine's own header bar and the screen's tab row, so
// rows seemed to scroll above it. Its header now pins just BELOW them, measured
// as they are. A grid that scrolls inside its own box keeps pinning to that box.
function pinPageHeaders() {
  const header = document.querySelector('header');
  const top0 = header ? Math.round(header.getBoundingClientRect().height) : 0;
  // The screens' tab rows pin below the header by this value: kept to the
  // header's REAL height, which grows when a narrow window wraps it.
  if (top0) document.documentElement.style.setProperty('--h-header', `${top0}px`);
  document.querySelectorAll('.screen').forEach(scr => {
    if (scr.offsetParent === null && getComputedStyle(scr).display === 'none') return;
    const sh = scr.querySelector(':scope > .screenhead');
    const off = top0 + (sh ? Math.round(sh.getBoundingClientRect().height) : 0);
    scr.querySelectorAll('table.gridtable, table.rulegrid').forEach(t => {
      let el = t.parentElement, boxed = false;
      while (el && el !== scr) {
        const cs = getComputedStyle(el);
        if (/(auto|scroll|hidden|clip)/.test(cs.overflowY)) { boxed = true; break; }
        el = el.parentElement;
      }
      t.querySelectorAll('tr:first-child th').forEach(th => {
        if (boxed) { if (th.dataset.pagepin) { th.style.top = ''; delete th.dataset.pagepin; } return; }
        th.style.top = `${off}px`; th.dataset.pagepin = '1';
      });
    });
  });
}
(function watchPageHeaders() {
  if (typeof MutationObserver === 'undefined') return;
  let t = null;
  const run = () => { clearTimeout(t); t = setTimeout(pinPageHeaders, 80); };
  const start = () => {
    new MutationObserver(muts => { if (muts.some(m => m.type === 'childList')) run(); })
      .observe(document.body, {childList: true, subtree: true});
    window.addEventListener('resize', run);
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();
})();

function measureBands() {
  const h = document.querySelector('header');
  const nav = document.querySelector('nav');
  if (!h || !nav) return;
  const hh = h.offsetHeight;
  document.documentElement.style.setProperty('--h-header', hh + 'px');
  document.documentElement.style.setProperty('--h-nav', (hh + nav.offsetHeight) + 'px');
  // How much room is left for the grid, measured from where it actually
  // starts. Everything above it -- header, tabs, filters, chips, icon bar --
  // can change height, so this is read rather than assumed.
  const g = document.getElementById('gridscroll');
  if (g) {
    // VIEWPORT-relative, with no scrollY added. The height below is
    // calc(100vh - this), and 100vh is measured from the top of the viewport --
    // so adding the page's scroll offset made the figure grow as you scrolled
    // and the grid stop further and further short of the bottom.
    const top = g.getBoundingClientRect().top;
    document.documentElement.style.setProperty(
      '--grid-top', Math.max(0, Math.round(top)) + 'px');
  }
}
window.addEventListener('resize', () => { try { centerPagerBar(); } catch (e) {} });
window.addEventListener('resize', () => {
  // A resize can rewrap the filter row, moving where the toggle belongs.
  BANDS_LEFT = 0;
  setBandsHidden(BANDS_HIDDEN);
  measureBands();
});

document.addEventListener('click', e => {
  if (e.target.closest('#hideBands')) setBandsHidden(!BANDS_HIDDEN);
});
try { BANDS_HIDDEN = !!localStorage.getItem(BANDS_KEY); } catch (e) {}

// Reloads the grid, the tab counts and the bill count without a page reload.
// It confirms with a flash: a refresh that finds nothing new looks identical to
// one that never ran, and the difference matters when you're waiting on a sync.
// The button names what it will reverse -- "Undo" alone gives no way to tell
// whether the next press takes back one charge or forty.
async function refreshUndo() {
  const b = $('#undoBtn');
  if (!b || !CAN.write) return;
  try {
    const j = await api(`/actions/undoable/${encodeURIComponent(company())}`);
    if (!j.next) {
      b.style.display = 'none';
      const g = $('#gridUndo');
      if (g) g.style.display = 'none';
      return;
    }
    b.style.display = 'none';        // the grid-bar icon is the visible control
    b.textContent = 'Undo Last Action';
    const g = $('#gridUndo');
    if (g) {
      g.style.display = '';
      g.title = `Undo: ${j.next.summary}`;
    }
    // What it will reverse lives in the tooltip and, more importantly, in the
    // confirmation -- the button itself stays a fixed width so it doesn't
    // reshuffle the toolbar after every click.
    b.title = `Reverses: ${j.next.summary}`;
    b.dataset.summary = j.next.summary;
  } catch (e) { b.style.display = 'none'; }
}

$('#undoBtn').onclick = async () => {
  const b = $('#undoBtn');
  const label = b.dataset.summary || 'your last action';
  const go = await askConfirm('Undo',
    `Reverse <b>${esc(label)}</b>?<br><br>Anything posted to QuickBooks by that `
    + `action is removed from QuickBooks too.`, 'Undo it', 'Cancel');
  if (!go) return;
  b.disabled = true;
  try {
    const fd = new FormData();
    fd.append('company', company());
    const r = await api('/actions/undo', {method: 'POST', body: fd});
    await load();
    const trouble = [...(r.failed || []), ...(r.skipped || [])];
    if (trouble.length) {
      notify(`${r.restored} put back. ${trouble.length} left alone:<br><br>`
             + trouble.slice(0, 6).map(esc).join('<br>'), 'Partly undone', {html: true});
    } else {
      // Say what came back, not just that something did.
      flash(r.summary ? `Undone: ${r.summary}` : 'Undone');
    }
  } catch (e) {
    notify(e.message, 'Could not undo');
  } finally { b.disabled = false; }
};


// Which top-level controls are currently narrowing the grid.
function markActiveFilters() {
  // Bills keep their own filter object, and this function used to run only for
  // the charge tabs -- so the button never lit up there.
  if (isBills()) {
    // NOT the Filters button: renderActiveFilters owns it. See below.
    ['fcardBtn', 'ftypeBtn', 'fkindBtn', 'ftierBtn', 'fmatchBtn',
     'fingestBtn', 'fuserBtn'].forEach(id => {
      const el = $('#' + id);
      if (el) el.classList.remove('on');
    });
    return;
  }
  const allCards = (COUNTS.sources || []).length;
  const on = {
    // Nothing selected is a filter too -- the strongest one there is, since it
    // hides every charge. Only "all selected" is the unfiltered state.
    // Lit only when some cards are ticked: nothing ticked is every card.
    fcardBtn: CARD_SEL.size > 0 && CARD_SEL.size < allCards,
    // NO moreFilters HERE. This excluded Strengths, matchable and search, so
    // with a Strengths filter on it switched the button back OFF -- after
    // renderActiveFilters had just switched it on from the chips. Two
    // functions deciding one button is how it stayed white with a chip
    // showing. The chip bar is what the user can see, so renderActiveFilters
    // alone decides; the button can then never disagree with the chips.
  };
  Object.entries(on).forEach(([id, active]) => {
    const el = $('#' + id);
    if (el) el.classList.toggle('on', !!active);
  });
}

// Excel first, then the column adjuster. Painted into their own bar rather
// than either grid header, so neither header's column alignment depends on
// them.
// Clickable page numbers: first, last, and a window around where you are, with
// gaps elided. Jumping to the end of 3,000 rows should not mean pressing Next
// fifteen times.
function renderPageNums(total) {
  const bar = $('#pagerbar');
  if (!bar) return;
  // REBUILT ONLY IF IT IS NOT THERE.
  //
  // This replaced the bar's contents on every render, so whatever the
  // selection count had just written into #bulkn was destroyed a moment later
  // -- on both grids, whichever element the count was moved to. Two writers,
  // and this one always ran last.
  if (!$('#bulkn')) {
    bar.innerHTML = '<b id="bulkn" style="font-size:13px"></b>';
  }
  const box = $('#pagenums');
  if (!box) return;
  const size = parseInt($('#fpage').value, 10) || 200;
  const pages = Math.ceil((total || 0) / size);
  const showBar = () => {
    // Only take a line when there is something on it.
    const _bn = $('#bulkn');
    // The bar now carries only the selection count; the numbers live in the
    // pager row itself.
    const any = _bn ? (_bn.textContent || '').trim() : '';
    bar.style.display = any ? 'flex' : 'none';
  };
  if (!total || pages < 2) {
    box.innerHTML = '';
    box.style.display = 'none';
    showBar();
    return;
  }
  const here = Math.floor(PAGE_OFFSET / size) + 1;
  // First, last, and two either side of the current page. A window rather than
  // every page, or 3,000 rows at 25 a page prints 120 links.
  const want = new Set([1, pages, here, here - 1, here + 1, here - 2, here + 2]);
  const list = [...want].filter(n => n >= 1 && n <= pages).sort((a, b) => a - b);
  let html = '';
  let prev = 0;
  for (const n of list) {
    if (prev && n - prev > 1) {
      html += `<span style="padding:0 4px;color:var(--tx2)">…</span>`;
    }
    const on = n === here;
    html += `<button class="ghost pagenum" data-p="${n}"
      style="padding:3px 9px;font-size:12px;min-width:30px;
             ${on ? 'background:var(--accent);color:#fff;border-color:var(--accent);'
                  : ''}">${n}</button>`;
    prev = n;
  }
  box.innerHTML = html;
  box.style.display = 'flex';
  showBar();
  box.querySelectorAll('.pagenum').forEach(b => b.onclick = () => {
    const n = parseInt(b.dataset.p, 10);
    if (!n || n === here) return;
    PAGE_OFFSET = (n - 1) * size;
    load({keepScroll: false});
  });
}

// Line the page numbers up under the pager controls -- the page-size box
// through to "Results". Measured rather than assumed: the grid is wider than
// the window, so centering on the page or the viewport both land somewhere else.
function centerPagerBar() {
  const bar = $('#pagerbar');
  const nums = $('#pagenums');
  if (!bar || !nums) return;
  const a = $('#fpage'), b = $('#nextPage');
  if (!a || !b) return;
  requestAnimationFrame(() => {
    const l = a.getBoundingClientRect().left;
    const r = b.getBoundingClientRect().right;
    if (!r || r <= l) return;
    const mid = (l + r) / 2;
    const w = nums.getBoundingClientRect().width || 0;
    // padding-left rather than a margin, so the bar itself still spans the
    // window and the sticky positioning keeps working when scrolled sideways.
    bar.style.justifyContent = 'flex-start';
    bar.style.paddingLeft = Math.max(0, Math.round(mid - w / 2)) + 'px';
  });
}

// Shift-click a range, on any grid that has tickboxes. The charge grid had
// this and the others did not, which meant the same gesture worked or did
// nothing depending on which tab you were looking at.
//
// `sel` is the Set being maintained; `key` reads the row's identity off the
// checkbox. Returns a click handler to attach to every box.
// A ROW THE QUICK SEARCH HID IS NOT SELECTABLE: select-all, shift-click
// ranges and batches take only the rows on screen.
const rowShown = el => { const tr = el && el.closest && el.closest('tr, .row');
  return !tr || (tr.style.display !== 'none' && tr.offsetParent !== null); };

function rangeSelect(boxes, sel, key, after) {
  let last = null;
  boxes.forEach((cb, i) => {
    cb.addEventListener('click', ev => {
      if (ev.shiftKey && last !== null && last !== i) {
        const [a, b] = last < i ? [last, i] : [i, last];
        for (let n = a; n <= b; n++) {
          if (!rowShown(boxes[n])) continue;
          boxes[n].checked = cb.checked;
          cb.checked ? sel.add(key(boxes[n])) : sel.delete(key(boxes[n]));
        }
      }
      last = i;
      if (after) after();
    });
  });
}

function renderGridIcons(show) {
  const bar = $('#gridicons');
  if (!bar) return;
  const bst = $('#billsStatus');
  if (bst && (!show || !isBills())) bst.style.display = 'none';
  if (!show) { bar.style.display = 'none'; return; }
  // Already built for this tab: just make sure it is visible. BUILT means it
  // still has its contents -- signing out empties the row but used to leave
  // this marker, so after signing back in (a timed-out session included) the
  // row was "shown" empty and only came back on a different tab or screen.
  if (bar.dataset.tab === status_ && bar.childElementCount) {
    bar.style.display = 'flex'; return;
  }
  {
    // Not built for this tab, or emptied since: filled first, shown second.
    bar.innerHTML = GRID_ICONS();
    bar.dataset.tab = status_;
    bar.style.display = 'flex';
    // Populated once, from the users who exist plus the engine's own system
  // identities. Filled here rather than at render so switching tabs does not
  // refetch a list that never changes within a session.
  if (!USER_OPTS_LOADED) {
    USER_OPTS_LOADED = true;
    api('/users/list').then(j => {
      MULTI.fuser.options = [...(j.users || []).map(u => [u, u]),
                             ...(j.system || []).map(u => [u, u])];
      renderMulti('fuser');
    }).catch(() => {});
  }
  const pe = $('#purgeExcluded');
    if (pe) pe.onclick = async () => {
      let n = 0;
      try {
        // Counted first, so the number is known before the decision rather
        // than reported after it.
        const pv = await api(`/queue/${encodeURIComponent(company())}/purge-excluded`,
                             {method: 'POST', body: new FormData()});
        n = pv.would_delete || 0;
      } catch (e) { return notify(e.message, 'Could not count them'); }
      if (!n) return flash('Nothing excluded to delete');
      const yes = await askConfirm(`Delete all ${n} excluded charges?`, '',
                                   'Delete all', 'Cancel');
      if (!yes) return;
      // Twenty thousand rows takes a minute or two and the request holds open
      // the whole time. Without this the button sat unchanged and the screen
      // looked asleep -- the single most common reason somebody clicks again.
      const _pb = $('#purgeExcluded');
      if (_pb) { _pb.disabled = true; _pb.textContent = `Deleting ${n}…`; }
      const fd = new FormData();
      fd.append('confirm', 'DELETE');
      try {
        const r = await api(`/queue/${encodeURIComponent(company())}/purge-excluded`,
                            {method: 'POST', body: fd});
        flash(`${r.deleted} excluded charges deleted`);
        await load();
      } catch (e) {
        notify(e.message, 'Could not delete them');
        if (_pb) { _pb.disabled = false; _pb.textContent = 'Delete All Excluded'; }
      }
    };
    const find = $('#gridFind');
    if (find) {
      // STILL BEING TYPED: a grid redrawn while somebody is typing keeps what
      // they have typed (and the cursor), rather than the search it last ran.
      const _typing = QS_TYPING.at && Date.now() - QS_TYPING.at < 2500;
      find.value = _typing ? QS_TYPING.value : (FILTERS.q || '');
      if (_typing && QS_TYPING.focused) { find.focus(); try { find.setSelectionRange(find.value.length, find.value.length); } catch (e) {} }
      let t;
      const run = () => {
        FILTERS.q = find.value.trim();
        PAGE_OFFSET = 0;
        QS_TYPING.at = 0;
        load({keepScroll: false});
      };
      find.oninput = () => {
        clearTimeout(t);
        QS_TYPING.value = find.value; QS_TYPING.at = Date.now(); QS_TYPING.focused = true;
        // A PAUSE, not a keystroke: the search runs once typing stops for
        // most of a second (Enter runs it at once). At 350ms a slow typist's
        // pause between words started a search mid-word.
        t = setTimeout(run, 800);
      };
      find.onkeydown = e => { if (e.key === 'Enter') { clearTimeout(t); run(); } };
      wireClearButton(find, () => { clearTimeout(t); run(); });
    }
    // Only rendered on For Review (see the template), so this just wires it.
    const ub = $('#uploadBtn');
    if (ub) ub.onclick = () => openUploadDialog();
    const ex = $('#excludeOne');
    if (ex) ex.onclick = () => { if (SEL.size === 1) act('exclude', [...SEL]); };
    const dl = $('#deleteOne');
    if (dl) dl.onclick = () => { if (SEL.size === 1) undoOrDelete([...SEL]); };

  }
}

