// FROZEN COLUMNS on the Bank Feed: the selection box, Action, Company (Multi-
// Company Mode) and Card Account stay in view while the grid scrolls right.
// A company setting; always on in Multi-Company, which has no settings.
// Each piece is measured where it sits in the header and pinned at that spot,
// in the header and in every row.
const FREEZE = {co: null, on: false};
// NO FROZEN COLUMNS, anywhere -- the setting is gone, and Multi-Company,
// where they were always on, scrolls like every other view.
async function freezeWanted() {
  return false;
  if (isAllCompanies()) return true;
  const co = company();
  if (!co) return false;
  if (FREEZE.co !== co) {
    FREEZE.co = co;
    try { FREEZE.on = !!(await api(`/setup/settings?company=${encodeURIComponent(co)}`)).freeze_cols; }
    catch (e) { FREEZE.on = false; }
  }
  return FREEZE.on;
}
async function applyFreeze() {
  const g = document.getElementById('gridscroll'), head = document.getElementById('colhead');
  if (!g || !head) return;
  g.querySelectorAll('[data-frz]').forEach(el => {
    el.style.position = el.style.left = el.style.zIndex = el.style.background = el.style.boxShadow = '';
    delete el.dataset.frz;
  });
  const on = await freezeWanted();
  document.body.classList.toggle('freeze-cols', on);
  if (!on) return;
  const parts = ['#pickAll', '.c-act', '.c-company', '.c-card'];
  const gl = g.getBoundingClientRect().left - g.scrollLeft;
  const lefts = parts.map(sel => { const el = head.querySelector(sel); return el ? el.getBoundingClientRect().left - gl : null; });
  const last = lefts.reduce((k, v, i) => (v != null ? i : k), -1);
  const pin = (el, i, bg, z) => {
    if (!el || lefts[i] == null) return;
    el.dataset.frz = '1';
    el.style.position = 'sticky';
    el.style.left = `${Math.round(lefts[i])}px`;
    el.style.zIndex = String(z);
    el.style.background = bg;
    // Covers the gap to its left, so rows don't show through between pieces;
    // the last piece has a line on its right edge.
    el.style.boxShadow = `-12px 0 0 ${bg}` + (i === last ? ', 1px 0 0 var(--line)' : '');
  };
  parts.forEach((sel, i) => pin(head.querySelector(sel), i, 'var(--bg)', 16));
  g.querySelectorAll('.row > .hd').forEach(hd => {
    pin(hd.querySelector('input.pick'), 0, 'var(--card)', 3);
    parts.slice(1).forEach((sel, k) => pin(hd.querySelector(sel), k + 1, 'var(--card)', 3));
  });
}
(function watchFreeze() {
  if (typeof MutationObserver === 'undefined') return;
  let t = null;
  const run = () => { clearTimeout(t); t = setTimeout(applyFreeze, 60); };
  const start = () => {
    const g = document.getElementById('gridscroll');
    // THE ROWS, not just the grid's own children: they are drawn into #list,
    // a level down, so watching the grid alone never fired -- and the setting
    // did nothing. The freeze only restyles cells, so it cannot re-trigger.
    if (g && !g.__frzWatch) { g.__frzWatch = true; new MutationObserver(run).observe(g, {childList: true, subtree: true}); }
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();
  window.addEventListener('resize', run);
})();

// ACCESSIBILITY, from one place: every control gets a name a screen reader
// can announce -- its own label, its tooltip, its placeholder, its column's
// header, or what it does ("Select this row") -- whenever the screen draws.
// Plus: an empty header cell says what its column is, and a scroll area can be
// reached from the keyboard.
// EVERY RED X IN A GRID, FILLED RED -- from the moment it is drawn. Run by an
// observer as soon as buttons are added (before the browser paints them), so
// an x never shows white first; and again from a11yFix as a backstop.
function markRedX(root) {
  // EVERY RED X IN A GRID IS FILLED: red with a white x, as the windows' X is
  // -- rather than an outlined one. Found here, on every draw, so every grid's
  // x gets it however it was written: a button showing just "x" in red. (Buttons
  // with words, such as Remove, keep their look.)
  (root || document).querySelectorAll('button:not(.dlgX):not(.xfill)').forEach(b => {
    if (!['\u00d7', '\u2715', '\u2716'].includes((b.textContent || '').trim()) || !b.offsetParent) return;
    const c = getComputedStyle(b).color;
    if (/^rgb\((1[5-9]\d|2\d\d), ?([0-9]|[1-7]\d), ?([0-9]|[1-7]\d)\)$/.test(c)) {
      b.classList.add('xfill');
      // On the element itself: some x's carry their own forced red, which
      // otherwise left a red x on the red fill -- and ONE SIZE for all, the
      // smallest in use (some were drawn larger than others).
      b.style.setProperty('width', '22px', 'important');
      b.style.setProperty('height', '22px', 'important');
      b.style.setProperty('padding', '0', 'important');
      b.style.setProperty('font-size', '12px', 'important');
      b.style.setProperty('line-height', '20px', 'important');
      b.style.setProperty('display', 'inline-flex', 'important');
      b.style.setProperty('align-items', 'center', 'important');
      b.style.setProperty('justify-content', 'center', 'important');
      b.style.setProperty('border-radius', '6px', 'important');
      // WHITE WITH A RED OUTLINE AND A RED X (the windows' own close X stays
      // filled red).
      b.style.setProperty('color', '#dc2626', 'important');
      b.style.setProperty('background', '#fff', 'important');
      b.style.setProperty('border-color', '#dc2626', 'important');
      // A DRAWN X, centered exactly: the "\u00d7" character sits low and to
      // one side in most fonts, so the x was never quite in the middle.
      b.innerHTML = '<svg viewBox="0 0 10 10" width="9" height="9" aria-hidden="true" style="display:block"'
        + ' fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M2 2l6 6M8 2L2 8"/></svg>';
      if (!b.getAttribute('aria-label')) b.setAttribute('aria-label', b.title || 'Remove');
    }
  });
}
// EVERY GRID'S SAVE IS ALWAYS THERE: gray while there is nothing to save,
// green once its row changes. Found on every draw, like the red x's, so no
// grid can miss it however its Save was written:
//   - a Save its grid reveals (visibility/display) is drawn gray while hidden;
//   - a Save that was simply always green now watches its row: the boxes,
//     dropdowns and pickers in it, and goes green when any of them changes
//     (gray again if they are put back). After a click it rests gray again
//     unless the row still differs.
// A Save outside a grid row opts in with class "trackSave", watching the
// nearest [data-save-scope].
function grayRowSaves(root) {
  (root || document).querySelectorAll('button').forEach(b => {
    if (b.dataset.gs) return;
    if ((b.textContent || '').trim() !== 'Save') return;
    const scope = b.classList.contains('trackSave') ? b.closest('[data-save-scope]') : b.closest('tr');
    if (!scope) return;
    b.dataset.gs = '1';
    const st = b.getAttribute('style') || '';
    if (/visibility:\s*hidden|display:\s*none/.test(st)) { b.classList.add('graySave'); return; }
    const snap = () => [...scope.querySelectorAll('input, select, textarea')]
        .map(f => (f.type === 'checkbox' || f.type === 'radio') ? (f.checked ? '1' : '0') : f.value)
        .concat([...scope.querySelectorAll('[data-value], .cs-v')]
          .filter(x => x !== b && !b.contains(x))
          .map(x => (x.dataset && x.dataset.value !== undefined) ? x.dataset.value : x.textContent))
        .join('\u0001');
    let base = snap();
    const upd = () => { if (b.isConnected) b.classList.toggle('isIdle', snap() === base); };
    scope.addEventListener('input', upd);
    scope.addEventListener('change', upd);
    try {
      new MutationObserver(ms => { if (ms.some(m => m.target !== b && !b.contains(m.target))) upd(); })
        .observe(scope, {subtree: true, childList: true, characterData: true, attributes: true,
                         attributeFilter: ['data-value', 'value']});
    } catch (e) {}
    b.addEventListener('click', () => setTimeout(() => { base = snap(); upd(); }, 1500));
    upd();
  });
}
(function watchRedX() {
  if (typeof MutationObserver === 'undefined') return;
  const go = () => new MutationObserver(muts => {
    for (const m of muts) for (const n of m.addedNodes) {
      if (n.nodeType === 1) {
        markRedX(n.tagName === 'BUTTON' ? n.parentElement || n : n);
        try { grayRowSaves(n.tagName === 'BUTTON' ? n.parentElement || n : n); } catch (e) {}
      }
    }
  }).observe(document.body, {childList: true, subtree: true});
  if (document.body) go(); else document.addEventListener('DOMContentLoaded', go);
})();

function a11yFix() {
  // ALGORITHMS: an amount reads 1.00, not 1 -- every number field there that
  // takes decimals, shown to two places. Whole-number fields (days, counts)
  // stay whole, and a field being typed in is left alone.
  document.querySelectorAll('#screen-algo input[type=number]').forEach(el => {
    const st = String(el.getAttribute('step') || '');
    if (!(st === 'any' || st.includes('.')) || document.activeElement === el || el.value === '') return;
    const n = Number(el.value);
    if (Number.isFinite(n) && el.value !== n.toFixed(2)) el.value = n.toFixed(2);
  });
  markRedX(document);
  document.querySelectorAll('input:not([type=hidden]), select, textarea').forEach(el => {
    if (el.getAttribute('aria-label') || el.getAttribute('aria-labelledby') || el.closest('label')) return;
    if (el.id && document.querySelector(`label[for="${CSS.escape(el.id)}"]`)) return;
    let name = el.getAttribute('title') || el.getAttribute('placeholder') || '';
    if (!name && el.classList.contains('pick')) name = 'Select this row';
    if (!name && el.id === 'pickAll') name = 'Select every row on this page';
    if (!name) {
      const td = el.closest('td,th');
      if (td && td.parentElement) {
        const idx = [...td.parentElement.children].indexOf(td);
        const th = td.closest('table') && td.closest('table').querySelector(`tr th:nth-child(${idx + 1})`);
        if (th) name = th.innerText.trim();
      }
    }
    if (!name) {
      // The words just before it ("Page size" beside its dropdown).
      const prev = el.previousElementSibling || (el.parentElement && el.parentElement.previousElementSibling);
      const tx = prev && (prev.innerText || '').trim();
      if (tx && tx.length <= 40) name = tx;
    }
    if (!name && el.type === 'checkbox') name = 'Select';
    if (name) el.setAttribute('aria-label', name);
  });
  document.querySelectorAll('th').forEach(th => {
    if (!th.innerText.trim() && !th.querySelector('.sr-only')) {
      const sp = document.createElement('span'); sp.className = 'sr-only'; sp.textContent = 'Actions'; th.appendChild(sp);
    }
  });
  ['auditRows', 'gridscroll'].forEach(id => {
    const el = document.getElementById(id);
    if (el && !el.hasAttribute('tabindex')) {
      el.tabIndex = 0; el.setAttribute('role', 'region');
      el.setAttribute('aria-label', id === 'auditRows' ? 'Audit Log rows' : 'Transactions');
    }
  });
}
(function watchA11y() {
  if (typeof MutationObserver === 'undefined') return;
  let t = null;
  const run = () => { clearTimeout(t); t = setTimeout(a11yFix, 120); };
  const start = () => new MutationObserver(muts => { if (muts.some(m => m.type === 'childList')) run(); })
    .observe(document.body, {childList: true, subtree: true});
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();
})();

function headerHtml() {
  const pick = `<input type="checkbox" id="pickAll" title="Select every row on this page"
                 style="width:auto;flex:none;margin:0 0 0 1px">`;
  // Leading the header rather than trailing it: on a wide grid the right edge
  // is off screen until you scroll, which put the two controls somewhere you
  // had to go looking for.
  return pick + visibleColumns().map(c => {
    const arrow = c.sort && SORT.by === c.sort ? (SORT.dir === 'asc' ? ' ▲' : ' ▼') : '';
    const cls = c.cls + (c.sort ? ' sortcol' : '');
    const attr = c.sort ? ` data-sort="${c.sort}"` : '';
    return `<span class="${cls}"${attr}>${esc(c.label)}${arrow}`
         + `<i class="rz" data-col="${c.key}"></i></span>`;
  }).join('');
}

const TAB_LABEL = {for_review: 'For Review', categorized: 'Categorized',
                   excluded: 'Excluded', bills: 'Open Bills', allbills: 'All Bills'};

// --- export -------------------------------------------------------------
//
// Asks the server for the WHOLE filtered set, not the page on screen: page size
// is a display limit, not part of the question. The visible columns go along in
// the person's own order, so the file matches what they were looking at.
function exportParams() {
  const p = new URLSearchParams();
  if (isBills()) {
    Object.entries(BILL_FILTERS).forEach(([k, v]) => { if (v) p.set(k, v); });
    if (FILTERS.q) p.set('q', FILTERS.q);
    p.set('sort', SORT.by);
    p.set('direction', SORT.dir);
    p.set('scope', billScope());
    return ['/export/bills/', p];
  }
  p.set('status', status_);
  Object.entries(activeFilters()).forEach(([k, v]) => p.set(k, v));
  const allSrcs = (COUNTS.sources || []).length;
  if (CARD_SEL.size && CARD_SEL.size < allSrcs) {
    p.set('card', [...CARD_SEL].join(','));
  }
  Object.entries(MULTI_PARAM).forEach(([key, param]) => {
    if (!MULTI[key].tabs.includes(status_)) return;
    const v = multiValue(key);
    if (v) p.set(param, v);
  });
  p.set('sort', SORT.by);
  p.set('direction', SORT.dir);
  p.set('columns', visibleColumns().map(c => c.key).join(','));
  return ['/export/queue/', p];
}

// Building a large export takes a few seconds on the server, during which
// nothing happens on screen -- so people click again, or conclude it is broken.
// The icon that was clicked says so for the duration, whichever grid it is on.
function exportBusy(on) {
  const marks = [$('#exportBtn'), ...document.querySelectorAll('.gi-x')]
    .filter(Boolean);
  marks.forEach(b => {
    b.disabled = on;
    if (on) {
      if (!b.dataset.wasHtml) b.dataset.wasHtml = b.innerHTML;
      if (!b.dataset.wasTitle) b.dataset.wasTitle = b.title || '';
      // A spinner the exact size of the icon it replaces. The word "Building…"
      // broke the button, which is sized (line-height:0) for a 17px glyph, not
      // a run of text; the title carries the message instead.
      b.innerHTML = '<span class="gi-spin" aria-label="Building export"></span>';
      b.title = 'Building your Excel export…';
      b.style.opacity = '.75';
    } else if (b.dataset.wasHtml) {
      b.innerHTML = b.dataset.wasHtml;
      b.title = b.dataset.wasTitle || '';
      delete b.dataset.wasHtml;
      delete b.dataset.wasTitle;
      b.style.opacity = '';
    }
  });
}

async function downloadExport(base, params) {
  // EVERY EXPORT DOWNLOADS THE SAME WAY: as a link opened by the click itself.
  // Fetching the file first and handing it over afterwards meant a large
  // export arrived after the browser stopped counting it as the person's own
  // download -- and it asked where to save, while a quick one saved straight
  // away. A link is the person's download however long the file takes.
  if (DL_TOKEN) {
    const _co = company() || (base === '/export/audit/' ? '*' : '');
    // THE ICON TURNS UNTIL THE FILE ARRIVES: the response sets a cookie with
    // this token, watched for here (up to three minutes).
    const dlt = Math.random().toString(36).slice(2, 12) + Date.now().toString(36);
    const extra = [params || '',
                   isAllCompanies() && compFilter() ? 'companies=' + encodeURIComponent(compFilter()) : '',
                   EXPORT_QS ? 'qs=' + encodeURIComponent(EXPORT_QS) : '',
                   'dl=' + encodeURIComponent(DL_TOKEN), 'dlt=' + dlt].filter(Boolean).join('&');
    exportBusy(true);
    const started = Date.now();
    const watch = setInterval(() => {
      const done = document.cookie.split(';').some(c => c.trim() === `engine_dl=${dlt}`);
      if (done || Date.now() - started > 180000) {
        clearInterval(watch); exportBusy(false);
        if (done) document.cookie = 'engine_dl=; Max-Age=0; Path=/';
      }
    }, 300);
    const head = base + encodeURIComponent(_co);
    const url = head + (head.includes('?') ? '&' : '?') + extra;
    const a = document.createElement('a');
    a.href = url; a.download = '';
    document.body.appendChild(a); a.click(); a.remove();
    flash('Exporting \u2014 the file downloads as soon as it is ready');
    return;
  }
  exportBusy(true);
  const btn = $('#exportBtn');
  if (btn) btn.disabled = true;
  try {
    // A base ending in '=' already carries its query key, so don't add another.
    const sep = base.endsWith('=') ? '' : '?';
    // The audit export from the dashboard asks for every company as "*". Any
    // other export with no company would build a path ending in "/", which
    // matches nothing and fails as a blocked http redirect.
    const _co = company() || (base === '/export/audit/' ? '*' : '');
    const r = await fetch(base + encodeURIComponent(_co) + sep + params,
                          {headers: {Authorization: 'Bearer ' + TOKEN}});
    if (!r.ok) throw new Error(await r.text());
    const blob = await r.blob();
    const cd = r.headers.get('Content-Disposition') || '';
    const name = (cd.match(/filename="([^"]+)"/) || [])[1] || 'export.xlsx';
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = name;
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
  } catch (e) {
    notify(e.message, 'Export failed');
  } finally {
    exportBusy(false);
    if (btn) btn.disabled = false;
  }
}

// Both live in the grid header, which is rebuilt on every render, so these are
// delegated rather than bound to the elements.
document.addEventListener('click', e => {
  if (e.target.closest('#exportBtn')) {
    const [base, params] = exportParams();
    downloadExport(base, params);
    return;
  }
  // Same action as the toolbar button, nearer the grid.
  if (e.target.closest('#gridUndo')) {
    const b = $('#undoBtn');
    if (b) b.click();
    return;
  }
  if (e.target.closest('#colsBtn')) {
    renderColsDialog();
    $('#cols').showModal();
    return;
  }
  const rb = e.target.closest('#gridRefresh');
  if (rb) {
    rb.disabled = true;
    load().then(() => flash('Refreshed')).finally(() => { rb.disabled = false; });
  }
});

// The audit screen exports through the shared grid toolbar (wireGridIcons in
// renderAuditScreen), not a handler of its own -- the dialog that owned this
// one is gone, and a second export path would honor a different set of
// filters from the grid it sits above.

function renderColsDialog() {
  const tab = gridKey();
  $('#colsTitle').textContent = `Column Settings — ${TAB_LABEL[tab] || tab}`;
  const cols = availableColumns();
  const hidden = new Set(PREFS.hidden[tab] || []);
  // The checkbox sits OUTSIDE the draggable part: a row that's draggable
  // everywhere makes ticking it feel like the start of a drag, and the browser
  // suppresses the cursor over a drag source in places.
  // A pinned column cannot be hidden or moved, so it is shown as settled
  // rather than as a control that quietly does nothing.
  $('#colsBody').innerHTML = cols.map(c => `
    <div class="colrow${c.fixed ? ' colfixed' : ''}"
         draggable="${c.fixed ? 'false' : 'true'}" data-key="${c.key}"
         title="${c.fixed ? 'Pinned — always shown first' : 'Drag to reorder'}">
      <input type="checkbox" class="colvis" data-key="${c.key}" draggable="false"
             ${hidden.has(c.key) ? '' : 'checked'} ${c.fixed ? 'disabled' : ''}>
      <span class="colhandle">
        <span class="colgrip">${c.fixed ? '' : '⠿'}</span>
        <span class="collabel">${esc(c.label)}</span>
        ${c.fixed ? '<span style="font-size:10px;color:var(--tx2);'
                    + 'margin-left:6px">pinned</span>' : ''}
      </span>
    </div>`).join('');

  const commit = () => { renderColsDialog(); savePrefs(); render(); };

  $('#colsBody').querySelectorAll('.colvis').forEach(cb => cb.onchange = () => {
    const h = new Set(PREFS.hidden[tab] || []);
    cb.checked ? h.delete(cb.dataset.key) : h.add(cb.dataset.key);
    PREFS.hidden[tab] = [...h];
    commit();
  });

  // Drag to reorder. The row being dragged is moved before or after whichever
  // row the pointer is over, which is the behavior anyone expects from a list
  // like this -- arrows meant one click per position moved.
  let dragKey = null;

  // The CONTAINER accepts the drag, not just the rows.
  //
  // During an HTML5 drag the cursor is chosen by the browser from the drop
  // effect, not by CSS -- and anywhere without a dragover handler that calls
  // preventDefault counts as "can't drop here", which shows the no-entry
  // cursor. The row gaps, the padding and the scroll area were all such
  // places, so the pointer flipped between move and no-entry as it traveled
  // down the list. That is the flicker.
  // While a column is being dragged the WHOLE document accepts it.
  //
  // The browser -- not CSS -- picks the cursor during a drag, and anywhere
  // without a dragover handler that calls preventDefault counts as "can't drop
  // here", which shows the no-entry cursor. Covering just the list left the
  // dialog's padding, its heading and its buttons uncovered, so the pointer
  // still flipped as it crossed them. Nothing outside the list is a real drop
  // target -- releasing there simply cancels -- but every pixel now says
  // "move", so the cursor never blinks out.
  const allowAnywhere = e => {
    e.preventDefault();
    if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
  };
  const beginDrag = () => {
    document.body.classList.add('col-dragging');
    document.addEventListener('dragover', allowAnywhere);
    document.addEventListener('drop', allowAnywhere);
  };
  const endDrag = () => {
    document.body.classList.remove('col-dragging');
    document.removeEventListener('dragover', allowAnywhere);
    document.removeEventListener('drop', allowAnywhere);
  };

  $('#colsBody').querySelectorAll('.colrow').forEach(row => {
    row.addEventListener('dragstart', e => {
      dragKey = row.dataset.key;
      row.classList.add('dragging');
      beginDrag();
      e.dataTransfer.effectAllowed = 'move';
      // Firefox won't start a drag without payload.
      e.dataTransfer.setData('text/plain', dragKey);
    });
    row.addEventListener('dragend', () => {
      endDrag();
      row.classList.remove('dragging');
      document.querySelectorAll('.colrow').forEach(r => r.classList.remove('over'));
    });
    row.addEventListener('dragover', e => {
      // A pinned column is not a drop target. Marking draggable=false stops it
      // being PICKED UP, but nothing stopped another column being dropped in
      // front of it -- which quietly unpinned it until the next render put it
      // back, so the list and the grid disagreed.
      if (row.classList.contains('colfixed')) {
        e.dataTransfer.dropEffect = 'none';
        return;                    // no preventDefault: refuses the drop
      }
      e.preventDefault();
      // Stated explicitly so the cursor is a move, not the browser's guess.
      e.dataTransfer.dropEffect = 'move';
      if (row.dataset.key !== dragKey) row.classList.add('over');
    });
    row.addEventListener('dragleave', () => row.classList.remove('over'));
    row.addEventListener('drop', e => {
      e.preventDefault();
      row.classList.remove('over');
      endDrag();
      const target = row.dataset.key;
      if (!dragKey || dragKey === target) return;
      // Belt and braces: refuse a drop onto or from a pinned column even if the
      // browser lets one through.
      const pinned = new Set(cols.filter(c => c.fixed).map(c => c.key));
      if (pinned.has(target) || pinned.has(dragKey)) return;
      const order = cols.map(c => c.key);
      const from = order.indexOf(dragKey);
      order.splice(from, 1);
      order.splice(order.indexOf(target), 0, dragKey);
      PREFS.order[tab] = order;
      commit();
    });
  });
}

$('#colsClose').onclick = () => $('#cols').close();
$('#colsReset').onclick = () => {
  const tab = gridKey();
  delete PREFS.order[tab];
  delete PREFS.hidden[tab];
  // Widths are shared across tabs, so only clear the ones this grid owns.
  availableColumns().forEach(c => { delete PREFS.widths[c.key]; });
  document.documentElement.removeAttribute('style');
  applyWidths();
  savePrefs();
  renderColsDialog();
  render();
};

// A band's name as shown: "very_strong" -> "Very Strong".
function tierName(t) {
  const b = BANDS.find(x => x.key === t);
  if (b) return b.name;
  return String(t || '').split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
}

function statusCell(it) {
  // The column is called Strength, so it shows strength -- on Categorized too,
  // where it answers "was this coded even though a bill matched well?".
  // What it was resolved to lives in Transaction Type and Categorization
  // Details; whether it reached QuickBooks is in the tooltip.
  const posted = it.qbo_txn_id
    ? 'in QuickBooks as ' + it.qbo_txn_type + ' ' + it.qbo_txn_id
    : (it.status === 'for_review' ? '' : 'not posted');
  // The word and the number said the same thing twice, and the color already
  // says which band it is -- so the pill is the number, with the word kept in
  // the tooltip for anyone who wants it spelled out.
  // The WORD, with the percentage in the tooltip. A band is what the number is
  // for -- nobody acts differently on 63% than on 61%, they act on "moderate".
  const band = it.tier ? tierName(it.tier) : '';
  const tip = [it.score ? it.score + '%' : '', posted].filter(Boolean).join(' — ');
  // The contested hand used to sit here, in the Match Strength column. It
  // belongs with the bill it is contesting -- the percentage pill on the
  // sub-row below the action icons -- because the thing being contested is the
  // MATCH, not the charge's own strength band. Moved to the tm-bill row.
  return `<span class="c-status">`
    + `<span class="tier t-${it.tier}" title="${esc(tip)}">${esc(band || '—')}</span>`
    + `</span>`;
}

// What the Vendor and Category columns show, whatever state the charge is in.
// On For Review these are the pending choice -- the engine's suggestion until
// someone overrides it -- and they're what "Code this" commits.
// Rendered in the viewer's own zone, whatever their machine says.
// EVERY timestamp reads m/d/yyyy, here and in the exports.
//
// 'en-US' rather than the browser's locale: the locale default put a reader on
// a machine set to en-GB on d/m/yyyy while the spreadsheet beside them said
// m/d/yyyy, and 3/4/2026 is a different day in each. One format everywhere is
// worth more than matching each reader's machine.
function localStamp(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d)) return '';
  return d.toLocaleString('en-US', {year: 'numeric', month: 'numeric',
    day: 'numeric', hour: 'numeric', minute: '2-digit'});
}

function vendorCell(it) {
  if (it.resolution === 'matched') return it.matched_bill_vendor || '';
  return it.coded_vendor || it.suggested_vendor || '';
}
// Airtable shows Full/Partial and each season status as a colored pill, so the
// same values read the same way here. The color is derived from the text, not
// from a fixed list, so a plan type or status nobody has seen before still gets
// a stable color rather than falling through to gray.
// Green when the account is live, red when it is anything else, gray for a
// blank. Deliberately binary: for reading a queue the only question is whether
// this account is good for the season, and shades between invited the reader to
// work out which amber meant what.
// THIS COMPANY'S "ACTIVE" WORDS (Broker Data > Status Words), beside the
// built-in "Active": Ticket Guy's "Yes" is green in Ticket Guy.
let STH_ACTIVE = new Set(['active']);
let STH_WORDS_FOR = null;
async function loadStatusWords() {
  const co = company();
  if (!co || isAllCompanies() || STH_WORDS_FOR === co) return;
  STH_WORDS_FOR = co;
  try {
    const j = await api(`/setup/sth-status-words?company=${encodeURIComponent(co)}`);
    STH_ACTIVE = new Set([...(((j.engine_words || {}).active) || ['active']), ...((j.words || {}).active || [])]
      .map(w => String(w).trim().toLowerCase()));
    STH_COLORS = j.colors || {};
  } catch (e) { STH_ACTIVE = new Set(['active']); STH_COLORS = {}; }
}
// EACH STATUS IN ITS OWN COLOR (Renewal Status Words), by word.
let STH_COLORS = {};
function pillColor(text) {
  const t = String(text || '').trim().toLowerCase();
  // A blank status is not "nothing to report" -- it is a season nobody has
  // recorded an answer for, which needs looking at as much as a bad one does.
  // The neutral gray read as fine.
  if (!t || t === '—' || t === '-') return ['#fee2e2', '#991b1b'];
  if (STH_COLORS[t]) return [STH_COLORS[t], inkOn(STH_COLORS[t])];
  return STH_ACTIVE.has(t) ? ['#dcfce7', '#166534'] : ['#fee2e2', '#991b1b'];
}
function pill(text) {
  const [bg, fg] = pillColor(text);
  return `<span class="pill" style="background:${bg};color:${fg}">${esc(text)}</span>`;
}

// Should this row have had a STH record? Only worth saying "none found" where
// one was expected -- a team charge. Saying it on a restaurant bill would be
// noise on most of the queue.
function halWanted(it) {
  return !!(it.vendor_from_rule || it.category_from_rule)
      && (it.suggested_category || '').includes('(TC)');
}

// The account beside the name: its totals, then the season statuses. Totals are
// per PLAN TYPE and cover every seat row on the account -- one account commonly
// has several rows, one per seat location, and showing only the row that
// matched reported a fraction of it.
function halPills(h) {
  const plans = h.plans && h.plans.length
    ? h.plans
    : (h.plan_type || h.total ? [{plan_type: h.plan_type, total: h.total,
                                  statuses: h.statuses || []}] : []);
  // Each plan carries its OWN status. One account can hold a renewed plan and a
  // canceled one at the same time, and a single status beside a combined total
  // would be describing whichever row happened to match.
  const seasonsOff = !h.seasons_chosen;
  // Each status is labeled with ITS OWN season. Two pills in a row said
  // "Active Active" with no way to tell which year was which.
  const parts = plans.map(p => {
    const st = (!seasonsOff && (p.statuses || []).length)
      ? ' ' + p.statuses.map(x =>
          // The same colored pill as the Payment Plans grid, so 25/26 is one
          // color everywhere it appears.
          `${yearPill(x.season)} ` +
          String(x.status || '').split(',')
            .map(v => pill(v.trim())).join(' ')).join(' ')
      : '';
    return `<span class="pill-amt">${esc(p.plan_type || '—')}${p.total
        ? ` ${esc(fmtAmt(p.total))}` : ''}</span>${st}`;
  });
  if (plans.length > 1 && h.account_total) {
    parts.push(`<span class="pill-amt"
      title="every seat row on this account">total ${esc(fmtAmt(h.account_total))}</span>`);
  }
  // When the team charges, and what one installment should be -- the two
  // things you check a season charge against.
  // A tick or a cross, but only where there is something to compare against.
  // Tick, cross, or "??" when there is nothing to check against.
  //
  // A missing verdict used to render as nothing, so a plan whose billing day
  // or month count is simply unrecorded in Airtable looked exactly like a
  // charge with no plan at all. Amber "??" says the third thing: the check
  // could not be made, which is a data gap rather than a pass or a fail.
  const mark = ok => ok === true
    ? `<span class="tie-mark" title="Ties out"
         style="color:#15803d;font-weight:700;margin-right:4px">\u2713</span>`
    : ok === false
    ? `<span class="tie-mark" title="Does not tie out"
         style="color:var(--bad);font-weight:700;margin-right:4px">\u2715</span>`
    : `<span class="tie-mark" title="Nothing to check against — the plan does
         not record this" style="color:#b45309;font-weight:700;margin-right:4px"
       >??</span>`;
  const day = h.day_of_month
    ? mark(h.date_ok) + `<span class="pill-amt tie-txt"
         title="Day of the month this team charges"
         style="display:inline-flex;align-items:center;gap:3px"
       ><svg viewBox="0 0 24 24" width="13" height="13" fill="none"
          stroke="currentColor" stroke-width="2" stroke-linecap="round"
          ><rect x="3" y="5" width="18" height="16" rx="2"/>
           <path d="M3 10h18M8 3v4M16 3v4"/></svg>${
             h.day_of_month === '??'
               ? '<span style="color:#b45309;font-weight:700">??</span>'
               : esc(h.day_of_month)}</span>`
    : '';
  const exp = h.expected_amount
    ? mark(h.amount_ok) + `<span class="pill-amt tie-txt"
         title="${esc(h.expected_calc || 'Account total divided by the months in the plan')}"
       >Exp Amt ${esc(fmtAmt(h.expected_amount))}</span>`
    : (h.expected_unknown
        ? mark(null) + `<span class="pill-amt tie-txt"
             title="The plan does not record how many months it runs, so there
                    is no installment to compare against"
           >Exp Amt <span style="color:#b45309;font-weight:700">??</span></span>`
        : '');
  // How far off it actually is. Signed, and colored only when it fails the
  // tolerance -- a variance inside tolerance is information, not a problem.
  const varp = (h.variance_pct === null || h.variance_pct === undefined)
    ? ''
    : `<span class="pill-amt tie-txt" style="margin-left:8px"
         title="Actual against the expected installment"
       >Var ${h.variance_pct > 0 ? '+' : ''}${esc(h.variance_pct)}%</span>`;
  const seats = h.seat_rows > 1
    ? `<span class="pill-amt" title="seat locations on this account"
        >${h.seat_rows} rows</span>` : '';
  // The season label is stated once, since every plan is shown for the same
  // season(s); the pills after each plan are that plan's status within it.
  // NAMES THE TEAM, not the league. Renewal years are chosen per team on
  // Payment Plans now, so "no seasons chosen for NBA" pointed at a screen that
  // no longer decides it -- and at a whole league when the fix is one row.
  const label = seasonsOff
    ? `<span style="color:var(--warn)">no renewal years chosen for ${
         esc(h.team || 'this team')}</span>`
    : '';
  // SEVERAL RENEWAL YEARS: a line each, oldest to newest -- the year, each
  // plan with that year's total and status -- and the charge-day and amount
  // checks on the line of the charge's own year.
  if (!seasonsOff && (h.by_season || []).length > 1) {
    const lines = h.by_season.map(y => `<span style="display:block;white-space:nowrap">${yearPill(y.season)} ${
      y.plans.map(p => `${p.plan_type || p.total ? `<span class="pill-amt">${esc(p.plan_type || '\u2014')}${p.total
        ? ` ${esc(fmtAmt(p.total))}` : ''}</span> ` : ''}${String(p.status || '').split(',').map(v => pill(v.trim())).join(' ')}`).join(' ')}${
      // EACH YEAR'S OWN SEAT ROWS, on its own line (they were shown on the
      // newer year only).
      y.rows > 1 ? ` <span class="pill-amt" title="seat locations on this account">${y.rows} rows</span>` : ''}${
      y.season === h.charge_season ? ` ${day} ${exp}${varp}` : ''}</span>`);
    if (!h.by_season.some(y => y.season === h.charge_season)) lines.push(`<span style="display:block">${day} ${exp}${varp}</span>`);
    return ` <span class="sth-years" style="display:inline-block;vertical-align:top">${lines.join('')}</span>`;
  }
  // Row count sits with the totals it explains, before the plan dates.
  return ` ${label} ${parts.join(' ')} ${seats} ${day} ${exp}${varp}`;
}

// Row actions as icons. The words were four different widths in a column that
// repeats on every row, and Add/Match/Split/Exclude are the four things done all
// day -- a shape is quicker to hit than a word to read.
const ACT_ICONS = {
  add: `<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor"
          stroke-width="2.8" stroke-linecap="round"><path d="M12 4v16M4 12h16"/></svg>`,
  // Interlocking links: this charge and that bill are joined. A tick reads as
  // "done", which is what Add means, so the two looked too alike.
  match: `<svg viewBox="0 0 24 24" width="18" height="18" fill="none"
          stroke="currentColor" stroke-width="2.2" stroke-linecap="round"
          ><path d="M9 12h6"/>
           <path d="M9.5 8H7a4 4 0 0 0 0 8h2.5"/>
           <path d="M14.5 8H17a4 4 0 0 1 0 8h-2.5"/></svg>`,
  split: `<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor"
          stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"
          ><path d="M4 12h5l4-6h7M9 12l4 6h7M17 3l3 3-3 3M17 15l3 3-3 3"/></svg>`,
  trash: `<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor"
          stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"
          ><path d="M3 6h18M8 6V4h8v2M6 6l1 14h10l1-14M10 11v6M14 11v6"/></svg>`,
  // A hammer: this is the reviewer overriding the engine, not the engine
  // proposing something.
  force: `<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor"
          stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"
          ><path d="M14 3l7 7-3 3-7-7z"/><path d="M11.5 5.5L4 13l3 3 7.5-7.5"/>
           <path d="M6 16l-2.5 2.5a1.8 1.8 0 0 0 2.5 2.5L8.5 18.5"/></svg>`,
  back: `<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor"
          stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"
          ><path d="M10 6L4 12l6 6M4 12h11a5 5 0 0 1 0 10h-1"/></svg>`,
};
function actBtn(cls, id, icon, title, style = '') {
  return `<button class="${cls} act-ico" data-id="${esc(id)}" title="${esc(title)}"
            aria-label="${esc(title)}" style="${style}"
            onclick="event.stopPropagation()">${ACT_ICONS[icon]}</button>`;
}
// What each tab can do to ONE row. Batch Actions is untouched and still covers
// the same ground for a selection.
// Matching by hand, to a bill the engine ruled out. Deliberately separate from
// Match: that one accepts what was offered, this one overrides why it wasn't.
async function openForceMatch(chargeId) {
  // The window is reused: its button starts fresh each time it opens.
  { const go = document.getElementById('fmDo'); if (go) go.textContent = 'Force Match'; }
  // EVERY OPEN STARTS ON "leave bill as is" -- the last choice used to carry
  // over, so an adjust meant for one charge was quietly offered for the next.
  document.querySelectorAll('input[name="fmMode"]').forEach(r => {
    r.checked = r.value === 'keep';
  });
  const it = (QUEUE.items || []).find(x => x.id === chargeId);
  // `amt` is what the queue calls it; `amount` is kept as a fallback so this
  // still works if the field is ever renamed back.
  const chargeAmt = it
    ? Math.round(parseFloat(it.amt != null ? it.amt : it.amount) * 100) / 100 : 0;
  let picked = {};                 // bill_id -> amount typed against it
  let rows = [];
  $('#fmErr').textContent = '';
  $('#fmDo').disabled = true;
  $('#fmFind').value = '';
  // THE CHARGE: card account, date, bank detail, profile, amount, CC last 4.
  $('#fmWho').innerHTML = it
    ? [['Card Account', it.account || it.src], ['Date', fmtDate(it.date || '')], ['Bank Detail', it.merchant],
       ['Profile', it.holder], ['Amount', fmtAmt(it.amt != null ? it.amt : it.amount)], ['CC Last 4/5', it.card]]
        // HEADERS BOLD, VALUES PLAIN -- as the Open Bills window's details.
        .map(([k, v]) => `<span style="margin-right:16px;white-space:nowrap"><b style="color:var(--tx)">${k}</b>
           <span style="color:var(--tx)">${esc(v || '\u2014')}</span></span>`).join('') : '';

  const money = n => (Math.round(n * 100) / 100).toFixed(2);
  const sum = () => Object.values(picked)
    .reduce((a, v) => a + (parseFloat(v) || 0), 0);

  const paintTotal = () => {
    const n = Object.keys(picked).length;
    const t = Math.round(sum() * 100) / 100;
    // READY when the payment is fully used: a single bill only if it covers
    // the whole payment (the rest of that bill stays open), otherwise the
    // amounts must add up to it. One ticked bill SMALLER than the payment
    // used to count as ready and show gray, though more bills were needed.
    // In ADJUST mode a single bill is corrected to the charge, so it is ready
    // whatever the bill's amount.
    const _adjust = ['adjust', 'fees'].includes(
      (document.querySelector('input[name="fmMode"]:checked') || {}).value);
    const ok = n === 1 ? (_adjust || t >= chargeAmt - 0.011)
                       : Math.abs(t - chargeAmt) < 0.011;
    $('#fmTot').innerHTML = n
      ? `${n} bill${n > 1 ? 's' : ''} · ${fmtAmt(money(t))} of ${fmtAmt(money(chargeAmt))}`
      : 'Nothing selected';
    // Red until ready, green once Force Match can be pressed.
    $('#fmTot').style.color = !n ? 'var(--tx2)' : ok ? 'var(--ok)' : 'var(--bad)';
    $('#fmDo').disabled = !n || !ok;
    // GRAY UNTIL IT CAN BE PRESSED. Disabled, it still looked green and ready.
    const _go = $('#fmDo');
    // GREEN when it can be pressed -- set outright, since clearing the gray
    // left the button's own white style showing.
    _go.style.background = _go.disabled ? '#d1d5db' : '#15803d';
    _go.style.borderColor = _go.disabled ? '#d1d5db' : '#15803d';
    _go.style.color = _go.disabled ? '#6b7280' : '#ffffff';
    _go.style.cursor = _go.disabled ? 'not-allowed' : 'pointer';
  };

  const draw = async needle => {
    $('#fmList').innerHTML = '<div class="why">loading…</div>';
    try {
      rows = (await api(`/force-match/bills?company=`
        + encodeURIComponent(rowCompany((QUEUE.items || []).find(x => String(x.id) === String(chargeId)))) + `&q=` + encodeURIComponent(needle || '')
      )).bills || [];
    } catch (e) {
      $('#fmList').innerHTML = `<div class="why">${esc(e.message)}</div>`; return;
    }
    if (!rows.length) {
      $('#fmList').innerHTML = '<div class="why">No bills found.</div>'; return;
    }
    // The whole Open Bills list, ticked like a statement. Several bills can be
    // ticked, which is how one charge settles more than one.
    $('#fmList').innerHTML = `
      <table class="gridtable" style="width:100%">
        <tr><th style="width:34px"><input type="checkbox" id="fmAll"
              title="Select or clear every bill listed" style="width:auto"></th>
            <th style="width:140px">Bill No.</th>
            <!-- Wider, and the cell below clips rather than spills. Under
                 table-layout:fixed an over-long vendor name does not widen its
                 column, it runs straight over the next one -- which is how
                 "Live Nation Coastal Credit" ended up sitting on top of the
                 date. -->
            <th style="width:320px">Vendor</th><th style="width:116px">Date</th>
            <th style="width:136px;text-align:right">Amount</th>
            <th style="width:136px;text-align:right">Balance</th><th style="width:140px">Applying</th>
            <th style="width:300px">Memo</th></tr>
        ${rows.map(b => `<tr class="${picked[b.bill_id] !== undefined ? 'fmOn' : ''}">
          <td><input type="checkbox" class="fmPick" data-b="${esc(b.bill_id)}"
                     ${picked[b.bill_id] !== undefined ? 'checked' : ''}
                     style="width:auto"></td>
          <td><b>${esc(b.doc_number || b.bill_id)}</b></td>
          <td style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap"
              title="${esc(b.vendor)}">${esc(b.vendor)}</td>
          <td>${esc(fmtDate(b.date))}</td>
          <td style="text-align:right">${esc(fmtAmt(b.amount))}</td>
          <td style="text-align:right">${esc(fmtAmt(b.balance))}</td>
          <td style="white-space:nowrap;overflow:visible;width:120px"
              onclick="event.stopPropagation()">$<input
                     class="fmAmt" data-b="${esc(b.bill_id)}" type="number"
                     step="0.01" inputmode="decimal"
                     value="${picked[b.bill_id] !== undefined
                       ? esc(picked[b.bill_id]) : ''}"
                     onclick="event.stopPropagation();this.focus()"
                     onmousedown="event.stopPropagation()"
                     style="width:92px;text-align:right"></td>
          <td style="color:var(--tx2)">${esc(b.memo || '')}</td>
        </tr>`).join('')}
      </table>`;
    const all = $('#fmAll');
    if (all) all.onchange = () => {
      // Ticking everything only makes sense while the amounts still add up, so
      // each row takes what is left of the charge and stops at zero.
      $('#fmList').querySelectorAll('.fmPick').forEach(cb => {
        if (all.checked === cb.checked) return;
        cb.checked = all.checked;
        cb.dispatchEvent(new Event('change'));
      });
    };
    $('#fmList').querySelectorAll('.fmPick').forEach(cb => cb.onchange = () => {
      const id = cb.dataset.b;
      const row = rows.find(r => r.bill_id === id);
      const tr = cb.closest('tr');
      const amt = tr.querySelector('.fmAmt');
      if (cb.checked) {
        // Defaults to whatever is still owing, capped at what is left of the
        // charge -- the common case is "this bill, then the rest on that one".
        // Never more than the charge can cover, first pick or not -- a bill
        // larger than the charge is a PART payment, and offering its full
        // balance made the total wrong the moment it was ticked.
        const left = Math.max(0, chargeAmt - sum());
        const owing = parseFloat(row.balance) || 0;
        picked[id] = money(Math.min(owing, Object.keys(picked).length
                                    ? left : chargeAmt));
        amt.value = picked[id];
      } else {
        delete picked[id];
        amt.value = '';
      }
      // The row is restyled in place. Redrawing the whole table on every tick
      // is the flash, and it also threw away where you had scrolled to -- so a
      // bill ticked further down could not be seen afterwards.
      tr.classList.toggle('fmOn', cb.checked);
      paintTotal();
    });
    $('#fmList').querySelectorAll('.fmAmt').forEach(inp => inp.oninput = () => {
      const id = inp.dataset.b;
      const tr = inp.closest('tr');
      const cb = tr.querySelector('.fmPick');
      // Typing a figure IS selecting the bill, and clearing it deselects --
      // otherwise the box and the tick can disagree about what is included.
      if (inp.value.trim() === '') {
        delete picked[id];
        if (cb) cb.checked = false;
        tr.classList.remove('fmOn');
      } else {
        picked[id] = inp.value;
        if (cb) cb.checked = true;
        tr.classList.add('fmOn');
      }
      paintTotal();
    });
    paintTotal();
  };
  // APPLY OLDEST FIRST. One daily payment to a vendor such as GoTickets or
  // TickPick covers many of that day's bills. Filtered to the vendor, this
  // takes its open bills oldest first, each for its full balance, until the
  // payment is used up -- so the last one is usually paid in part.
  const applyOldest = () => {
    const box = $('#fmOldest');
    const vendors = new Set(rows.map(r => (r.vendor || '').trim().toLowerCase()));
    if (vendors.size > 1) {
      box.checked = false;
      $('#fmErr').textContent = 'Filter to one vendor first, then tick '
        + '"Apply oldest first" -- these bills are from '
        + vendors.size + ' vendors.';
      return;
    }
    $('#fmErr').textContent = '';
    const order = [...rows].sort((a, b) =>
      String(a.date || '').localeCompare(String(b.date || ''))
      || String(a.doc_number || '').localeCompare(String(b.doc_number || '')));
    picked = {};
    let left = chargeAmt;
    for (const r of order) {
      if (left <= 0.005) break;
      const owing = parseFloat(r.balance) || 0;
      if (owing <= 0) continue;
      const a = Math.min(owing, left);
      picked[r.bill_id] = money(a);
      left = Math.round((left - a) * 100) / 100;
    }
    $('#fmList').querySelectorAll('.fmPick').forEach(cb => {
      const on = cb.dataset.b in picked;
      cb.checked = on;
      const amt = cb.closest('tr').querySelector('.fmAmt');
      if (amt) amt.value = on ? picked[cb.dataset.b] : '';
    });
    if (left > 0.005) {
      $('#fmErr').textContent = `These open bills come to less than the payment `
        + `-- ${fmtAmt(money(left))} would be left over.`;
    }
    paintTotal();
  };
  // Switching between "leave as is" and "adjust" changes what counts as
  // ready, so the total and the button are redrawn at once.
  document.querySelectorAll('input[name="fmMode"]').forEach(r => {
    r.onchange = () => paintTotal();
  });
  $('#fmOldest').checked = false;
  $('#fmOldest').onchange = () => {
    if ($('#fmOldest').checked) return applyOldest();
    picked = {};
    $('#fmErr').textContent = '';
    $('#fmList').querySelectorAll('.fmPick').forEach(cb => {
      cb.checked = false;
      const amt = cb.closest('tr').querySelector('.fmAmt');
      if (amt) amt.value = '';
    });
    paintTotal();
  };
  await draw('');
  let t;
  $('#fmFind').oninput = () => {
    clearTimeout(t);
    // Re-applied after the list redraws, so narrowing to the vendor with the
    // box already ticked still fills the bills in.
    t = setTimeout(async () => {
      await draw($('#fmFind').value.trim());
      if ($('#fmOldest').checked) applyOldest();
    }, 300);
  };
  $('#fmCancel').onclick = () => $('#fmatch').close();
  $('#fmDo').onclick = async () => {
    const ids = Object.keys(picked);
    if (!ids.length) return;
    const fd = new FormData();
    fd.append('charge_id', chargeId);
    fd.append('mode', document.querySelector('input[name="fmMode"]:checked').value);
    if (ids.length === 1) {
      fd.append('bill_id', ids[0]);
    } else {
      fd.append('bills', JSON.stringify(
        ids.map(b => ({bill_id: b, amount: picked[b]}))));
    }
    // AT ONCE, NOT AFTER A PAUSE: the button says it is working the moment it
    // is pressed, and the window closes onto the Updating circle.
    const go = $('#fmDo');
    go.disabled = true; go.textContent = 'Matching\u2026';
    try {
      const r = await api('/queue/force-match', {method: 'POST', body: fd});
      $('#fmatch').close();
      await load();
      flash(r.reason || 'Matched');
    } catch (e) { $('#fmErr').textContent = e.message; go.disabled = false; go.textContent = 'Force Match'; }
  };
  $('#fmatch').showModal();
}

function actionCell(it) {
  const id = it.id;
  // Only the actions that mean something on this tab. A grayed icon that can
  // NEVER apply here is clutter, not consistency -- Categorized has nothing to
  // add or match, and an excluded row has nothing to match or split.
  const btn = (cls, icon, title, on) => on
    ? `<button class="${cls} act-ico" data-id="${esc(id)}" title="${esc(title)}"
         aria-label="${esc(title)}" onclick="event.stopPropagation()"
         >${ACT_ICONS[icon]}</button>`
    : `<span class="act-ico ico-off" title="${esc(title)} — not available here"
         aria-hidden="true">${ACT_ICONS[icon]}</span>`;
  let out = '';
  if (status_ === 'for_review') {
    out += btn('doCode ico-add', 'add', 'Add', true);
    out += it.candidates.length
      ? `<button class="doMatch act-ico ico-match" data-id="${esc(id)}"
           data-bill="${esc(it.candidates[0].bill_id)}" title="Match"
           aria-label="Match" onclick="event.stopPropagation()"
           >${ACT_ICONS.match}</button>`
      : btn('doMatch ico-match', 'match', 'Match', false);
    out += btn('rowForce ico-force', 'force', 'Force match to a specific bill', true);
  } else if (status_ === 'excluded') {
    out += btn('rowUndo ico-undo', 'back', 'Unexclude', true);
    out += btn('rowDelete ico-del', 'trash', 'Delete permanently', true);
  }
  return `<span class="c-act">${out}</span>`;
}

function categoryCell(it) {
  if (it.resolution === 'matched') return 'Bill Payment';
  // Blank for a split: the badge alongside says SPLIT, and the word appearing
  // twice in one cell said nothing the badge did not.
  if (it.split_lines > 1) return '';
  return it.coded_category || it.suggested_category || '';
}

// The lines behind a Split, for the cell's tooltip.
function splitTitle(it) {
  return (it.split_detail || [])
    .map(l => `${l.category} — ${fmtAmt(l.amount)}`).join('\n');
}

// The cell shows the first line; the badge says there are others, so a split
// transaction never looks like a plain one coded to a single account. Returned
// separately from the value because the value is escaped.
// Says where the value came from, and disappears the moment somebody types
// over it -- otherwise the badge would credit a rule with a person's decision.
function ruleBadge(it, field) {
  // A MATCHED charge took its vendor and category from the bill it settled, so
  // a rule badge beside them claims credit for something the rule did not do --
  // and on Categorized that is the difference between "a rule decided this" and
  // "a bill did".
  if (it.resolution === 'matched') return '';
  // SUGGESTED FROM PAST CODING: the same badge, the same blue, while the cell
  // still holds the suggestion (gone once somebody changes it).
  if (it.from_history) {
    const held = field === 'vendor'
      ? (!it.coded_vendor || it.coded_vendor === it.suggested_vendor)
      : (!it.coded_category || it.coded_category === it.suggested_category);
    if (held) return `<span class="tag tag-rule" title="${esc(ruleProvenance(it))}">SUGGESTION</span>`;
  }
  const on = field === 'vendor' ? it.vendor_from_rule : it.category_from_rule;
  if (!on) return '';
  // A DEDUCTION, NOT A STATED RULE.
  //
  // Shared billing entities -- KSE for both Denver teams, MLSE for both
  // Toronto teams, one college billing football and basketball identically --
  // name a set rather than a team. The engine narrows that set using which
  // season account the cardholder holds, which day the plan bills and what the
  // installment comes to. When one candidate survives it fills the row.
  //
  // That is worth doing and worth distinguishing. Amber rather than blue,
  // because a reviewer skimming a hundred rows should be able to see at a
  // glance which ones rest on circumstance, and the hover says what decided it.
  if (it.vendor_confidence === 'likely') {
    // Same word as the blue badge, different color. Reviewers read this
    // column as "was this filled by a rule" -- a second word made it a second
    // concept to learn. The color carries the difference and the hover says
    // what decided it.
    return `<span class="tag" title="${esc(ruleProvenance(it) || 'Filled by rule')}
        — best guess. ${esc(it.likely_reason || '')}. This bank detail is
        shared by more than one team, so which one it is was deduced rather
        than stated."
        style="background:#fef3c7;color:#92400e;border:1px solid #fcd34d"
        >RULE</span>`;
  }
  // "(DEP)" when the category is a deposit account.
  //
  // A deposit is coded by a different rule from a ticket credit -- it is the
  // charge whose amount matches a deposit record -- and the two look identical
  // on the row otherwise. Saying which fired is the difference between
  // trusting the badge and opening the charge to find out.
  // TWO badges, not one word with a suffix. "RULE (DEP)" read as a different
  // kind of rule; they are two facts -- a rule filled this, and the account it
  // chose is the deposit one -- and DEP is the one worth catching the eye.
  //
  // `forVendor` because a deposit is a property of the CATEGORY: the vendor is
  // the same either way, and marking it there said something untrue.
  return depBadge(it, field === 'vendor') + `<span class="tag tag-rule" title="${
    esc(ruleProvenance(it) || 'Filled by rule')}">RULE</span>`;
}

// A quiet marker on the row itself, so the conflict is visible without
// expanding every transaction.
// The wording, in one place, so the badge tooltip and the note in the expanded
// row cannot say different things about the same conflict.
function contestedText(it) {
  const vs = it.contested_by;
  if (!vs) return '';
  return `A stronger transaction wants this bill. Bill ${vs.bill} is also the `
    + `top match for ${vs.merchant} — ${vs.card || ''}`
    + `${vs.last4 ? ' ••' + vs.last4 : ''}, ${vs.date || ''}, `
    + `${fmtAmt(vs.amount || 0)}${vs.holder ? ', ' + vs.holder : ''} — at `
    + `${Math.round(vs.score * 100)}%, higher than this one.`
    + (vs.others > 1 ? ` ${vs.others} transactions want it in total.` : '');
}

function contestedBadge(it) {
  const vs = it.contested_by;
  // Only when the rival scores HIGHER, and only on a transaction that is not
  // itself Weak. Every weak row has a better claimant somewhere, so marking
  // those turned the badge into wallpaper.
  if (!vs || !vs.stronger || it.tier === 'weak' || !it.tier) return '';
  // A hand, not "VS". The abbreviation needed explaining every time; a stop
  // sign reads as "wait, look at this before you act", which is the whole
  // message.
  // Drawn, not an emoji. The glyph renders differently on every platform --
  // Apple's is peach, Windows' is yellow, some are outlined -- so the one thing
  // it could not be was consistent. This is the same shape everywhere.
  return `<span class="tag tag-vs beaten" title="${esc(contestedText(it))}">`
    // Four separated fingers and a thumb, drawn as strokes so the gaps read at
    // 16px. The previous solid silhouette lost its finger separation at this
    // size and looked like a mitten.
    + `<svg viewBox="0 0 32 32" width="21" height="21" aria-hidden="true"
         fill="none" stroke="#d64545" stroke-width="2.6"
         stroke-linecap="round" stroke-linejoin="round">
       <path d="M11 15V6.5a1.8 1.8 0 0 1 3.6 0V14"/>
       <path d="M14.6 14V4.8a1.8 1.8 0 0 1 3.6 0V14"/>
       <path d="M18.2 14V6a1.8 1.8 0 0 1 3.6 0v8.6"/>
       <path d="M21.8 14.6v-4a1.8 1.8 0 0 1 3.6 0v7.6c0 5-3.4 8.6-8.2 8.6
                -3 0-5.2-1.2-6.8-3.4l-4.2-6a1.9 1.9 0 0 1 .7-2.7
                c.9-.5 2-.2 2.6.6L11 16"/>
       </svg></span>`;
}

function splitBadge(it) {
  if (!(it.split_lines > 1)) return '';
  // Left of the value, not right: with the cell otherwise empty a
  // right-aligned badge floated away from everything it describes.
  return `<span class="tag tag-split" style="margin:0 6px 0 0"
    title="${esc(splitTitle(it))}">SPLIT</span>`;
}

// One column, both resolution kinds. A bill payment reads as the bill it paid;
// a coded charge reads as the vendor and account it went to.
// The STH season-ticket account as one plain line, in the same order the For
// Review row shows it: who the account belongs to, what it is worth, whether it
// is a full or partial plan, then the season statuses. Used by the More Details
// column, where a charge that was ADDED against a season account has no bill to
// describe but does have this.
function halDetailsOf(it) {
  const h = it.hal;
  if (!h) return '';
  const parts = [h.lookup_name || '',
                 h.total ? fmtAmt(h.total) : '',
                 h.plan_type || ''];
  if (h.seasons_chosen && (h.statuses || []).length) {
    h.statuses.forEach(s => parts.push(`${s.season} ${s.status}`));
  }
  // The plan comparison, carried onto Categorized. On For Review these sit in
  // their own pills; once a row is coded the question shifts from "act on
  // this" to "what was this", and that reads better as one line of text.
  //
  // Suppressed on refunds, for the same reason the pills are: a credit
  // reverses a charge, it is not an installment, so a billing day and one
  // twelfth of a season are figures it was never meant to match.
  if (!it.is_credit) {
    if (h.day_of_month) parts.push('day ' + h.day_of_month);
    if (h.expected_amount) parts.push('exp ' + fmtAmt(h.expected_amount));
    if (h.variance_pct !== null && h.variance_pct !== undefined) {
      parts.push(`var ${h.variance_pct > 0 ? '+' : ''}${h.variance_pct}%`);
    }
    if (h.fx_note) parts.push(h.fx_note);
  }
  return parts.filter(Boolean).join('  ·  ');
}

function detailsOf(it) {
  const parts = it.resolution === 'matched'
    ? [it.matched_bill_no ? 'Bill ' + it.matched_bill_no : '',
       it.matched_bill_vendor,
       it.matched_bill_date ? fmtDate(it.matched_bill_date) : '',
       it.matched_bill_memo]     // bill's own vendor stays in the bill's detail
    : [it.coded_category];   // vendor has its own column now
  return parts.filter(Boolean).join('  ·  ');
}
// Expanding a resolved row showed a single Undo button; Undo is on the bulk
// bar, so the row is just a record and there is nothing underneath it.
const expandable = () => status_ === 'for_review';

function rowHtml(it) {
  const done = it.status !== 'for_review';
  const top = it.candidates[0];
  // One line per bill: a reviewer is scanning for the right one, and three
  // lines each turns five candidates into a page of scrolling.
  // The bill's own details only. Why the engine ranked it is its business, and
  // the reasoning crowded out the part being compared.
  const candLine = c =>
    `<b>Bill ${esc(c.bill)}</b> · ${esc(fmtAmt(c.amt))} · ${fmtDate(c.date)}`
    + ` · ${esc(c.vendor)}${c.memo ? ' · ' + esc(c.memo) : ''}`;
  // The same pill the collapsed row uses, colored by that candidate's own
  // strength -- a bare blue percentage read as a different kind of number.
  const vs = it.contested_by;
  const contested = (vs && vs.stronger && it.tier && it.tier !== 'weak') ? `
    <div class="why" style="margin:0 0 8px;color:var(--bad)">
      ${esc(contestedText(it))}
    </div>` : '';
  // The season-ticket account behind this charge, used by the detail line
  // below the row.
  const h = it.hal;
  // No STH panel inside the expansion any more. The collapsed row already
  // shows the account, its plan totals and each season's status -- repeating
  // it here said the same thing twice, in a second format, and the two could
  // disagree once the row started aggregating seat rows.
  const halPanel = '';
  const splitRows = (it.split_detail || []).length
    ? `<div class="why" style="margin:0 0 8px">
         <b>Split across ${it.split_detail.length} categories:</b>
         ${it.split_detail.map(l =>
            `<div style="margin-top:3px">${esc(l.category)}
             &nbsp;·&nbsp; ${esc(fmtAmt(l.amount))}</div>`).join('')}
       </div>`
    : '';
  // The match icon leads the row, in front of the strength pill: it is the
  // action, and having it at the far right meant a long bill line pushed it
  // off to a place the eye had to travel to. With the button no longer
  // stretching the row, the containers shrink to the text they hold.
  const cands = it.candidates.map((c, i) => `
    <div class="candrow">
      <button class="doMatch act-ico ico-match" data-id="${esc(it.id)}"
              data-bill="${esc(c.bill_id)}" title="Match this bill"
              aria-label="Match this bill"
              onclick="event.stopPropagation()">${ACT_ICONS.match}</button>
      <div class="cand ${i === 0 ? 'best' : ''}">
        <div class="sc"><span class="tier t-${esc(c.tier || it.tier)}"
          >${Math.round(c.score * 100)}%</span></div>
        <div class="d">${candLine(c)}</div>
      </div>
    </div>`).join('');


  return `<div class="row" data-id="${esc(it.id)}">
    <div class="hd" style="cursor:default">
      <input type="checkbox" class="pick" data-id="${esc(it.id)}"
             ${SEL.has(it.id) ? 'checked' : ''} onclick="event.stopPropagation()">
      ${visibleColumns().map(c => c.cell(it)).join('\n      ')}

    </div>
    <!-- The detail line under the row. The bill sits on the left, where it has
         always been; the STH season-ticket account is slid over to begin at the
         Profile column, on the SAME line, so a routine payment shows its bill
         and its account side by side rather than stacked. -->
    ${(status_ === 'for_review' && (top || h || halWanted(it))) ? `
    <div class="topmatch${(h || halWanted(it)) ? ' has-hal' : ''}">
      ${h ? `
      <div class="tm-hal">
        <span class="tier" style="background:#e6eefb;color:var(--accent)">STH</span>
        <span class="tm-b">${h.team ? `<b>${esc(h.team)}</b> \u00b7 ` : ''}<b>${esc(h.holder_name || h.lookup_name || '—')}</b>${halPills(h)}</span>
      </div>`
      : halWanted(it) ? `
      <div class="tm-hal">
        <span class="tier" style="background:#e6eefb;color:var(--accent)">STH</span>
        <span class="tm-b"><span class="pill pill-none"
          title="Searched STH for &quot;${esc(it.holder || '')}&quot;${
            it.hal_emails ? ' and ' + esc(it.hal_emails) : ''}. Nothing matched \u2014 either this person has no record for the season, or the name on the card is written differently in STH."
          >No Records Found</span></span>
      </div>` : ''}
      ${top ? `
      <!-- The hand sits in the gutter, directly under the action icons, so the
           percentage pill below Card Account lines up with the pill above it.
           Inline-block with a fixed width rather than a flex gap: the pill has
           to hold its column position whether a hand is present or not. -->
      <div class="tm-bill">
        <span class="tm-flag">${contestedBadge(it)}</span><span
          class="tier t-${it.tier}">${Math.round(top.score * 100)}%</span>
        <span class="tm-b">${candLine(top)}</span>
        ${it.candidates.length > 1
          ? `<button class="tm-more" data-id="${esc(it.id)}"
                     onclick="event.stopPropagation();
                              this.closest('.row').classList.toggle('open')"
             >Click Here To See All Matching Bills</button>`
          : ''}
      </div>` : ''}
    </div>` : ''}
    ${expandable() ? `<div class="body">
      ${!CAN.write ? '<div class="why">View only — you can browse but not change anything.</div>' : ''}
      ${it.post_error ? `<div class="why" style="color:var(--bad);margin-bottom:8px">
        Last attempt was not written to QuickBooks: ${esc(it.post_error)}</div>` : ''}
      ${contested}
      ${splitRows}
      <div style="display:flex;gap:14px;align-items:flex-start">
        <div style="flex:1;min-width:0">
          ${it.candidates.length ? `
            <div style="font-size:11px;text-transform:uppercase;letter-spacing:.05em;
                        color:var(--tx2);margin-bottom:6px"
              >All bills available for matching</div>
            <div class="candlist">${cands}</div>` : ''}
        </div>
        ${halPanel}
      </div>
    </div>` : ''}</div>`;
}

function categoryOptions(suggested) {
  if (!CATEGORIES.length) {
    // QuickBooks not reachable — fall back to the engine's own labels so the
    // reviewer isn't blocked, but make it obvious they're not QBO accounts.
    return ['TC', 'DEP'].map(v =>
      `<option value="${v}" ${v === suggested ? 'selected' : ''}>${v} (not from QuickBooks)</option>`).join('');
  }
  const want = (suggested || '').toLowerCase();
  return ['<option value="">— choose category —</option>'].concat(
    CATEGORIES.map(c => {
      const label = c.fully_qualified || c.name;
      const sel = want && label.toLowerCase().includes(want) ? 'selected' : '';
      return `<option value="${esc(label)}" ${sel}>${esc(label)}</option>`;
    })).join('');
}

function matchCategory(suggested) {
  if (!suggested || !CATEGORIES.length) return suggested || '';
  const s = suggested.toLowerCase();
  const hit = CATEGORIES.find(c => (c.fully_qualified || c.name).toLowerCase() === s)
           || CATEGORIES.find(c => (c.fully_qualified || c.name).toLowerCase().includes(s));
  return hit ? (hit.fully_qualified || hit.name) : suggested;
}

function matchVendor(suggested) {
  if (!suggested || !VENDORS.length) return suggested || '';
  const s = suggested.toLowerCase();
  const hit = VENDORS.find(v => (v.name || '').toLowerCase() === s)
           || VENDORS.find(v => (v.name || '').toLowerCase().includes(s));
  return hit ? hit.name : suggested;
}

function render() {
  if (isBills()) return renderBills();
  // Every path into the charge grid comes through here, so this is the one
  // place that can be sure the bills bar has no business being on screen.
  hideBillBulk();
  // Strength is a stored column now, so the server filters and sorts it like
  // any other -- the page arrives already narrowed and the totals are real.
  let rows = (QUEUE.items || []);
  // Anything filtered out of view must leave the selection, or the count says
  // "381 selected" while 34 rows are shown and a bulk action hits the wrong set.
  // EXCEPT a "select all N matching" selection, made under these very filters:
  // it deliberately reaches past this page. Trimming it here shrank it back to
  // the page at once. Kept while the filters are unchanged.
  const _matchingSel = SEL_MATCHING && SEL_MATCHING === `${status_}|${feedFilterSig()}`;
  if (!_matchingSel) {
    SEL_MATCHING = null;
    const visible = new Set(rows.map(r => r.id));
    [...SEL].forEach(id => { if (!visible.has(id)) SEL.delete(id); });
  }
  // The pager already shows "51-100 of 381", so this element carries only the
  // SELECTION count -- which paintBulk sets. Blanking it here ran after that
  // and wiped it on every render, which is why the count never appeared on
  // either grid however it was written.
  // Content first, then reveal.
  $('#colhead').innerHTML = headerHtml();
  $('#colhead').classList.add('on');
  // The toolbar stays while a search is running, even with no results. It
  // holds the search box, so hiding it left no way to clear the term -- you had
  // to press Reset Filters to get the grid back.
  renderGridIcons(true);
  // Vendor and Category exist on both queues; User and Time Stamp only mean
  // something once a charge has been resolved.
  $('#fcvenWrap').style.display = editableHere() ? '' : 'none';
  $('#fcatWrap').style.display = editableHere() ? '' : 'none';
  // The whole row goes, not just its fields, so For Review has no empty band.
  // User and Time Stamp only mean something once a charge is resolved.
  // Bank Detail moves to row 2 on For Review, where row 1 is otherwise short;
  // BANK DETAIL NO LONGER MOVES.
  //
  // It used to be shuffled between two wrapping rows depending on the tab,
  // because those rows re-flowed at every window width and the field landed
  // somewhere different each time. The dialog puts one field per line in a
  // fixed order, so there is nothing to compensate for -- and the two row
  // containers this reached for no longer exist, which would have thrown here
  // on every render.
  $('#fuserWrap').style.display = resolutionCols() ? '' : 'none';
  $('#ftsFromWrap').style.display = resolutionCols() ? '' : 'none';
  $('#ftsToWrap').style.display = resolutionCols() ? '' : 'none';
  // Only Categorized has a QuickBooks id to filter on -- nothing on For Review
  // has been posted yet.
  // Bank Detail is the first field of row 2 in the markup, on every tab. An
  // older version of this function moved it back into row 1 on For Review,
  // which is why it kept reappearing there after every render.
  // Strength only filters on For Review, where a strength exists.

  // Only For Review has anything left to match.

  markActiveFilters();
  refreshUndo();
  $('#list').style.opacity = '';
  $('#list').innerHTML = rows.length ? rows.map(rowHtml).join('')
    : '<div class="empty">Nothing here.</div>';
  // Frozen columns, re-pinned on every draw (Settings: Freeze the Action and
  // Card Account columns).
  applyFreeze();
  wireRows();
  updateBulk();
  alignDetailLines();
}

// Where the Profile column starts, in pixels from the left of the grid. The
// STH and bill lines both begin there, so they read as a column under it
// rather than as two lines floating near the left edge.
// Where the CARD ACCOUNT column starts, in pixels from the left of the grid.
// Both detail lines begin there, so they read as a block hanging under the row
// rather than as two lines at two different insets.
function alignDetailLines() {
  // COMPUTED, not measured. getBoundingClientRect returns zeroes whenever the
  // grid is not laid out at the moment this runs -- mid-render, or on a tab
  // that is hidden -- and the fallback then pinned the detail lines at 34px,
  // which is why they sat far left of Card Account however the columns moved.
  //
  // The widths are all ours: the select-all checkbox, then every visible column
  // before Card Account. Adding them up gives the same answer without
  // depending on when this is called.
  const cols = visibleColumns();
  const i = cols.findIndex(c => c.key === 'card');
  if (i < 0) {
    document.documentElement.style.setProperty('--card-indent', '34px');
    return;
  }
  const cs = getComputedStyle(document.documentElement);
  const px = key => {
    const v = (PREFS.widths || {})[key];
    if (v) return parseInt(v, 10) || 0;
    // The Company column (Multi-Company) has a fixed width of its own.
    if (key === 'company') return 150;
    const varName = COL_VAR[key];
    return varName ? (parseInt(cs.getPropertyValue(varName), 10) || 0) : 0;
  };
  // The checkbox column, matching .hd's leading control, plus the inset the
  // cell puts before its own text -- so the pills start where the words "Card
  // Account" start rather than at the column's edge.
  let left = 28 + 16;
  for (let n = 0; n < i; n++) left += px(cols[n].key);
  // MEASURED WHEN IT CAN BE: where the Card Account heading's words actually
  // begin, relative to the header row. The sum above missed something in
  // Multi-Company, where the pills sat left of the heading; the measurement
  // cannot. The sum remains for when the grid is not laid out.
  const hd = document.querySelector('#colhead .c-card');
  const row0 = document.getElementById('colhead');
  if (hd && row0 && hd.offsetWidth) {
    const pad = parseFloat(getComputedStyle(hd).paddingLeft) || 0;
    const measured = hd.getBoundingClientRect().left - row0.getBoundingClientRect().left + pad;
    if (measured > 20) left = measured;
  }
  document.documentElement.style.setProperty(
    '--card-indent', Math.max(34, Math.round(left)) + 'px');
}

function wireRows() {
  if (!CAN.write) {
    document.querySelectorAll('.pick, .doMatch, .doCode, .doExclude, .doUndo')
      .forEach(el => { el.disabled = true; el.style.display = 'none'; });
    const bb = $('#bulkinline');
    if (bb) bb.style.display = 'none';
    return;
  }
  const boxes = [...document.querySelectorAll('.pick')];
  boxes.forEach(cb => cb.onclick = ev => {
    ev.stopPropagation();
    const idx = boxes.indexOf(cb);
    // Shift-click selects everything between the last click and this one --
    // the usual spreadsheet behavior, and much faster than ticking 40 rows.
    if (ev.shiftKey && LAST_CLICKED !== null && LAST_CLICKED !== idx) {
      const [a, b] = [Math.min(LAST_CLICKED, idx), Math.max(LAST_CLICKED, idx)];
      const on = cb.checked;
      for (let i = a; i <= b; i++) {
        boxes[i].checked = on;
        on ? SEL.add(boxes[i].dataset.id) : SEL.delete(boxes[i].dataset.id);
      }
    } else {
      cb.checked ? SEL.add(cb.dataset.id) : SEL.delete(cb.dataset.id);
    }
    LAST_CLICKED = idx;
    updateBulk();
  });
  document.querySelectorAll('.doMatch').forEach(b => b.onclick = e => {
    e.stopPropagation(); act('match', [b.dataset.id], {bill_id: b.dataset.bill});
  });
  // Setting .onclick REPLACES the inline onclick attribute, so the
  // stopPropagation written there never ran -- clicking a pencil also hit the
  // row's expand toggle, which re-rendered and swallowed the edit. Every
  // in-row control now stops the event itself.
  // NOT the filter pickers.
  //
  // The Vendor and Category filters carry `cellsel` for the styling and
  // `filterpick` for the behavior -- and this ran AFTER their handler, so
  // assigning .onclick replaced it. Every click opened the charge-edit picker
  // instead, against a button with no charge behind it: "Could not save,
  // charge not found".
  document.querySelectorAll('.cellsel:not(.filterpick)').forEach(
    b => b.onclick = e => {
      e.stopPropagation();
      openPicker(b);
    });

  document.querySelectorAll('.ed-open').forEach(b => b.onclick = e => {
    e.stopPropagation();
    EDIT_CELL = `${b.dataset.id}::${b.dataset.field}`;
    render();
    const f = document.querySelector('.ed-input');
    if (f) { f.focus(); f.select(); }
  });
  document.querySelectorAll('.ed-cancel').forEach(b => b.onclick = e => {
    e.stopPropagation();
    EDIT_CELL = '';
    render();
  });

  const saveCell = async btn => {
    const {id, field} = btn.dataset;
    const input = document.querySelector('.ed-input');
    if (!input) return;
    btn.disabled = true;
    const fd = new FormData();
    fd.append('charge_id', id);
    // Only the field being edited is sent. An absent field means "leave it
    // alone", so one cell can never quietly overwrite another -- and an empty
    // one is named explicitly, since empty and absent look the same over a form.
    fd.append(field, input.value);
    if (!input.value.trim() && (field === 'vendor' || field === 'category')) {
      fd.append('clear', field);
    }
    try {
      const r = await api('/queue/edit', {method: 'POST', body: fd});
      EDIT_CELL = '';
      // Say when the change reached QuickBooks -- silence would leave someone
      // wondering whether the ledger followed.
      // A Custom Note goes into the QuickBooks memo too, in brackets.
      if (field === 'custom_note') flash('Note saved'); else flashEdit(field, r.qbo);
      await load();
    } catch (e) {
      notify(e.message, 'Could not save');
      btn.disabled = false;
    }
  };
  document.querySelectorAll('.ed-save').forEach(b => b.onclick = e => {
    e.stopPropagation(); saveCell(b);
  });
  document.querySelectorAll('.ed-input').forEach(inp => {
    inp.addEventListener('keydown', e => {
      if (e.key === 'Enter') {
        const b = document.querySelector(
          `.ed-save[data-id="${CSS.escape(inp.dataset.id)}"]`);
        if (b) saveCell(b);
      } else if (e.key === 'Escape') { EDIT_CELL = ''; render(); }
    });
  });

  document.querySelectorAll('.doCode').forEach(b => b.onclick = e => {
    e.stopPropagation();
    const id = b.dataset.id;
    // The Vendor and Category columns ARE the coding form now, so this commits
    // whatever they show -- the engine's suggestion, or an override typed into
    // the cell.
    const it = (QUEUE.items || []).find(x => x.id === id);
    if (!it) return;
    // A split transaction carries its categories on its LINES, so the cell
    // renders blank and this refused it for having none. The first line stands
    // in; the server posts every line whatever is sent here. The batch Add had
    // the same bug -- this is the per-row button, a separate path.
    // A payment onto the card is not an expense: it posts as a Transfer or a
    // Credit Card Payment between two accounts, so it has no vendor and no
    // category to ask for. The other side is the primary account set on Card
    // Accounts.
    if (it.is_card_payment) { act('code', [id]); return; }
    const cat = (it.split_lines > 1
      ? ((it.split_detail || [])[0] || {}).category || ''
      : categoryCell(it)).trim();
    const ven = vendorCell(it).trim();
    if (!cat || !ven) {
      const missing = [!cat && 'Category', !ven && 'Vendor'].filter(Boolean);
      notify(`${missing.join(' and ')} ${missing.length > 1 ? 'are' : 'is'} `
             + `required before adding`);
      return;
    }
    act('code', [id], {category: cat, vendor: ven});
  });
  // One row, same code paths as the batch buttons -- passing a single-item list
  // rather than a second implementation that could drift from the first.
  document.querySelectorAll('.rowForce').forEach(b => b.onclick = e => {
    e.stopPropagation(); openForceMatch(b.dataset.id);
  });
  document.querySelectorAll('.rowSplit').forEach(b => b.onclick = e => {
    e.stopPropagation(); splitDialog([b.dataset.id]);
  });
  document.querySelectorAll('.rowExclude').forEach(b => b.onclick = e => {
    e.stopPropagation(); act('exclude', [b.dataset.id]);
  });
  document.querySelectorAll('.rowUndo').forEach(b => b.onclick = e => {
    e.stopPropagation(); undoOrDelete([b.dataset.id]);
  });
  document.querySelectorAll('.rowDelete').forEach(b => b.onclick = e => {
    e.stopPropagation();
    // Two different deletes. On EXCLUDED it is a permanent purge; on
    // CATEGORIZED it undoes the coding and removes the QuickBooks transaction,
    // which is what the batch Delete has always done. Sending both through
    // purgeIds meant the Categorized trash showed the purge warning and then
    // deleted nothing, because the charge was not excluded.
    if (status_ === 'excluded') purgeIds([b.dataset.id]);
    else undoOrDelete([b.dataset.id]);
  });

  document.querySelectorAll('.doExclude').forEach(b => b.onclick = e => {
    e.stopPropagation(); act('exclude', [b.dataset.id]);
  });
  document.querySelectorAll('.doUndo').forEach(b => b.onclick = e => {
    e.stopPropagation(); act('undo', [b.dataset.id]);
  });
}

function updateBulk() {
  const boxes = [...document.querySelectorAll('.pick')];
  const all = $('#pickAll');
  if (all) {
    const n = boxes.filter(b => b.checked).length;
    all.checked = boxes.length > 0 && n === boxes.length;
    all.indeterminate = n > 0 && n < boxes.length;
  }
  const box = $('#bulkinline');
  // Deleting is irreversible, so it only appears once rows are actually picked.
  const pg = $('#purgeBtn');
  // From TWO rows up: one excluded row is deleted with its own trash icon, and
  // a bar appearing for a single selection duplicated the row's own button.
  if (pg) pg.style.display = 'none';   // lives inside Batch Actions now
  // Exclude makes no sense once a charge is resolved, and "un-exclude" only
  // means something on the Excluded tab.
  // On For Review the individual buttons give way to one Batch Actions button:
  // four choices in a row is a lot to scan, and Match All needs explaining.
  // Two or more, because "batch" over a single row is just the row's own
  // buttons with an extra dialog in the way.
  // On both queues, from two rows up. The options differ -- Categorized has
  // nothing to match or add, only corrections to make.
  const bb = $('#bBatch');
  if (bb) {
    // Never shown. It stays in the DOM because the toolbar button and Batch
    // Actions' own "Add All" both drive it, but the reader only ever sees the
    // one control in the toolbar.
    bb.style.display = 'none';
  }
  const bx = $('#bExclude'), bu = $('#bUndo'), ba = $('#bAdd');
  // Superseded by Batch Actions on both tabs; kept so their handlers can be
  // reused rather than duplicated.
  [['#bSetVendor', 'vendor'], ['#bSetCategory', 'category']].forEach(([sel]) => {
    const el = $(sel);
    if (el) el.style.display = 'none';
  });
  if (bx) {
    // Excluding is a removal, so it reads like one. Assigned rather than
    // appended: += grew the style attribute by the same declarations on every
    // render, and it has to precede the display line either way.
    bx.className = '';
    bx.style.cssText = 'background:var(--bad);color:#fff;'
      + 'border:1px solid var(--bad);border-radius:6px;padding:5px 14px;'
      + 'font-weight:600';
    // Never on the bar. One row has its own Exclude icon; several go through
    // Batch Actions, which already offers it -- showing it twice put a
    // destructive button next to the menu that contains it.
    bx.style.display = 'none';
  }
  // One row only. Splitting several charges at once would mean one set of
  // proportions across different amounts, which is a different feature and not
  // one anybody has asked for -- from two rows up it moves into Batch Actions,
  // which explains that it is applied to each charge separately.
  const bs = $('#bSplit');
  if (bs) {
    // Never for a single row now -- that is the split icon in the Action
    // column. Two or more still goes through Batch Actions, which explains that
    // the split is applied to each charge separately.
    bs.style.display = 'none';
  }
  // Never shown -- Batch Actions is the way in. Kept only so "Add All" can
  // reuse its handler.
  if (ba) ba.style.display = 'none';
  if (bu) {
    // From two rows up on Categorized it lives inside Batch Actions instead.
    // Excluded has no Batch Actions, so Unexclude stays on the bar there.
    // From two rows up it lives in Batch Actions, so showing it here as well
    // offered the same destructive action twice.
    // "Undo" understated it. On Categorized this removes the transaction from
    // QuickBooks, which is a deletion however it is reached, and the button
    // should look like the thing it does.
    const del = status_ === 'categorized';
    bu.textContent = status_ === 'excluded' ? 'Unexclude' : 'Delete';
    // cssText REPLACES the whole style attribute, so it has to come before the
    // display line rather than after it. Setting display first and then
    // assigning cssText wiped the display:none, which is why this button kept
    // appearing on For Review and alongside Batch Actions however many times
    // the condition below was corrected.
    bu.style.cssText = del
      ? 'background:var(--bad);color:#fff;border:1px solid var(--bad);'
        + 'border-radius:6px;padding:5px 14px;font-weight:600'
      : '';
    bu.className = del ? '' : 'ghost';
    // Never on the bar: one row uses its own icon, several go through Batch
    // Actions, which now lists both Unexclude and Delete Permanently.
    bu.style.display = 'none';
  }

  // One row only. Several is a batch decision, and Batch Actions is where
  // batch decisions are confirmed.
  const bt = $('#batchTop');
  if (bt) {
    // Always there, so the control does not appear and disappear as rows are
    // ticked -- it just stops being usable.
    // Bills keep their own selection set, so the count comes from whichever
    // grid is on screen.
    const n = isBills() ? BILL_SEL.size : SEL.size;
    const on = n > 1 && ['for_review', 'categorized', 'excluded', 'bills', 'allbills']
      .includes(status_);
    bt.disabled = !on;
    bt.style.background = on ? '#15803d' : '#e9edf2';
    bt.style.color = on ? '#fff' : '#b3bcc7';
    bt.style.borderColor = on ? '#15803d' : '#e9edf2';
    bt.style.cursor = on ? 'pointer' : 'default';
    bt.title = on ? 'Act on the selected rows' : 'Select two or more rows';
    bt.onclick = () => {
      if (!on) return;
      // Disabled buttons still receive clicks in some browsers when styled
      // rather than truly disabled, so the guard is here as well.
      (isBills() ? $('#billBatch') : $('#bBatch')).click();
    };
  }
  // Same rule for the Categorized delete: one row here, several via Batch.
  const dl1 = $('#deleteOne');
  if (dl1) {
    const on1 = SEL.size === 1;
    dl1.disabled = !on1;
    dl1.style.opacity = on1 ? '' : '.4';
    dl1.style.cursor = on1 ? 'pointer' : 'default';
    dl1.title = on1 ? 'Delete the selected transaction'
      : SEL.size ? 'Several selected — use Batch Actions'
      : 'Select one transaction to delete';
  }
  const ex1 = $('#excludeOne');
  if (ex1) {
    const on = SEL.size === 1;
    ex1.disabled = !on;
    ex1.style.opacity = on ? '' : '.4';
    ex1.style.cursor = on ? 'pointer' : 'default';
    ex1.title = on ? 'Exclude the selected transaction'
      : SEL.size ? 'Several selected — use Batch Actions'
      : 'Select one transaction to exclude';
  }
  if (box) {
    box.style.display = SEL.size ? 'flex' : 'none';
    box.style.alignItems = 'center';
  }
  // The count lives on the centerd pager line, which is rebuilt each render.
  const bar = $('#pagerbar');
  if (bar) {
    // Keyed off the SELECTION, not off the count's text -- the count moved to
    // the pagination row, so reading it here hid the bar permanently.
    bar.style.display = SEL.size ? 'flex' : 'none';
  }
  // THE COUNT LIVES ON THE PAGINATION ROW, at its end.
  //
  // It was in the bulk bar, which appears and disappears with the selection --
  // so the number moved the buttons sideways as it changed width, and on a
  // narrow window it wrapped the row. #shown already sits at the end of the
  // pagination row and was being blanked deliberately; it is the natural home
  // for "how many of these am I acting on".
  // #bulkn, which #pagerbar CREATES INSIDE ITSELF and keys its own visibility
  // on. #shown lives in an earlier row that pagerbar neither contains nor
  // reveals, so writing the count there produced text in a hidden element on
  // both grids -- and pagerbar, finding #bulkn empty, kept itself closed.
  //
  // pagerbar sits at the end of the pagination area, which is where this was
  // asked to go; the count did not need to move, only to stop being blanked.
  const total = QUEUE.total || 0;
  // WHAT THE SELECTION ADDS UP TO: charges, and refunds and payments apart
  // from them, each with its count and total. Only rows on screen can be
  // added up; a selection reaching past this page says so rather than giving
  // a partial total as though it were the whole.
  let _sum = '';
  if (SEL.size) {
    const byId = new Map((QUEUE.items || []).map(x => [String(x.id), x]));
    const parts = {charge: [0, 0], refund: [0, 0], payment: [0, 0]};
    let seen = 0;
    SEL.forEach(id => {
      const x = byId.get(String(id));
      if (!x) return;
      seen++;
      const k = !x.is_credit ? 'charge' : (x.is_card_payment ? 'payment' : 'refund');
      parts[k][0]++;
      parts[k][1] += Math.abs(Number(x.amt) || 0);
    });
    // EVERY ROW selected with "Select all N matching": the server's totals,
    // for as long as the selection is still exactly that set.
    let _all = false;
    if (SEL_MATCHING && SEL_TOTALS && SEL_TOTALS.count === SEL.size) {
      for (const k of ['charge', 'refund', 'payment']) {
        parts[k] = [SEL_TOTALS.totals[k].n, Number(SEL_TOTALS.totals[k].amount) || 0];
      }
      seen = SEL.size; _all = true;
    }
    const say = (k, one, many) => parts[k][0]
      ? `${parts[k][0]} ${parts[k][0] === 1 ? one : many} ${fmtAmt(parts[k][1])}` : '';
    const bits = [say('charge', 'charge', 'charges'), say('refund', 'refund', 'refunds'),
                  say('payment', 'payment', 'payments')].filter(Boolean);
    if (bits.length) _sum = ' \u00b7 ' + bits.join(' \u00b7 ');
    if (seen < SEL.size) _sum += ` (totals for the ${seen} on this page)`;
  }
  const _txt = SEL.size ? `${SEL.size} of ${total} selected${_sum}` : '';
  setSelectionCount(_txt);
  // SELECT EVERYTHING THE FILTERS MATCH, not just this page. Offered once the
  // whole page is ticked and more rows match beyond it; the batch actions --
  // Exclude among them -- then apply to every one of them. The function for
  // it existed, but nothing on screen called it.
  const _pageIds = (QUEUE.items || []).map(x => String(x.id));
  const _wholePage = _pageIds.length && _pageIds.every(id => SEL.has(id) || SEL.has(Number(id)));
  const _t = $('#shown');
  if (_t && !isBills() && _wholePage && total > SEL.size) {
    const a = document.createElement('a');
    a.href = '#';
    a.textContent = ` Select all ${total.toLocaleString()} matching`;
    a.style.cssText = 'margin-left:8px;font-weight:600';
    a.onclick = ev => { ev.preventDefault(); selectAllMatching(); };
    _t.appendChild(a);
  } else if (_t && !isBills() && SEL_MATCHING && SEL.size > _pageIds.length) {
    // AND BACK: once everything matching is selected, the same place offers to
    // clear it -- every page's selection, not just this one's.
    const a = document.createElement('a');
    a.href = '#';
    a.textContent = ' Deselect all';
    a.style.cssText = 'margin-left:8px;font-weight:600';
    a.onclick = ev => {
      ev.preventDefault();
      SEL = new Set(); SEL_MATCHING = null; SEL_TOTALS = null;
      render(); updateBulk();
    };
    _t.appendChild(a);
  }

}

async function act(action, ids, extra = {}) {
  const fd = new FormData();
  fd.append('ids', ids.join(','));
  fd.append('action', action);
  Object.entries(extra).forEach(([k, v]) => fd.append(k, v));
  try {
    const r = await api('/queue/resolve', {method: 'POST', body: fd});
    const n = r.changed || 0;
    if (n && !r.conflicts && !r.post_failed) {
      // "Undo" on the Excluded tab is an unexclude, and calling it "Undone"
      // described the click rather than what happened to the charge.
      const verb = {match: 'Matched', code: 'Added', exclude: 'Excluded',
                    undo: status_ === 'excluded' ? 'Unexcluded' : 'Undone'
                   }[action] || 'Updated';
      flash(n === 1 ? `Transaction ${verb}` : `${n} Transactions ${verb}`);
    }
    if (r.conflicts) {
      // WHO got there first, where known; and the moment both pressed at once.
      const cmsgs = [...new Set((r.conflict_detail || []).map(x =>
        x.status === 'posting' ? 'Someone else is posting this transaction right now'
        : (x.status === 'excluded' ? 'Transaction already excluded' : 'Transaction already categorized')
          + (x.resolved_by ? ` by ${x.resolved_by}` : '')))];
      notify(cmsgs.length ? cmsgs.join('\n\n') : 'Transaction already categorized');
    }
    if (r.post_failed) {
      // Show the reason, nothing else. When every failure has the same cause
      // -- the common case, since a bulk action usually fails for one reason
      // -- that is a single line and no scaffolding around it.
      const msgs = [...new Set((r.errors || []).map(e => e.error))];
      notify(msgs.length ? msgs.join('\n\n')
                        : 'Could not post to QuickBooks');
    }
    await load();
  } catch (e) { notify(e.message); }
}

// bulk actions
// Two different things, deliberately kept separate:
//   "Select all in this view"  -> the rows currently on screen
//   "Select all N matching"    -> every row the filters match, across pages
async function selectAllMatching() {
  const fd = new FormData();
  fd.append('company', company());
  fd.append('status', status_);
  if (CARD_SEL.size) fd.append('card', [...CARD_SEL].join(','));
  if (compFilter()) fd.append('companies', compFilter());
  Object.entries(MULTI_PARAM).forEach(([key, param]) => {
    if (!MULTI[key].tabs.includes(status_)) return;
    const v = multiValue(key);
    if (v) fd.append(param, v);
  });
  Object.entries(activeFilters()).forEach(([k, v]) => fd.append(k, v));
  try {
    const j = await api('/queue/select-all', {method: 'POST', body: fd});
    SEL = new Set(j.ids);
    SEL_MATCHING = `${status_}|${feedFilterSig()}`;
    SEL_TOTALS = j.totals ? {count: j.count, totals: j.totals} : null;
    render();
    updateBulk();
  } catch (e) { notify(e.message); }
}
// Delegated: the header is rebuilt whenever the column layout changes, so a
// handler bound directly to the element would be discarded with it.
document.addEventListener('change', e => {
  if (!e.target.matches('#pickAll')) return;
  // The header box mirrors the page: ticking it selects the rows on screen,
  // clearing it deselects them.
  const on = e.target.checked;
  document.querySelectorAll('.pick').forEach(cb => {
    cb.checked = on;
    on ? SEL.add(cb.dataset.id) : SEL.delete(cb.dataset.id);
  });
  updateBulk();
});

// Shared by the batch button and the per-row trash icon, so one confirmation
// and one request shape rather than two that could drift apart.
async function purgeIds(list) {
  if (!list.length) return;
  const ok = await askConfirm('Permanently delete',
    `Permanently delete <b>${list.length}</b> excluded charge(s)?`
    + `<br><br>This cannot be undone. They can be re-uploaded afterwards.`,
    'Delete', 'Cancel');
  if (!ok) return;
  // Grouped BY COMPANY: in Multi-Company the selection can span several,
  // and each company deletes only its own.
  const byCo = {};
  list.forEach(id => {
    const it = (QUEUE.items || []).find(x => String(x.id) === String(id));
    const co = it ? rowCompany(it) : String(id).split(':')[0];
    (byCo[co] = byCo[co] || []).push(id);
  });
  let deleted = 0;
  try {
    for (const [co, ids] of Object.entries(byCo)) {
      const fd = new FormData();
      fd.append('company', co);
      fd.append('ids', ids.join(','));
      const j = await api('/queue/purge', {method: 'POST', body: fd});
      deleted += j.deleted || 0;
    }
    list.forEach(x => SEL.delete(x));
    await load();
    flash(`${deleted} charge(s) permanently deleted`);
  } catch (e) {
    notify(e.message, 'Could not delete');
  }
}

$('#purgeBtn').onclick = async () => {
  if (!SEL.size) return;
  const ok = await askConfirm('Permanently delete',
    `Permanently delete <b>${SEL.size}</b> excluded charge(s)?`
    + `<br><br>This cannot be undone. They can be re-uploaded afterwards.`,
    'Delete', 'Cancel');
  if (!ok) return;
  const ids = [...SEL].join(',');
  const fd = new FormData();
  fd.append('company', company());
  fd.append('ids', ids);
  const btn = $('#purgeBtn');
  btn.disabled = true;
  try {
    // One confirmation is enough. An excluded charge is one you've already
    // decided doesn't belong, so if a stale QuickBooks reference is attached
    // it goes with it rather than prompting again.
    const j = await api('/queue/purge', {method: 'POST', body: fd});
    SEL.clear();
    await load();
    // Nothing about QuickBooks: an excluded charge has no transaction there.
    flash(`${j.deleted} charge(s) permanently deleted`);
  } catch (e) {
    showWarn('Could not delete', esc(e.message));
  }
  btn.disabled = false;
};
// Code every selected charge in one go, each with ITS OWN vendor and category.
// One shared category for the batch would be quicker to build and wrong most of
// the time -- the whole point of the suggestions is that they differ per row.
// The work, separated from the asking. "Update & Add" has already confirmed --
// making it confirm a second time turns one decision into two dialogs.
async function bulkAdd({confirm = true} = {}) {
  const rows = (QUEUE.items || []).filter(r => SEL.has(r.id));
  const groups = new Map();
  const missing = [];
  rows.forEach(r => {
    // Card payments carry no vendor or category by design -- they post as a
    // Transfer or Credit Card Payment, not an expense.
    if (r.is_card_payment) {
      const key = '\u0000payment';
      if (!groups.has(key)) groups.set(key, {cat: '', ven: '', ids: [], payment: true});
      groups.get(key).ids.push(r.id);
      return;
    }
    // A split transaction HAS categories -- several of them, on its lines --
    // so categoryCell renders blank and the row was refused for having none.
    // The first line's category stands in for grouping; the server posts every
    // line regardless of what is sent here.
    const cat = (r.split_lines > 1
      ? ((r.split_detail || [])[0] || {}).category || ''
      : categoryCell(r)).trim();
    const ven = vendorCell(r).trim();
    if (!cat || !ven) { missing.push(r); return; }
    const key = cat + '\u0000' + ven;
    if (!groups.has(key)) groups.set(key, {cat, ven, ids: []});
    groups.get(key).ids.push(r.id);
  });
  if (!groups.size) {
    notify(`None of the ${rows.length} selected transaction(s) have both a Vendor `
           + `and a Category set. Fill those in first.`, 'Nothing to add');
    return;
  }
  if (confirm) {
    const go = await askConfirm('Add selected',
      `Code <b>${rows.length - missing.length}</b> transaction(s), each with the Vendor `
      + `and Category shown on its row?`
      + (missing.length ? `<br><br><b>${missing.length}</b> will be skipped — no `
          + `Vendor or Category set.` : ''),
      'Add', 'Cancel', {goGreen: true});
    if (!go) return;
  }

  const btn = $('#bAdd');
  btn.disabled = true;
  let done = 0, failed = 0;
  try {
    // One request per distinct (category, vendor) pair rather than per row:
    // 200 charges from one merchant become a single call.
    for (const g of groups.values()) {
      const fd = new FormData();
      fd.append('ids', g.ids.join(','));
      fd.append('action', 'code');
      fd.append('category', g.cat);
      fd.append('vendor', g.ven);
      try {
        const r = await api('/queue/resolve', {method: 'POST', body: fd});
        done += r.changed || 0;
        failed += (r.post_failed || 0) + (r.conflicts || 0);
      } catch (e) { failed += g.ids.length; }
    }
  } finally { btn.disabled = false; }

  SEL.clear();
  await load();
  if (failed) {
    notify(`${done} added. ${failed} could not be — check For Review and the `
           + `audit log.`, 'Partly done');
  } else {
    flash(done === 1 ? 'Transaction Added' : `${done} Transactions Added`);
  }
}

$('#bAdd').onclick = () => bulkAdd();

// Set one vendor or category across every selected charge.
//
// Each row is its own QuickBooks update, so this is a sequence of edits rather
// than one call -- and a failure partway through leaves the successes standing,
// because rolling them back would mean more writes to a ledger that just
// refused one.
// Match every selected charge to its own top-ranked bill.
//
// One request per charge, because each goes to a different bill -- the batch
// resolve endpoint takes a single bill id, which is right for "these five
// charges paid this one bill" and wrong for this.
async function bulkMatch() {
  const rows = (QUEUE.items || []).filter(r => SEL.has(r.id));
  const withBill = rows.filter(r => (r.candidates || []).length);
  const skipped = rows.length - withBill.length;
  if (!withBill.length) {
    notify('None of the selected charges has a suggested bill.', 'Nothing to match');
    return;
  }
  const go = await askConfirm('Match All',
    `Match <b>${withBill.length}</b> transaction(s), each to its highest-ranked bill?`
    + (skipped ? `<br><br><b>${skipped}</b> with no candidate will be skipped.` : ''),
    'Match', 'Cancel', {goGreen: true});
  if (!go) return;

  let done = 0;
  const failed = [];
  for (const r of withBill) {
    const fd = new FormData();
    fd.append('ids', r.id);
    fd.append('action', 'match');
    fd.append('bill_id', r.candidates[0].bill_id);
    try {
      const res = await api('/queue/resolve', {method: 'POST', body: fd});
      if (res.post_failed) failed.push(`${r.merchant || r.id}: ${res.errors?.[0]?.error || 'post failed'}`);
      else done += 1;
    } catch (e) {
      failed.push(`${r.merchant || r.id}: ${e.message}`);
    }
  }
  SEL.clear();
  await load();
  if (failed.length) {
    notify(`${done} matched. ${failed.length} could not be:<br><br>`
           + failed.slice(0, 6).map(esc).join('<br>'), 'Partly done', {html: true});
  } else {
    flash(done === 1 ? 'Transaction Matched' : `${done} Transactions Matched`);
  }
}

// Update, or update and then post in one go. Two separate trips through the
// same selection is the common case, and the second one is easy to forget.
function askUpdate(title, body) {
  return new Promise(resolve => {
    const box = $('#confirm3');
    $('#c3Title').textContent = title;
    $('#c3Body').innerHTML = body;
    $('#c3Cancel').onclick = () => { box.close(); resolve(null); };
    $('#c3Go').onclick = () => { box.close(); resolve('update'); };
    $('#c3GoAdd').onclick = () => { box.close(); resolve('add'); };
    // Nothing to add on Categorized -- those charges are already in QuickBooks,
    // and the update posts there by itself.
    // With nothing to add, Update becomes the only way forward, so it takes
    // the green the confirmations elsewhere give the action you came to do.
    const add = status_ === 'for_review';
    $('#c3GoAdd').style.display = add ? '' : 'none';
    $('#c3Go').style.cssText = (add
      ? 'background:var(--accent);border:1px solid var(--accent);'
      : 'background:#15803d;border:1px solid #15803d;')
      + 'color:#fff;border-radius:6px;padding:6px 16px;font-weight:600';
    box.showModal();
  });
}

// UPDATE FIELDS: one window for the fields a batch can set, a column each
// with its picker. A field left blank keeps what each row already has.
// Resolves to {values, go: 'update' | 'add'} or null.
function updateFieldsDialog(title, cols, opts = {}) {
  return new Promise(resolve => {
    const d = document.createElement('dialog');
    d.id = 'updFields';
    d.style.cssText = `max-width:${opts.width || 760}px;width:94vw;border:1px solid var(--line);border-radius:10px;padding:16px 18px`;
    const vals = {};
    const colHtml = c => c.kind === 'html' ? c.html : `
      <div style="flex:1;min-width:0">
        <label style="display:block;font-weight:600;margin-bottom:4px">${esc(c.label)}</label>
        ${c.kind === 'text'
          ? `<input class="ufText" data-k="${c.key}" placeholder="Leave as is" style="width:100%;box-sizing:border-box">`
          : `<button class="cellsel filterpick ufPick" data-k="${c.key}" style="width:100%;min-height:38px;box-sizing:border-box;padding:6px 10px;background:#fff;border:1px solid var(--line);border-radius:6px"><span class="cs-v"><i style="color:var(--tx2)">Leave as is</i></span><span class="cs-c">▾</span></button>`}
      </div>`;
    d.innerHTML = `<h3 style="margin:0 0 6px;text-align:center">${esc(title)}</h3>
      <div style="font-size:12px;color:var(--tx2);margin-bottom:12px;text-align:center">${opts.sub || ''}</div>
      <div style="display:flex;gap:18px;align-items:flex-start">${cols.map(colHtml).join('')}</div>
      <div class="dact" style="justify-content:center;margin-top:16px">
        <button class="ufCancel" style="background:var(--bad);color:#fff;border:1px solid var(--bad);border-radius:6px;padding:6px 16px">Cancel</button>
        <button class="ufGo" style="background:${opts.add ? 'var(--accent)' : '#15803d'};color:#fff;border:1px solid ${opts.add ? 'var(--accent)' : '#15803d'};border-radius:6px;padding:6px 16px;font-weight:600">Update</button>
        ${opts.add ? `<button class="ufAdd" style="background:#15803d;color:#fff;border:1px solid #15803d;border-radius:6px;padding:6px 16px;font-weight:600">Update &amp; Add</button>` : ''}
      </div>`;
    document.body.appendChild(d);
    const done = v => { d.close(); d.remove(); resolve(v); };
    d.querySelectorAll('.ufPick').forEach(btn => btn.onclick = e => {
      e.stopPropagation();
      const c = cols.find(x => x.key === btn.dataset.k);
      btn.dataset.value = vals[c.key] || '';
      openPicker(btn, {
        list: () => (c.kind === 'category' ? CATEGORIES.map(x => x.fully_qualified || x.name)
                     : c.kind === 'vendor' ? VENDORS.map(v => v.name || v) : (c.list ? c.list() : [])),
        canCreate: '',
        onPick: v => {
          vals[c.key] = v || '';
          btn.querySelector('.cs-v').innerHTML = v ? esc(v) : '<i style="color:var(--tx2)">Leave as is</i>';
          btn.title = v || '';
        },
      });
    });
    const collect = () => {
      d.querySelectorAll('.ufText').forEach(i => { vals[i.dataset.k] = i.value.trim(); });
      const out = {...vals};
      if (opts.read) Object.assign(out, opts.read(d));
      return out;
    };
    d.querySelector('.ufCancel').onclick = () => done(null);
    d.querySelector('.ufGo').onclick = () => done({values: collect(), go: 'update'});
    const ad = d.querySelector('.ufAdd'); if (ad) ad.onclick = () => done({values: collect(), go: 'add'});
    d.addEventListener('cancel', e => { e.preventDefault(); done(null); });
    if (opts.wire) opts.wire(d);
    d.showModal();
  });
}

// BATCH ACTIONS > UPDATE FIELDS on For Review and Categorized: Vendor,
// Category and Custom Notes together. Update & Add follows on For Review.
async function bulkUpdateFields(ids) {
  const rows = (QUEUE.items || []).filter(r => ids.includes(r.id));
  if (!rows.length) return;
  const forReview = status_ === 'for_review';
  const r = await updateFieldsDialog('Update Fields', [
    {key: 'vendor', label: 'Vendor', kind: 'vendor'},
    {key: 'category', label: 'Category', kind: 'category'},
    {key: 'custom_note', label: 'Custom Notes', kind: 'text'},
  ], {add: forReview, sub: `<b>${rows.length}</b> selected. A field left blank keeps each transaction’s own.`});
  if (!r) return;
  const v = r.values;
  if (!v.vendor && !v.category && !v.custom_note) { flash('Nothing to update'); return; }
  // A bill payment's vendor and category come from its bill: on Categorized
  // only coded rows take them. A note goes on any row.
  let done = 0, skipped = 0; const failed = [];
  for (const row of rows) {
    const fd = new FormData(); fd.append('charge_id', row.id);
    const codedOk = forReview || row.resolution === 'coded';
    let any = false;
    if (v.vendor && codedOk) { fd.append('vendor', v.vendor); any = true; }
    if (v.category && codedOk) { fd.append('category', v.category); any = true; }
    if (v.custom_note) { fd.append('custom_note', v.custom_note); any = true; }
    if (!any) { skipped++; continue; }
    try {
      await api('/queue/edit', {method: 'POST', body: fd});
      if (v.vendor && codedOk) { row.coded_vendor = v.vendor; row.suggested_vendor = v.vendor; }
      if (v.category && codedOk) { row.coded_category = v.category; row.suggested_category = v.category; }
      done++;
    } catch (e) { failed.push(`${row.merchant || row.id}: ${e.message}`); }
  }
  if (failed.length) {
    SEL.clear(); await load();
    notify(`${done} updated. ${failed.length} could not be:<br><br>` + failed.slice(0, 5).map(esc).join('<br>'),
           'Partly done', {html: true});
    return;
  }
  if (r.go === 'add' && forReview) return bulkAdd({confirm: false});
  SEL.clear(); await load();
  flash(`${done} transaction(s) updated` + (skipped ? ` — ${skipped} bill payment(s) skipped` : ''));
}

// OPEN BILLS > BATCH ACTIONS > UPDATE FIELDS: Vendor and Amount together.
async function billUpdateFields(ids) {
  if (!ids.length) return;
  const amtCol = `<div style="flex:1.4;min-width:0">
      <label style="display:block;font-weight:600;margin-bottom:4px">Amount</label>
      <select class="ufMode" style="width:100%">
        <option value="">Leave as is</option>
        <option value="set">New amount</option>
        <option value="delta">Increase or decrease by fixed $ amount</option>
        <option value="percent">Increase or decrease by % of total</option>
        <option value="cad">Adjust for CAD to USD</option>
        <option value="vendors_open">Adjust for Vendors Open</option>
      </select>
      <div class="ufValRow" style="display:none;align-items:center;gap:6px;margin-top:6px">
        <span class="ufUnit" style="font-size:15px;color:var(--tx2);width:14px">$</span>
        <input class="ufVal" type="number" step="0.01" placeholder="0.00" style="width:150px;flex:none"></div>
      <div class="ufHint" style="font-size:11px;color:var(--tx2);margin-top:6px"></div>
      <div class="ufHow" style="display:none;margin-top:8px;font-size:13px">
        <div style="font-weight:600">Record an increase as</div>
        <label style="display:flex;gap:6px;align-items:center;font-weight:400;margin:4px 0 0">
          <input type="radio" name="ufHow" value="amount" checked style="width:auto"> A change to the bill's amount</label>
        <label style="display:flex;gap:6px;align-items:center;font-weight:400;margin:2px 0 0">
          <input type="radio" name="ufHow" value="fees" style="width:auto"> An Other Fees line for the difference</label></div>
    </div>`;
  const r = await updateFieldsDialog('Update Fields', [
    {key: 'vendor', label: 'Vendor', kind: 'vendor'},
    {kind: 'html', html: amtCol},
  ], {
    width: 680,
    sub: `<b>${ids.length}</b> bill(s) selected. A field left blank keeps each bill’s own.`,
    wire: d => {
      const m = d.querySelector('.ufMode');
      const paint = () => {
        const v = m.value, noVal = !v || v === 'cad' || v === 'vendors_open';
        d.querySelector('.ufValRow').style.display = noVal ? 'none' : 'flex';
        d.querySelector('.ufHow').style.display = (!v || v === 'cad' || v === 'vendors_open') ? 'none' : '';
        d.querySelector('.ufUnit').textContent = v === 'percent' ? '%' : '$';
        d.querySelector('.ufHint').textContent = !v ? '' : v === 'set' ? 'The new total for each bill.'
          : v === 'cad' ? 'Each bill’s amount times the CAD to USD rate on the bill’s date.'
          : v === 'vendors_open' ? 'Adds a negative “Due from Vendors - Open” line for each bill’s open balance.'
          : 'Positive for increase. Negative for decrease.';
      };
      m.onchange = paint; paint();
    },
    read: d => ({mode: d.querySelector('.ufMode').value, value: d.querySelector('.ufVal').value.trim(),
                 how: (d.querySelector('input[name="ufHow"]:checked') || {}).value || 'amount'}),
  });
  if (!r) return;
  const v = r.values, f = {};
  if (v.vendor) f.vendor = v.vendor;
  if (v.mode) {
    const noVal = v.mode === 'cad' || v.mode === 'vendors_open';
    if (!noVal && !v.value) { notify('Enter the amount, or set Amount to Leave as is.', 'Not updated'); return; }
    f.amount_mode = v.mode; f.amount_value = noVal ? '0' : v.value;
    f.amount_how = v.mode === 'cad' ? 'amount' : v.how;
  }
  if (!Object.keys(f).length) { flash('Nothing to update'); return; }
  await applyBillEdit(ids, f);
}

async function bulkSet(field) {
  const label = field === 'vendor' ? 'Vendor' : 'Category';
  const list = field === 'category'
    ? CATEGORIES.map(c => c.fully_qualified || c.name)
    : VENDORS.map(v => v.name || v);
  const rows = (QUEUE.items || []).filter(r => SEL.has(r.id));

  // A bill payment's vendor comes from its bill, and its category is the
  // payment itself -- neither is ours to overwrite in bulk. On For Review
  // nothing is resolved yet, so every selected row is fair game.
  const eligible = status_ === 'for_review'
    ? rows : rows.filter(r => r.resolution === 'coded');
  const skipped = rows.length - eligible.length;
  if (!eligible.length) {
    notify(`None of the selected charges can have their ${label.toLowerCase()} `
           + `changed here — bill payments take theirs from the bill.`,
           `Nothing to update`);
    return;
  }

  const chosen = await pickFromList(`Update ${label}`, list,
                                    {confirmLabel: 'Update'});
  if (chosen === null) return;

  // The QuickBooks note that used to sit here said nothing a reviewer on
  // Categorized didn't already know -- everything on that tab is posted.
  const go = await askUpdate(`Update ${label}`,
    `Update <b>${label}</b> to <b>${esc(chosen)}</b> on <b>${eligible.length}</b> `
    + `transaction(s)?`
    + (skipped ? `<br><br><b>${skipped}</b> bill payment(s) will be skipped.` : ''));
  if (!go) return;
  const alsoAdd = go === 'add';

  let done = 0;
  const failed = [];
  for (const r of eligible) {
    const fd = new FormData();
    fd.append('charge_id', r.id);
    fd.append(field, chosen);
    try {
      await api('/queue/edit', {method: 'POST', body: fd});
      // Applied to the row in memory as well as on the server, so a following
      // Add can read it without a reload. That reload rescored every charge
      // against every bill and rendered nothing anyone saw -- easily the
      // slowest step in the sequence, for no visible result.
      if (field === 'vendor') { r.coded_vendor = chosen; r.suggested_vendor = chosen; }
      else { r.coded_category = chosen; r.suggested_category = chosen; }
      done += 1;
    } catch (e) {
      failed.push(`${r.merchant || r.id}: ${e.message}`);
    }
  }
  if (failed.length) {
    SEL.clear();
    await load();
    notify(`${done} updated. ${failed.length} could not be:<br><br>`
           + failed.slice(0, 5).map(esc).join('<br>'), 'Partly done', {html: true});
    return;
  }
  if (alsoAdd) {
    // Straight on: the rows already carry the new value, the selection is
    // intact, and the choice was made on the previous screen.
    return bulkAdd({confirm: false});
  }
  SEL.clear();
  await load();
  flash(done === 1 ? `${label} updated` : `${label} updated on ${done}`);
}

// A one-off searchable list, reusing the cell picker's shape.
// Picking from a list, with the choice confirmed rather than acted on the
// instant a row is clicked. `opts.confirmLabel` names the go button, and
// `opts.back` adds a Go Back that resolves to the string 'back' -- which is how
// a two-step flow lets someone return to the first question instead of
// canceling out of both.
//
// Resolves to: the chosen string, 'back', or null for cancel.
// One line of text, asked for the way everything else in the app asks.
// `withKind` may be true (the Bank / Credit Card pair this was written for) or
// a list of [value, label] pairs. A chart-of-accounts entry needs the expense
// side of the chart, and a fixed two-option list silently created every one of
// them as a bank account.
function askForText(title, body, placeholder = '', value = '', withKind = false,
                    parents = null) {
  return new Promise(resolve => {
    const box = $('#asktext');
    $('#askTextTitle').textContent = title;
    $('#askTextBody').textContent = body || '';
    $('#askTextBody').style.display = body ? '' : 'none';
    $('#askTextKindWrap').style.display = withKind ? '' : 'none';
    // The markup no longer hard-codes Bank / Credit Card, so the list is always
    // supplied here -- otherwise a caller passing `true` would open an empty
    // dropdown.
    const _kinds = Array.isArray(withKind) ? withKind
      : [['Bank', 'Bank Account'], ['Credit Card', 'Credit Card']];
    if (withKind) {
      $('#askTextKind').innerHTML = _kinds.map(
        ([v, label]) => `<option value="${esc(v)}">${esc(label)}</option>`).join('');
    }
    // The parent list, when one is offered. Filtered live by the chosen type,
    // because a sub-account must match its parent and offering the others only
    // produces a refusal from QuickBooks a moment later.
    const pw = $('#askTextParentWrap');
    const psel = $('#askTextParent');
    // Shown whenever the caller offers the choice at all -- not only when the
    // filtered list has entries. Hidden on an empty list, a type with no
    // existing accounts made the whole row vanish, which reads as the feature
    // being absent rather than as "nothing to nest under yet".
    if (parents) {
      const fill = () => {
        const want = $('#askTextKind').value;
        const match = parents.filter(p => !want || (p.account_type || '') === want);
        // If nothing matches the chosen type, offer the rest WITH their type
        // shown rather than an empty list. A dropdown holding only "None" is
        // indistinguishable from a broken one, and the reason it is empty --
        // no existing account of this type -- is worth saying out loud.
        const list = match.length ? match : parents;
        psel.innerHTML = '<option value="">None</option>'
          + list.map(p => `<option value="${esc(p.qbo_id)}"${
              match.length ? '' : ' disabled'}>${esc(p.name)}${
              match.length ? '' : `  (${esc(p.account_type || 'no type')})`
            }</option>`).join('')
          + (parents.length ? '' :
             '<option value="" disabled>— no accounts to nest under yet —</option>');
      };
      fill();
      $('#askTextKind').onchange = fill;
      pw.style.display = '';
    } else if (pw) {
      pw.style.display = 'none';
    }
    const input = $('#askTextInput');
    input.placeholder = placeholder;
    input.value = value;
    const done = v => { box.close(); resolve(v); };
    $('#askTextOk').onclick = () => {
      const name = input.value.trim();
      if (!name) return;
      // The parent travels back with the rest, so the caller does not have to
      // read a dialog element it did not open.
      done(withKind ? {name, kind: $('#askTextKind').value,
                       parent: ($('#askTextParent') || {}).value || ''} : name);
    };
    $('#askTextCancel').onclick = () => done(null);
    input.onkeydown = e => { if (e.key === 'Enter') $('#askTextOk').click(); };
    box.showModal();
    setTimeout(() => input.focus(), 0);
  });
}

function pickFromList(title, list, opts = {}) {
  return new Promise(resolve => {
    const box = $('#listpick');
    $('#listpickTitle').textContent = title;
    const search = $('#listpickSearch');
    search.value = '';
    let chosen = null;

    const go = $('#listpickGo');
    go.textContent = opts.confirmLabel || 'Select';
    go.disabled = true;
    $('#listpickBack').style.display = opts.back ? '' : 'none';

    const draw = needle => {
      const n = needle.trim().toLowerCase();
      const hits = list.filter(x => !n || x.toLowerCase().includes(n)).slice(0, 300);
      $('#listpickList').innerHTML = hits.length
        ? hits.map(x => `<div class="cp-o${x === chosen ? ' on' : ''}">${esc(x)}</div>`).join('')
        : `<div class="cp-empty">Nothing matches “${esc(needle)}”</div>`;
      $('#listpickList').querySelectorAll('.cp-o').forEach(o => o.onclick = () => {
        // Selects, and waits. Closing on the first click meant a mis-click was
        // a decision, with the dialog already gone.
        chosen = o.textContent;
        go.disabled = false;
        $('#listpickList').querySelectorAll('.cp-o')
          .forEach(x => x.classList.toggle('on', x === o));
      });
    };
    search.oninput = () => draw(search.value);
    draw('');

    const done = value => { box.close(); resolve(value); };
    go.onclick = () => { if (chosen) done(chosen); };
    $('#listpickBack').onclick = () => done('back');
    $('#listpickCancel').onclick = () => done(null);
    box.showModal();
    setTimeout(() => search.focus(), 0);
  });
}

$('#bBatch').onclick = () => {
  $('#batchN').textContent = `${SEL.size} transaction(s)`;
  // Match and Add belong to charges that are still unresolved. On Categorized
  // the work is correcting what was already posted.
  const forReview = status_ === 'for_review';
  // Two tabs, two orders. Alphabetical was fine when the list was short, but
  // Split belongs last where it is rarely wanted and third-from-top where it
  // is, and only the tab knows which.
  const excluded = status_ === 'excluded';
  const ORDER = forReview
    ? ['code', 'match', 'fields', 'release', 'split', 'exclude', 'undo']
    : excluded
    ? ['unexclude', 'purge']
    : ['fields', 'convert', 'split', 'release', 'undo', 'code', 'match'];
  const holder = document.querySelector('.batchOpt').parentElement;
  ORDER.forEach(a => {
    const el = holder.querySelector(`.batchOpt[data-a="${a}"]`);
    if (el) holder.appendChild(el);
  });
  document.querySelectorAll('.batchOpt').forEach(b => {
    const onlyReview = b.dataset.a === 'match' || b.dataset.a === 'code';
    const onlyCoded = b.dataset.a === 'undo' || b.dataset.a === 'release'
      || b.dataset.a === 'convert';
    // Release is offered only where it applies -- on charges the sweep flagged.
    // Anywhere else it is a way to lose the link to a live QuickBooks
    // transaction, which is not something to leave lying in a menu.
    const flagged = (QUEUE.items || [])
      .filter(r => SEL.has(r.id)).every(r => r.post_error);
    // Each tab lists exactly what it can do, so the menu is the same shape as
    // the row icons rather than a superset of them.
    const a = b.dataset.a;
    const hide = excluded
      ? !(a === 'unexclude' || a === 'purge')
      : (a === 'unexclude' || a === 'purge')
        || (a === 'exclude' && !forReview)
        || (onlyReview && !forReview)
        || (onlyCoded && forReview)
        || (a === 'release' && !flagged);
    b.style.display = hide ? 'none' : '';
  });
  $('#batch').showModal();
};
$('#batchCancel').onclick = () => $('#batch').close();
document.querySelectorAll('.batchOpt').forEach(b => b.onclick = async () => {
  $('#batch').close();
  const a = b.dataset.a;
  if (a === 'match') return bulkMatch();
  if (a === 'code') return bulkAdd();      // this one still confirms
  if (a === 'undo') return undoOrDelete([...SEL]);
  if (a === 'split') return splitDialog([...SEL], {percentOnly: true});
  if (a === 'release') return releaseCharges([...SEL]);
  if (a === 'exclude') return act('exclude', [...SEL]);
  if (a === 'unexclude') return undoOrDelete([...SEL]);
  if (a === 'purge') return purgeIds([...SEL]);
  if (a === 'convert') return convertPayments([...SEL]);
  if (a === 'notes') return bulkNotes([...SEL]);
  if (a === 'fields') return bulkUpdateFields([...SEL]);
  return bulkSet(a);
});

// UPDATE CUSTOM NOTES: one note on every selected transaction (blank clears
// it). A posted one's QuickBooks memo follows, the note in brackets.
async function bulkNotes(ids) {
  if (!ids.length) return;
  const note = await askForText('Update Custom Notes', `The note for ${ids.length} selected transaction(s). Leave it blank to clear it.`,
                                'Custom note', '');
  if (note === null || note === undefined) return;
  let done = 0; const failed = [];
  for (const id of ids) {
    const fd = new FormData(); fd.append('charge_id', id); fd.append('custom_note', note);
    try { await api('/queue/edit', {method: 'POST', body: fd}); done++; }
    catch (e) { failed.push(e.message); }
  }
  if (failed.length) notify(`${done} updated. ${failed.length} not:<br><br>` + failed.slice(0, 5).map(esc).join('<br>'), 'Partly done', {html: true});
  else flash(`Custom notes updated on ${done} transaction(s)`);
  await load();
}

$('#bSetVendor').onclick = () => bulkSet('vendor');
$('#bSetCategory').onclick = () => bulkSet('category');

// --- splitting one charge across categories --------------------------------
//
// Dollars are what QuickBooks receives, so they are what the dialog works in
// even when percentages are how the split was thought of. Percent mode
// converts on every keystroke and the LAST line absorbs the remainder, so the
// lines always total the charge exactly -- three equal shares of $100 are
// 33.33 / 33.33 / 33.34, not three 33.33s and a cent QuickBooks balances
// wherever it likes.
let SPLIT_STATE = null;

function splitRound(v) { return Math.round((Number(v) || 0) * 100) / 100; }

function splitRedraw() {
  const st = SPLIT_STATE;
  const pct = st.mode === 'percent';
  $('#splitLines').innerHTML = st.lines.map((ln, i) => `
    <div style="display:flex;gap:6px;align-items:center">
      <span style="width:16px;color:var(--tx2);font-size:12px">${i + 1}</span>
      <select class="spCat" data-i="${i}" style="flex:1">
        ${categoryOptions(ln.category)}
      </select>
      <input class="spVal" data-i="${i}" type="number" step="0.01"
             value="${pct ? (ln.percent ?? '') : (ln.amount ?? '')}"
             style="width:100px" placeholder="${pct ? '%' : '0.00'}">
      <span class="spDollars" data-i="${i}"
            style="width:78px;font-size:12px;color:var(--tx2);text-align:right"
        >${pct ? fmtAmt(ln.amount || 0) : ''}</span>
      <button class="ghost spDel" data-i="${i}"
              style="padding:1px 9px;font-size:16px;line-height:1;color:var(--bad);border-color:var(--line)"${st.lines.length <= 2 ? ' disabled' : ''}
        >×</button>
    </div>`).join('');

  splitRefreshTotals();

  $('#splitLines').querySelectorAll('.spCat').forEach(sel => sel.onchange = () => {
    st.lines[+sel.dataset.i].category = sel.value;
  });
  $('#splitLines').querySelectorAll('.spVal').forEach(inp => inp.oninput = () => {
    const i = +inp.dataset.i, v = Number(inp.value);
    if (st.mode === 'percent') {
      st.lines[i].percent = inp.value === '' ? null : v;
      splitFillRemainder(i, 'percent');
      splitApplyPercents();
    } else {
      st.lines[i].amount = inp.value === '' ? null : splitRound(v);
      st.lines[i].percent = null;
      splitFillRemainder(i, 'amount');
    }
    // NOT a redraw. Re-rendering the field being typed in put the caret back at
    // the start of it, because <input type="number"> has no selectionStart to
    // read and the restore failed silently -- so "12" was entered as "21".
    // Only the figures derived from the input are refreshed.
    // The other row's figure changed, so it has to be redrawn -- but not the
    // field being typed in, which would take the caret with it.
    st.lines.forEach((ln, j) => {
      if (j === i) return;
      const el = $('#splitLines').querySelector(`.spVal[data-i="${j}"]`);
      if (el && document.activeElement !== el) {
        el.value = st.mode === 'percent' ? (ln.percent ?? '') : (ln.amount ?? '');
      }
    });
    splitRefreshTotals();
  });
  $('#splitLines').querySelectorAll('.spDel').forEach(b => b.onclick = () => {
    st.lines.splice(+b.dataset.i, 1);
    if (st.mode === 'percent') splitApplyPercents();
    splitRedraw();
  });
}

// Everything on the dialog that follows from the numbers, and nothing that a
// person might currently be typing into.
function splitRefreshTotals() {
  const st = SPLIT_STATE;
  if (!st) return;
  if (st.mode === 'percent') {
    $('#splitLines').querySelectorAll('.spDollars').forEach(el => {
      const ln = st.lines[+el.dataset.i];
      el.textContent = ln ? fmtAmt(ln.amount || 0) : '';
    });
  }
  const total = st.lines.reduce((a, b) => a + (Number(b.amount) || 0), 0);
  const diff = splitRound(st.amount - total);
  const el = $('#splitSum');
  el.textContent = diff === 0
    ? `${fmtAmt(total)} of ${fmtAmt(st.amount)} — balanced`
    : `${fmtAmt(total)} of ${fmtAmt(st.amount)} — ${diff > 0 ? fmtAmt(diff)
        + ' unallocated' : fmtAmt(-diff) + ' over'}`;
  el.style.color = diff === 0 ? 'var(--ok)' : 'var(--bad)';
  // Save is only possible from a balanced split -- the server refuses an
  // unbalanced one anyway, and a button that fails is worse than one that waits.
  $('#splitSave').disabled = diff !== 0;
}

// Whatever is left over, put on the OTHER untouched lines. Typing 40 into the
// first of two rows means the second is 60 -- there is only one answer, and
// making somebody work it out and type it was busywork on every split.
//
// Only lines nobody has filled in are adjusted: once a figure has been typed
// it is the person's, and quietly rewriting it would be worse than leaving the
// arithmetic to them.
function splitFillRemainder(justEdited, mode) {
  const st = SPLIT_STATE;
  const key = mode === 'percent' ? 'percent' : 'amount';
  const whole = mode === 'percent' ? 100 : st.amount;
  // Rows the PERSON has typed in, not rows that merely hold a number. The
  // first version looked for empty rows, so it filled the second row on the
  // first keystroke and then -- the row no longer being empty -- never
  // updated it again as the first row was finished. A row this function
  // wrote is still ours to rewrite; a row somebody typed is not.
  st.lines[justEdited].touched = true;
  const free = st.lines.map((l, i) => i)
    .filter(i => i !== justEdited && !st.lines[i].touched);
  if (free.length !== 1) return;      // ambiguous with two or more to fill
  const used = st.lines.reduce(
    (a, l, i) => a + (i === free[0] ? 0 : (Number(l[key]) || 0)), 0);
  const left = splitRound(whole - used);
  st.lines[free[0]][key] = left > 0 ? left : null;
  if (mode === 'amount') st.lines[free[0]].percent = null;
}

// The last line takes the remainder, so rounding never leaves the split a cent
// short of the charge.
function splitApplyPercents() {
  const st = SPLIT_STATE;
  // Same rule as the bill split: an untouched form computes nothing.
  if (!st.lines.some(l => l.percent !== null && l.percent !== '')) {
    st.lines.forEach(l => { l.amount = null; });
    return;
  }
  let running = 0;
  st.lines.forEach((ln, i) => {
    if (i === st.lines.length - 1) {
      ln.amount = splitRound(st.amount - running);
    } else {
      ln.amount = splitRound(st.amount * (Number(ln.percent) || 0) / 100);
      running = splitRound(running + ln.amount);
    }
  });
}

async function splitDialog(ids, opts = {}) {
  const rows = (QUEUE.items || []).filter(r => ids.includes(r.id));
  if (!rows.length) return;
  const many = rows.length > 1;
  const amount = many ? 0 : Math.abs(Number(rows[0].amt) || 0);

  // Nothing is read back. The dialog is for SAYING how to split, and any
  // attempt to also show the current split meant it opened carrying values
  // nobody had just typed. What the transaction is currently split into is on
  // the row instead -- hover the Split label in the Category column.
  const existing = [];

  // Rebuilt from nothing on every open. Two blank lines unless the charge
  // actually HAS a saved split, in which case that split is the data and is
  // shown. Nothing is carried over from a previous open, and the first line is
  // no longer pre-filled with the charge's current category -- that read as the
  // dialog remembering something, and it meant a mis-click saved a split whose
  // first line nobody had chosen.
  SPLIT_STATE = {
    ids, many, amount,
    mode: (many || opts.percentOnly) ? 'percent'
          : (existing.length && existing[0].percent != null ? 'percent' : 'amount'),
    lines: existing.length
      ? existing.map(l => ({category: l.category,
                            amount: Number(l.amount),
                            percent: l.percent == null ? null : Number(l.percent)}))
      : [{category: '', amount: null, percent: null, touched: false},
         {category: '', amount: null, percent: null, touched: false}],
  };

  $('#split').querySelector('h3').textContent =
    many ? 'Split Transactions' : 'Split Transaction';
  $('#splitHead').innerHTML = many
    ? `<b>${rows.length}</b> transactions — the same percentages applied to each.`
    : `${esc(rows[0].merchant || '')} · <b>${fmtAmt(amount)}</b>`
      + (existing.length ? ` · currently split ${existing.length} ways` : '');
  // Fixed amounts make no sense across charges of different sizes.
  document.querySelectorAll('.splitMode').forEach(b => {
    b.style.display = (many && b.dataset.m === 'amount') ? 'none' : '';
    b.classList.toggle('on', b.dataset.m === SPLIT_STATE.mode);
  });
  $('#splitClear').style.display = existing.length ? '' : 'none';
  // On For Review the split and the post are one intention, so they are one
  // press: saving a split and then having to find Add All was two steps for
  // something nobody wants half of. On Categorized the charge is already in
  // QuickBooks, so saving is the whole job.
  SPLIT_STATE.alsoAdd = status_ === 'for_review';
  $('#splitSave').textContent = SPLIT_STATE.alsoAdd ? 'Split & Add' : 'Save';
  $('#splitSave').title = SPLIT_STATE.alsoAdd
    ? 'Saves the split and posts the transaction to QuickBooks' : '';
  if (SPLIT_STATE.mode === 'percent') splitApplyPercents();
  splitRedraw();
  $('#split').showModal();
}

document.querySelectorAll('.splitMode').forEach(b => b.onclick = () => {
  SPLIT_STATE.mode = b.dataset.m;
  document.querySelectorAll('.splitMode').forEach(
    x => x.classList.toggle('on', x === b));
  if (SPLIT_STATE.mode === 'percent') splitApplyPercents();
  splitRedraw();
});
$('#splitAdd').onclick = () => {
  SPLIT_STATE.lines.push({category: '', amount: null, percent: null,
                          touched: false});
  if (SPLIT_STATE.mode === 'percent') splitApplyPercents();
  splitRedraw();
};
$('#splitEven').onclick = () => {
  const n = SPLIT_STATE.lines.length;
  const share = Math.floor((100 / n) * 10000) / 10000;
  SPLIT_STATE.lines.forEach((ln, i) => {
    ln.percent = i === n - 1 ? splitRound(100 - share * (n - 1)) : share;
  });
  SPLIT_STATE.mode = 'percent';
  document.querySelectorAll('.splitMode').forEach(
    x => x.classList.toggle('on', x.dataset.m === 'percent'));
  splitApplyPercents();
  splitRedraw();
};
// Closing by any route -- Cancel, Escape, the backdrop -- drops the state, so
// the next open cannot inherit it.
$('#splitCancel').onclick = () => $('#split').close();
$('#split').addEventListener('close', () => { SPLIT_STATE = null; });
$('#billsplit').addEventListener('close', () => { BS = null; });

async function splitPost(id, lines) {
  const fd = new FormData();
  fd.append('charge_id', id);
  fd.append('payload', JSON.stringify(lines));
  return api('/queue/split', {method: 'POST', body: fd});
}

$('#splitClear').onclick = async () => {
  const ids = SPLIT_STATE.ids;
  $('#split').close();
  try {
    for (const id of ids) await splitPost(id, []);
    flash('Split removed');
    SEL.clear();
    await load();
  } catch (e) { notify(e.message, 'Could not remove the split'); }
};

$('#splitSave').onclick = async () => {
  const st = SPLIT_STATE;
  if (st.lines.some(l => !l.category)) {
    notify('Every line needs a category.', 'Not saved');
    return;
  }
  const rows = (QUEUE.items || []).filter(r => st.ids.includes(r.id));
  $('#split').close();
  const failed = [];
  for (const r of rows) {
    // Per charge, because the percentages resolve to different dollars on each
    // and the remainder has to land on that charge's last line.
    const amt = Math.abs(Number(r.amt) || 0);
    let running = 0;
    const lines = st.lines.map((ln, i) => {
      const value = st.mode === 'percent'
        ? (i === st.lines.length - 1 ? splitRound(amt - running)
           : splitRound(amt * (Number(ln.percent) || 0) / 100))
        : ln.amount;
      if (i < st.lines.length - 1) running = splitRound(running + value);
      return {category: ln.category, amount: value,
              percent: st.mode === 'percent' ? ln.percent : null};
    });
    try { await splitPost(r.id, lines); }
    catch (e) { failed.push(`${r.merchant || r.id}: ${e.message}`); }
  }
  const alsoAdd = st.alsoAdd;
  const ok = rows.filter(r => !failed.some(f => f.startsWith(`${r.merchant || r.id}:`)))
                 .map(r => r.id);
  SPLIT_STATE = null;
  if (failed.length) {
    SEL.clear();
    await load();
    notify(`${rows.length - failed.length} split. ${failed.length} could not be:`
           + `<br><br>${failed.slice(0, 5).map(esc).join('<br>')}`, 'Partly done');
    return;
  }
  if (alsoAdd && ok.length) {
    // ONE reload, at the end. This used to reload, populate the selection, then
    // call bulkAdd -- which reloads again, and act() inside it reloads once
    // more. Three renders for one button, which is what the flashing was.
    //
    // Everything needed is already here: the category is the split's first
    // line, and the vendor is on the row. Nothing has to be read back to know
    // them, so the intermediate reloads bought nothing.
    const byPair = new Map();
    ok.forEach(id => {
      const row = rows.find(r => r.id === id);
      const cat = st.lines[0].category;
      const ven = vendorCell(row).trim();
      const key = cat + '\u0000' + ven;
      if (!byPair.has(key)) byPair.set(key, {cat, ven, ids: []});
      byPair.get(key).ids.push(id);
    });
    for (const g of byPair.values()) {
      const fd = new FormData();
      fd.append('ids', g.ids.join(','));
      fd.append('action', 'code');
      fd.append('category', g.cat);
      fd.append('vendor', g.ven);
      try { await api('/queue/resolve', {method: 'POST', body: fd}); }
      catch (e) { failed.push(`${g.ids.length} transaction(s): ${e.message}`); }
    }
    SEL.clear();
    await load();
    if (failed.length) {
      notify(failed.slice(0, 5).map(esc).join('<br>'), 'Partly done',
             {html: true});
    } else {
      flash(ok.length === 1 ? 'Split and added'
                            : `${ok.length} transactions split and added`);
    }
    return;
  }
  SEL.clear();
  await load();
  flash(rows.length === 1 ? 'Transaction split' : `${rows.length} transactions split`);
};

async function convertPayments(ids) {
  const rows = (QUEUE.items || []).filter(r => ids.includes(r.id));
  const payments = rows.filter(r => r.resolution === 'matched');
  if (!payments.length) {
    notify('None of the selected transactions are bill payments.',
           'Nothing to convert');
    return;
  }
  // The category is asked for once and applied to all of them -- the same
  // question Update Category asks, so it uses the same picker.
  // Vendor first, then category -- two questions rather than one dialog that
  // asked for a category and silently kept whatever vendor was on each row.
  // A converted expense needs both, and they are different decisions.
  // Two questions with a way back between them, rather than two dialogs that
  // each closed the moment something was clicked.
  let ven = null, cat = null;
  for (;;) {
    ven = await pickFromList(
      `Vendor for ${payments.length} converted expense(s)`,
      VENDORS.map(v => v.name || v), {confirmLabel: 'Next'});
    if (!ven) return;
    cat = await pickFromList(
      `Category for ${payments.length} converted expense(s)`,
      CATEGORIES.map(c => c.fully_qualified || c.name),
      {confirmLabel: 'Next', back: true});
    if (cat === 'back') continue;      // straight back to the vendor question
    if (!cat) return;
    break;
  }
  const skipped = rows.length - payments.length;
  const go = await askConfirm('Convert bill payments',
    `Convert <b>${payments.length}</b> bill payment(s) to expenses?`
    + `<br><br>Vendor <b>${esc(ven)}</b>, category <b>${esc(cat)}</b>.`
    + `<br><br>Each payment is deleted from QuickBooks, which puts its bill `
    + `back on the books, and an expense is created in its place.`
    + (skipped ? `<br><br><b>${skipped}</b> already coded and will be skipped.` : ''),
    'Convert', 'Cancel', {goGreen: true});
  if (!go) return;
  const fd = new FormData();
  fd.append('ids', payments.map(r => r.id).join(','));
  fd.append('category', cat);
  fd.append('vendor', ven);
  try {
    const r = await api('/queue/convert-to-expense', {method: 'POST', body: fd});
    SEL.clear();
    await load();
    const trouble = (r.failed || []).concat(r.skipped || []);
    if (trouble.length) {
      notify(`${r.converted} converted. ${trouble.length} not:<br><br>`
             + trouble.slice(0, 6).map(esc).join('<br>'), 'Partly done',
             {html: true});
    } else {
      flash(`${r.converted} converted to expenses`);
    }
  } catch (e) { notify(e.message, 'Could not convert'); }
}

async function releaseCharges(ids) {
  const go = await askConfirm('Return to For Review',
    `Release <b>${ids.length}</b> charge(s) from their QuickBooks record?`
    + `<br><br>Nothing is written to QuickBooks — this only lets go of a `
    + `transaction that is no longer there. If the payment DOES still exist in `
    + `QuickBooks, use Undo instead, which removes it properly.`,
    'Release them', 'Cancel');
  if (!go) return;
  let done = 0;
  const failed = [];
  for (const id of ids) {
    const fd = new FormData();
    fd.append('charge_id', id);
    try { await api('/queue/release', {method: 'POST', body: fd}); done += 1; }
    catch (e) { failed.push(`${id}: ${e.message}`); }
  }
  SEL.clear();
  await load();
  if (failed.length) {
    notify(`${done} released. ${failed.length} could not be:<br><br>`
           + failed.slice(0, 5).map(esc).join('<br>'), 'Partly done', {html: true});
  } else {
    flash(done === 1 ? 'Returned to For Review' : `${done} returned to For Review`);
  }
}

$('#bSplit').onclick = () => splitDialog([...SEL]);

