// The confirmation is the point: on Categorized this reaches into QuickBooks
// and removes the transaction, and a mis-click on a batch is expensive.
// Unexcluding is not destructive, so it goes straight through.
async function undoOrDelete(ids) {
  if (status_ === 'excluded') {
    const back = await askConfirm('Return to For Review',
      `Put <b>${ids.length}</b> transaction(s) back into For Review?`,
      'Unexclude', 'Cancel');
    if (!back) return;
    return act('undo', ids);
  }
  // THE QUESTION IS THE TITLE; no subtext.
  const go = await askConfirm(ids.length === 1 ? 'Delete this transaction?' : `Delete ${ids.length} transactions?`,
    '', 'Delete', 'Go Back');
  if (!go) return;
  return act('undo', ids);
}
$('#bUndo').onclick = () => undoOrDelete([...SEL]);

