// The filter fields use the SAME picker as the grid cells -- searchable, with
// Clear at the top -- rather than a free-text box with a datalist. Two controls
// for one job taught people the list was optional here.
document.querySelectorAll('.filterpick').forEach(btn => btn.onclick = e => {
  e.stopPropagation();
  const hidden = $('#' + btn.dataset.target);
  const kind = btn.dataset.kind;
  // ONE CONTROL FOR EVERY FILTER FIELD.
  //
  // The audit dialog used to have two kinds of picker side by side: this one
  // for vendor and category, and a bespoke button-plus-hidden-menu for action
  // group, action, user and card account. They looked different, behaved
  // differently, and the second kind was the one that went missing. There is
  // one now, and its options come from here.
  const list = kind === 'vendor'
    ? VENDORS.map(v => v.name || v)
    : kind === 'category'
    ? CATEGORIES.map(c => c.fully_qualified || c.name)
    : (AUDIT_OPTS[{auditgroup: 'group', auditaction: 'action',
                   auditactor: 'actor', auditcard: 'card'}[kind]] || [])
        .map(o => o[1]);
  // SEVERAL, not one.
  //
  // Picking a vendor replaced the last one, so "the three Broadway venues" was
  // three separate looks at the grid. Each pick now ADDS to the list, and the
  // same pick again removes it -- the value is comma separated, which the
  // server splits.
  const current = (hidden.value || '').split(',')
    .map(t => t.trim()).filter(Boolean);
  btn.dataset.value = current[current.length - 1] || '';
  const paint = () => {
    const now = (hidden.value || '').split(',').map(t => t.trim()).filter(Boolean);
    btn.querySelector('.cs-v').innerHTML = now.length === 0
      ? `<i style="color:var(--tx2)">Any ${kind}</i>`
      : now.length === 1 ? esc(now[0])
      // The count rather than the names: three full account paths do not fit
      // in a filter box, and a truncated list reads as one wrong value.
      : esc(`${now.length} ${kind}s selected`);
    btn.title = now.join('\n');
  };
  openPicker(btn, {
    list: () => list,
    canCreate: '',
    multi: true,
    chosen: () => (hidden.value || '').split(',')
      .map(t => t.trim()).filter(Boolean),
    onPick: chosen => {
      const now = (hidden.value || '').split(',')
        .map(t => t.trim()).filter(Boolean);
      if (!chosen) {
        hidden.value = '';            // "clear" from the picker means clear
      } else if (now.includes(chosen)) {
        hidden.value = now.filter(t => t !== chosen).join(', ');
      } else {
        hidden.value = now.concat(chosen).join(', ');
      }
      paint();
    },
  });
});

